-- ============================================================================
CREATE TABLE reference.type_matchups (
    attacking_type_id integer NOT NULL REFERENCES reference.types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    defending_type_id integer NOT NULL REFERENCES reference.types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    generation_start_id integer NOT NULL REFERENCES reference.generations (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    multiplier_numerator integer NOT NULL,
    multiplier_denominator integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT type_matchups_primary_key PRIMARY KEY (attacking_type_id, defending_type_id, generation_start_id),
    CONSTRAINT type_matchups_multiplier_check CHECK ((multiplier_numerator, multiplier_denominator) IN ((0, 1), (1, 2), (1, 1), (2, 1)))
);

CREATE INDEX type_matchups_defending_generation_idx ON reference.type_matchups (defending_type_id, generation_start_id);

COMMENT ON TABLE reference.type_matchups IS 'Type effectiveness rows stored by generation change point for historic team analysis.';

COMMENT ON COLUMN reference.type_matchups.multiplier_numerator IS 'Exact rational multiplier numerator, e.g. 1 for 1/2x or 2 for 2x.';

COMMENT ON COLUMN reference.type_matchups.multiplier_denominator IS 'Exact rational multiplier denominator, e.g. 2 for 1/2x or 1 for 2x.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/011_natures.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.natures
-- Pokémon nature definitions.
-- ============================================================================
CREATE TABLE reference.natures (
    id integer PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    name text NOT NULL UNIQUE,
    introduced_generation_id integer NOT NULL REFERENCES reference.generations (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    increased_stat text,
    decreased_stat text,
    sort_order integer NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT natures_id_positive_check CHECK (id > 0),
    CONSTRAINT natures_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 80),
    CONSTRAINT natures_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 80),
    CONSTRAINT natures_increased_stat_check CHECK (increased_stat IS NULL OR increased_stat IN ('attack', 'defense', 'special_attack', 'special_defense', 'speed')),
    CONSTRAINT natures_decreased_stat_check CHECK (decreased_stat IS NULL OR decreased_stat IN ('attack', 'defense', 'special_attack', 'special_defense', 'speed')),
    CONSTRAINT natures_stat_pair_check CHECK ((increased_stat IS NULL AND decreased_stat IS NULL) OR (increased_stat IS NOT NULL AND decreased_stat IS NOT NULL AND increased_stat <> decreased_stat)),
    CONSTRAINT natures_sort_order_positive_check CHECK (sort_order > 0)
);

COMMENT ON TABLE reference.natures IS 'Pokémon natures and their stat modifiers. Neutral natures use null modifier fields.';

