    CONSTRAINT egg_groups_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 80),
    CONSTRAINT egg_groups_sort_order_positive_check CHECK (sort_order > 0)
);

