-- ============================================================================
-- Source: database/schema/02_reference/01_tables/021_pokemon_form_rules.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.pokemon_form_rules
-- Form behavior metadata for team builder, planning, and display.
-- ============================================================================
CREATE TABLE reference.pokemon_form_rules (
    form_id integer PRIMARY KEY REFERENCES reference.pokemon_forms (id) ON UPDATE CASCADE ON DELETE CASCADE,
    form_class text NOT NULL,
    is_team_selectable boolean NOT NULL DEFAULT TRUE,
    is_battle_only boolean NOT NULL DEFAULT FALSE,
    is_cosmetic boolean NOT NULL DEFAULT FALSE,
    is_regional boolean NOT NULL DEFAULT FALSE,
    is_evolution_locked boolean NOT NULL DEFAULT FALSE,
    battle_mechanic text,
    condition_summary text,
    notes text,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT pokemon_form_rules_form_class_check CHECK (form_class IN ('variant', 'form', 'battle')),
    CONSTRAINT pokemon_form_rules_battle_class_check CHECK ((form_class = 'battle') = is_battle_only),
    CONSTRAINT pokemon_form_rules_battle_not_team_selectable_check CHECK (NOT is_battle_only OR NOT is_team_selectable),
    CONSTRAINT pokemon_form_rules_battle_mechanic_check CHECK (battle_mechanic IS NULL OR battle_mechanic IN ('mega-evolution', 'primal-reversion', 'ultra-burst', 'dynamax', 'in-battle')),
    CONSTRAINT pokemon_form_rules_battle_mechanic_presence_check CHECK ((battle_mechanic IS NOT NULL) = is_battle_only),
    CONSTRAINT pokemon_form_rules_condition_summary_length_check CHECK (condition_summary IS NULL OR CHAR_LENGTH(BTRIM(condition_summary)) BETWEEN 1 AND 500),
    CONSTRAINT pokemon_form_rules_notes_length_check CHECK (notes IS NULL OR CHAR_LENGTH(BTRIM(notes)) BETWEEN 1 AND 1000)
);

COMMENT ON TABLE reference.pokemon_form_rules IS 'UI and planning behavior metadata for Pokémon forms.';

COMMENT ON COLUMN reference.pokemon_form_rules.form_class IS 'variant: a different Pokémon you catch and keep, chosen when it is added (Hisuian Arcanine). form: one the Pokémon can switch to and back on a Play (Rotom, Therian Formes, Arceus types). battle: only in battle (Mega, Gigantamax). A default form has no rule row.';

COMMENT ON COLUMN reference.pokemon_form_rules.battle_mechanic IS 'Battle forms only: the mechanic that reaches the form, so it shows only in games that have it. in-battle means an ability, move or held item changes it during any battle in a game with the Pokémon.';

CREATE FUNCTION private.enforce_storable_pokemon_form ()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path = ''
    AS $$
DECLARE
    v_form_id integer := (TO_JSONB (NEW) ->> TG_ARGV[0])::integer;
BEGIN
    IF EXISTS (
        SELECT
            1
        FROM
            reference.pokemon_form_rules
        WHERE
            pokemon_form_rules.form_id = v_form_id
            AND NOT pokemon_form_rules.is_team_selectable) THEN
    RAISE EXCEPTION 'Form % is a battle form and cannot be a Pokémon''s stored form', v_form_id
        USING ERRCODE = '23514';
END IF;
    RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION private.enforce_storable_pokemon_form () FROM PUBLIC;

REVOKE ALL ON FUNCTION private.enforce_storable_pokemon_form () FROM anon;

REVOKE ALL ON FUNCTION private.enforce_storable_pokemon_form () FROM authenticated;

GRANT EXECUTE ON FUNCTION private.enforce_storable_pokemon_form () TO service_role;

COMMENT ON FUNCTION private.enforce_storable_pokemon_form () IS 'Refuses a form that is not team selectable, such as a Mega or Gigantamax form, on a row that stores a Pokémon''s identity. TG_ARGV[0] names the form column.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/022_pokemon_form_item_requirements.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.pokemon_form_item_requirements
-- Item relationships that select, maintain, or explain Pokémon forms.
-- ============================================================================
CREATE TABLE reference.pokemon_form_item_requirements (
    form_id integer NOT NULL REFERENCES reference.pokemon_forms (id) ON UPDATE CASCADE ON DELETE CASCADE,
    item_id integer NOT NULL REFERENCES reference.items (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    generation_start_id integer NOT NULL REFERENCES reference.generations (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    generation_end_id integer REFERENCES reference.generations (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    version_group_start_id integer REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    version_group_end_id integer REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    requirement_kind text NOT NULL,
    type_effect_scope text,
    type_id integer REFERENCES reference.types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    notes text,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT pokemon_form_item_requirements_primary_key PRIMARY KEY (form_id, item_id, generation_start_id),
    CONSTRAINT pokemon_form_item_requirements_generation_range_check CHECK (generation_end_id IS NULL OR generation_end_id >= generation_start_id),
    CONSTRAINT pokemon_form_item_requirements_version_group_range_check CHECK (version_group_end_id IS NULL OR version_group_start_id IS NULL OR version_group_end_id >= version_group_start_id),
    CONSTRAINT pokemon_form_item_requirements_kind_check CHECK (requirement_kind IN ('required_held_item', 'alternative_held_item', 'form_change_item')),
    CONSTRAINT pokemon_form_item_requirements_type_effect_scope_check CHECK (type_effect_scope IS NULL OR type_effect_scope IN ('form_type', 'secondary_type', 'signature_move_type')),
    CONSTRAINT pokemon_form_item_requirements_type_effect_pair_check CHECK ((type_effect_scope IS NULL AND type_id IS NULL) OR (type_effect_scope IS NOT NULL AND type_id IS NOT NULL)),
    CONSTRAINT pokemon_form_item_requirements_notes_length_check CHECK (notes IS NULL OR CHAR_LENGTH(BTRIM(notes)) BETWEEN 1 AND 1000)
);

CREATE INDEX pokemon_form_item_requirements_item_generation_idx ON reference.pokemon_form_item_requirements (item_id, generation_start_id, generation_end_id, version_group_start_id, version_group_end_id, form_id);

COMMENT ON TABLE reference.pokemon_form_item_requirements IS 'Item-driven form selection, held-item requirements, and type/move effects for Pokémon forms.';

COMMENT ON COLUMN reference.pokemon_form_item_requirements.generation_end_id IS 'Optional last generation where this item-form rule applies. NULL means no known end generation.';

COMMENT ON COLUMN reference.pokemon_form_item_requirements.version_group_start_id IS 'Optional first version group/content scope where this item-form rule applies when generation boundaries are not precise enough.';

COMMENT ON COLUMN reference.pokemon_form_item_requirements.version_group_end_id IS 'Optional last version group/content scope where this item-form rule applies when generation boundaries are not precise enough.';

COMMENT ON COLUMN reference.pokemon_form_item_requirements.requirement_kind IS 'required_held_item means the item must be held; alternative_held_item means one of several held items can select the form; form_change_item means the item changes form without being held.';

COMMENT ON COLUMN reference.pokemon_form_item_requirements.type_effect_scope IS 'Optional meaning of type_id: Pokémon form type, secondary type added by the item/form, or signature move type.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/023_pokemon_attributes.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.pokemon_attributes
-- Generation-aware Pokémon form mechanics and base stats.
-- ============================================================================
CREATE TABLE reference.pokemon_attributes (
    species_id integer NOT NULL,
    form_id integer NOT NULL,
    generation_start_id integer NOT NULL REFERENCES reference.generations (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    primary_type_id integer NOT NULL REFERENCES reference.types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    secondary_type_id integer REFERENCES reference.types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    primary_ability_id integer REFERENCES reference.abilities (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    secondary_ability_id integer REFERENCES reference.abilities (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    hidden_ability_id integer REFERENCES reference.abilities (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    primary_egg_group_id integer REFERENCES reference.egg_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    secondary_egg_group_id integer REFERENCES reference.egg_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    base_hp integer NOT NULL,
    base_attack integer NOT NULL,
    base_defense integer NOT NULL,
    base_special_attack integer NOT NULL,
    base_special_defense integer NOT NULL,
    base_speed integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT pokemon_attributes_primary_key PRIMARY KEY (species_id, form_id, generation_start_id),
    CONSTRAINT pokemon_attributes_form_fkey FOREIGN KEY (species_id, form_id) REFERENCES reference.pokemon_forms (species_id, id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT pokemon_attributes_type_distinct_check CHECK (secondary_type_id IS NULL OR secondary_type_id <> primary_type_id),
    CONSTRAINT pokemon_attributes_ability_presence_check CHECK ((secondary_ability_id IS NULL OR primary_ability_id IS NOT NULL) AND (hidden_ability_id IS NULL OR primary_ability_id IS NOT NULL)),
    CONSTRAINT pokemon_attributes_ability_distinct_check CHECK ((secondary_ability_id IS NULL OR primary_ability_id IS NULL OR secondary_ability_id <> primary_ability_id) AND (hidden_ability_id IS NULL OR primary_ability_id IS NULL OR hidden_ability_id <> primary_ability_id) AND (hidden_ability_id IS NULL OR secondary_ability_id IS NULL OR hidden_ability_id <> secondary_ability_id)),
    CONSTRAINT pokemon_attributes_egg_group_presence_check CHECK (secondary_egg_group_id IS NULL OR primary_egg_group_id IS NOT NULL),
    CONSTRAINT pokemon_attributes_egg_group_distinct_check CHECK (secondary_egg_group_id IS NULL OR secondary_egg_group_id <> primary_egg_group_id),
    CONSTRAINT pokemon_attributes_egg_group_generation_check CHECK ((generation_start_id = 1 AND primary_egg_group_id IS NULL AND secondary_egg_group_id IS NULL) OR (generation_start_id >= 2 AND primary_egg_group_id IS NOT NULL)),
    CONSTRAINT pokemon_attributes_ability_generation_check CHECK ((generation_start_id < 3 AND primary_ability_id IS NULL AND secondary_ability_id IS NULL AND hidden_ability_id IS NULL) OR (generation_start_id >= 3 AND primary_ability_id IS NOT NULL AND (generation_start_id >= 5 OR hidden_ability_id IS NULL)) OR (generation_start_id >= 9 AND primary_ability_id IS NULL AND secondary_ability_id IS NULL AND hidden_ability_id IS NULL)),
    CONSTRAINT pokemon_attributes_base_stats_check CHECK (base_hp BETWEEN 1 AND 255 AND base_attack BETWEEN 1 AND 255 AND base_defense BETWEEN 1 AND 255 AND base_special_attack BETWEEN 1 AND 255 AND base_special_defense BETWEEN 1 AND 255 AND base_speed BETWEEN 1 AND 255)
);

COMMENT ON TABLE reference.pokemon_attributes IS 'Pokémon form types, abilities, egg groups, and base stats by generation change point.';

COMMENT ON COLUMN reference.pokemon_attributes.generation_start_id IS 'First generation where this mechanics row applies.';

COMMENT ON COLUMN reference.pokemon_attributes.primary_ability_id IS 'Required from Generation III. NULL from Generation IX only for a form that has no ability in its games, such as a Mega introduced in Legends: Z-A, which has no abilities.';

-- ============================================================================
