-- Source: database/schema/02_reference/01_tables/028_pokemon_evolution_edges.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.pokemon_evolution_edges
-- Evolution relationships between Pokémon species/forms.
-- ============================================================================
CREATE TABLE reference.pokemon_evolution_edges (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    from_species_id integer NOT NULL,
    from_form_id integer NOT NULL,
    to_species_id integer NOT NULL,
    to_form_id integer NOT NULL,
    version_group_id integer REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    introduced_generation_id integer NOT NULL REFERENCES reference.generations (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    evolution_method_id integer NOT NULL REFERENCES reference.evolution_methods (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    minimum_level integer,
    item_id integer REFERENCES reference.items (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    held_item_id integer REFERENCES reference.items (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    known_move_id integer REFERENCES reference.moves (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    known_type_id integer REFERENCES reference.types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    gender text,
    time_of_day text,
    location_label text,
    condition_summary text,
    condition_data jsonb,
    sort_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT pokemon_evolution_edges_id_positive_check CHECK (id > 0),
    CONSTRAINT pokemon_evolution_edges_from_form_fkey FOREIGN KEY (from_species_id, from_form_id) REFERENCES reference.pokemon_forms (species_id, id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT pokemon_evolution_edges_to_form_fkey FOREIGN KEY (to_species_id, to_form_id) REFERENCES reference.pokemon_forms (species_id, id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT pokemon_evolution_edges_not_self_check CHECK (from_species_id <> to_species_id OR from_form_id <> to_form_id),
    CONSTRAINT pokemon_evolution_edges_minimum_level_check CHECK (minimum_level IS NULL OR minimum_level BETWEEN 1 AND 100),
    CONSTRAINT pokemon_evolution_edges_gender_check CHECK (gender IS NULL OR gender IN ('male', 'female')),
    CONSTRAINT pokemon_evolution_edges_time_of_day_length_check CHECK (time_of_day IS NULL OR CHAR_LENGTH(BTRIM(time_of_day)) BETWEEN 1 AND 80),
    CONSTRAINT pokemon_evolution_edges_location_label_length_check CHECK (location_label IS NULL OR CHAR_LENGTH(BTRIM(location_label)) BETWEEN 1 AND 200),
    CONSTRAINT pokemon_evolution_edges_condition_summary_length_check CHECK (condition_summary IS NULL OR CHAR_LENGTH(BTRIM(condition_summary)) BETWEEN 1 AND 500),
    CONSTRAINT pokemon_evolution_edges_condition_data_object_check CHECK (condition_data IS NULL OR JSONB_TYPEOF(condition_data) = 'object'),
    CONSTRAINT pokemon_evolution_edges_sort_order_positive_check CHECK (sort_order > 0)
);

CREATE UNIQUE INDEX pokemon_evolution_edges_natural_unique ON reference.pokemon_evolution_edges (from_species_id, from_form_id, to_species_id, to_form_id, (COALESCE(version_group_id, 0)), introduced_generation_id, evolution_method_id, (COALESCE(minimum_level, 0)), (COALESCE(item_id, 0)), (COALESCE(held_item_id, 0)), (COALESCE(known_move_id, 0)), (COALESCE(known_type_id, 0)), (COALESCE(gender, '')), (COALESCE(time_of_day, '')), (COALESCE(location_label, '')), (COALESCE(condition_data::text, '{}')));

COMMENT ON INDEX reference.pokemon_evolution_edges_natural_unique IS 'Prevents duplicate evolution edges for the same form pair, scope, method, requirements, and structured mechanic data.';

COMMENT ON COLUMN reference.pokemon_evolution_edges.id IS 'Generated surrogate key for Supabase/client ergonomics; seed files omit id and rely on natural uniqueness constraints.';

COMMENT ON TABLE reference.pokemon_evolution_edges IS 'Version-aware evolution edges between Pokémon species/forms for team evolution actions and planning.';

COMMENT ON COLUMN reference.pokemon_evolution_edges.version_group_id IS 'Nullable when the edge is broadly applicable across version groups.';

COMMENT ON COLUMN reference.pokemon_evolution_edges.condition_data IS 'Structured details for hard-to-model evolution edge cases.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/029_game_content_scopes.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.game_content_scopes
-- Maps games to their base and optional content scopes.
-- ============================================================================
CREATE TABLE reference.game_content_scopes (
    game_id integer NOT NULL REFERENCES reference.games (id) ON UPDATE CASCADE ON DELETE CASCADE,
    version_group_id integer NOT NULL REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    is_base_scope boolean NOT NULL DEFAULT FALSE,
    sort_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT game_content_scopes_primary_key PRIMARY KEY (game_id, version_group_id),
    CONSTRAINT game_content_scopes_sort_order_positive_check CHECK (sort_order > 0),
    CONSTRAINT game_content_scopes_game_sort_order_unique UNIQUE (game_id, sort_order)
);

CREATE UNIQUE INDEX game_content_scopes_one_base_scope_per_game_unique ON reference.game_content_scopes (game_id)
WHERE
    is_base_scope;

COMMENT ON TABLE reference.game_content_scopes IS 'Maps each game to the version-group content scopes that can apply to it, including optional DLC scopes.';

COMMENT ON COLUMN reference.game_content_scopes.is_base_scope IS 'True for the game base version group. Optional content such as DLC uses false.';

CREATE FUNCTION private.enforce_game_content_scope_base ()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SET search_path = ''
    AS $$
DECLARE
    expected_base_version_group_id integer;
    scope_parent_version_group_id integer;
BEGIN
    SELECT
        games.version_group_id
    INTO
        expected_base_version_group_id
    FROM
        reference.games
    WHERE
        games.id = NEW.game_id;
    IF expected_base_version_group_id IS NULL THEN
        RAISE EXCEPTION 'Game content scope references unknown game_id %', NEW.game_id
            USING ERRCODE = '23503';
    END IF;
    IF NEW.is_base_scope AND NEW.version_group_id <> expected_base_version_group_id THEN
        RAISE EXCEPTION 'Base content scope for game_id % must use version_group_id %, got %', NEW.game_id, expected_base_version_group_id, NEW.version_group_id
            USING ERRCODE = '23514';
    END IF;
    IF NOT NEW.is_base_scope AND NEW.version_group_id = expected_base_version_group_id THEN
        RAISE EXCEPTION 'Base version_group_id % for game_id % must be marked as the base scope', NEW.version_group_id, NEW.game_id
            USING ERRCODE = '23514';
    END IF;
    IF NOT NEW.is_base_scope THEN
        SELECT
            version_groups.parent_version_group_id
        INTO
            scope_parent_version_group_id
        FROM
            reference.version_groups
        WHERE
            version_groups.id = NEW.version_group_id;
        IF scope_parent_version_group_id IS DISTINCT FROM expected_base_version_group_id THEN
            RAISE EXCEPTION 'Optional content scope version_group_id % for game_id % must be a child of base version_group_id %', NEW.version_group_id, NEW.game_id, expected_base_version_group_id
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION private.enforce_game_content_scope_base () FROM PUBLIC;

REVOKE ALL ON FUNCTION private.enforce_game_content_scope_base () FROM anon;

REVOKE ALL ON FUNCTION private.enforce_game_content_scope_base () FROM authenticated;

GRANT EXECUTE ON FUNCTION private.enforce_game_content_scope_base () TO service_role;

CREATE TRIGGER enforce_game_content_scope_base
    BEFORE INSERT OR UPDATE OF game_id,
    version_group_id,
    is_base_scope ON reference.game_content_scopes
    FOR EACH ROW
    EXECUTE FUNCTION private.enforce_game_content_scope_base ();

COMMENT ON FUNCTION private.enforce_game_content_scope_base () IS 'Ensures each base game content scope matches the game base version group and optional scopes are direct children of that base scope.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/030_content_scope_dependencies.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.content_scope_dependencies
-- Ordered dependencies between optional version-group content scopes.
-- ============================================================================
CREATE TABLE reference.content_scope_dependencies (
    version_group_id integer NOT NULL,
    required_version_group_id integer NOT NULL,
    dependency_kind text NOT NULL DEFAULT 'required',
    sort_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT content_scope_dependencies_primary_key PRIMARY KEY (version_group_id, required_version_group_id),
    CONSTRAINT content_scope_dependencies_version_group_fkey FOREIGN KEY (version_group_id) REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT content_scope_dependencies_required_version_group_fkey FOREIGN KEY (required_version_group_id) REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT content_scope_dependencies_kind_check CHECK (dependency_kind IN ('required')),
    CONSTRAINT content_scope_dependencies_sort_order_positive_check CHECK (sort_order > 0),
    CONSTRAINT content_scope_dependencies_not_self_check CHECK (version_group_id <> required_version_group_id)
);

CREATE UNIQUE INDEX content_scope_dependencies_sort_order_unique ON reference.content_scope_dependencies (version_group_id, sort_order);

COMMENT ON TABLE reference.content_scope_dependencies IS 'Explicit ordered dependencies between optional content scopes, used when resolving cumulative DLC/update reference data.';

COMMENT ON COLUMN reference.content_scope_dependencies.version_group_id IS 'Content scope that requires another scope when resolving cumulative reference data.';

COMMENT ON COLUMN reference.content_scope_dependencies.required_version_group_id IS 'Required content scope that must be included before version_group_id.';

COMMENT ON COLUMN reference.content_scope_dependencies.dependency_kind IS 'Dependency semantics. Currently only required dependencies are seeded.';

