    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT learn_methods_id_positive_check CHECK (id > 0),
    CONSTRAINT learn_methods_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:_[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 80),
    CONSTRAINT learn_methods_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 120),
    CONSTRAINT learn_methods_description_length_check CHECK (CHAR_LENGTH(BTRIM(description)) BETWEEN 1 AND 1000),
    CONSTRAINT learn_methods_sort_order_positive_check CHECK (sort_order > 0)
);

COMMENT ON TABLE reference.learn_methods IS 'Stable move learn methods used by generation- and game-aware Pokémon learnsets.';

COMMENT ON COLUMN reference.learn_methods.description IS 'Stable product-facing definition for this learn method.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/036_move_machines.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.move_machines
-- Version/game-scoped TM/HM/TR machine catalog.
-- ============================================================================
CREATE TABLE reference.move_machines (
    id integer PRIMARY KEY,
    move_id integer NOT NULL REFERENCES reference.moves (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    version_group_id integer NOT NULL REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    game_id integer,
    learn_method_id integer NOT NULL REFERENCES reference.learn_methods (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    machine_label text NOT NULL,
    scope_operation text NOT NULL DEFAULT 'add',
    sort_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT move_machines_id_positive_check CHECK (id > 0),
    CONSTRAINT move_machines_game_scope_fkey FOREIGN KEY (game_id, version_group_id) REFERENCES reference.game_content_scopes (game_id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT move_machines_method_check CHECK (learn_method_id IN (2, 3, 4)),
    CONSTRAINT move_machines_label_shape_check CHECK ((learn_method_id = 2 AND machine_label ~ '^TM[0-9]{2,3}$') OR (learn_method_id = 3 AND machine_label ~ '^HM[0-9]{2}$') OR (learn_method_id = 4 AND machine_label ~ '^TR[0-9]{2}$')),
    CONSTRAINT move_machines_scope_operation_check CHECK (scope_operation IN ('add', 'override', 'remove')),
    CONSTRAINT move_machines_machine_label_length_check CHECK (CHAR_LENGTH(BTRIM(machine_label)) BETWEEN 1 AND 40),
    CONSTRAINT move_machines_sort_order_positive_check CHECK (sort_order > 0)
);

CREATE UNIQUE INDEX move_machines_vg_label_unique ON reference.move_machines (version_group_id, learn_method_id, machine_label)
WHERE
    game_id IS NULL;

CREATE UNIQUE INDEX move_machines_game_label_unique ON reference.move_machines (version_group_id, game_id, learn_method_id, machine_label)
WHERE
    game_id IS NOT NULL;

CREATE INDEX move_machines_move_scope_lookup_idx ON reference.move_machines (move_id, version_group_id, game_id);

CREATE INDEX move_machines_scope_method_lookup_idx ON reference.move_machines (version_group_id, game_id, learn_method_id, sort_order);

COMMENT ON TABLE reference.move_machines IS 'Version- and game-scoped TM/HM/TR machine catalog delta rows used by Pokémon learnsets.';

COMMENT ON COLUMN reference.move_machines.id IS 'Curated deterministic machine id: version_group_id * 1000000 + COALESCE(game_id, 0) * 10000 + learn_method_id * 1000 + machine number.';

COMMENT ON COLUMN reference.move_machines.game_id IS 'Nullable for version-group-wide machine catalogs. When set, the game must be mapped to the same content scope.';

COMMENT ON COLUMN reference.move_machines.learn_method_id IS 'Must reference a machine learn method: TM, HM, or TR.';

COMMENT ON COLUMN reference.move_machines.machine_label IS 'Machine display label such as TM24, HM03, or TR10.';

COMMENT ON COLUMN reference.move_machines.scope_operation IS 'Cumulative content-scope operation. add is the normal positive row; override/remove are reserved for source changes that supersede earlier scopes.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/037_pokemon_learnsets.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.pokemon_learnsets
-- Pokémon/form move learnsets by version group and optional game scope.
-- ============================================================================
CREATE TABLE reference.pokemon_learnsets (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    species_id integer NOT NULL,
    form_id integer NOT NULL,
    move_id integer NOT NULL REFERENCES reference.moves (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    version_group_id integer NOT NULL REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    game_id integer,
    learn_method_id integer NOT NULL REFERENCES reference.learn_methods (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    level_learned_at integer,
    source_item_id integer REFERENCES reference.items (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    move_machine_id integer REFERENCES reference.move_machines (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    condition_summary text,
    scope_operation text NOT NULL DEFAULT 'add',
    sort_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT pokemon_learnsets_id_positive_check CHECK (id > 0),
    CONSTRAINT pokemon_learnsets_form_fkey FOREIGN KEY (species_id, form_id) REFERENCES reference.pokemon_forms (species_id, id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT pokemon_learnsets_game_scope_fkey FOREIGN KEY (game_id, version_group_id) REFERENCES reference.game_content_scopes (game_id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT pokemon_learnsets_level_check CHECK (level_learned_at IS NULL OR level_learned_at BETWEEN 1 AND 100),
    CONSTRAINT pokemon_learnsets_level_method_shape_check CHECK ((learn_method_id = 1 AND level_learned_at IS NOT NULL) OR (learn_method_id <> 1 AND level_learned_at IS NULL)),
    CONSTRAINT pokemon_learnsets_machine_method_shape_check CHECK ((learn_method_id IN (2, 3, 4) AND move_machine_id IS NOT NULL) OR (learn_method_id NOT IN (2, 3, 4) AND move_machine_id IS NULL)),
    CONSTRAINT pokemon_learnsets_condition_summary_length_check CHECK (condition_summary IS NULL OR CHAR_LENGTH(BTRIM(condition_summary)) BETWEEN 1 AND 500),
    CONSTRAINT pokemon_learnsets_scope_operation_check CHECK (scope_operation IN ('add', 'override', 'remove')),
    CONSTRAINT pokemon_learnsets_sort_order_positive_check CHECK (sort_order > 0)
);

CREATE UNIQUE INDEX pokemon_learnsets_vg_unique ON reference.pokemon_learnsets (species_id, form_id, move_id, version_group_id, learn_method_id, (COALESCE(level_learned_at, 0)), (COALESCE(source_item_id, 0)), (COALESCE(move_machine_id, 0)))
WHERE
    game_id IS NULL;

CREATE UNIQUE INDEX pokemon_learnsets_game_unique ON reference.pokemon_learnsets (species_id, form_id, move_id, version_group_id, game_id, learn_method_id, (COALESCE(level_learned_at, 0)), (COALESCE(source_item_id, 0)), (COALESCE(move_machine_id, 0)))
WHERE
    game_id IS NOT NULL;

CREATE INDEX pokemon_learnsets_form_scope_lookup_idx ON reference.pokemon_learnsets (species_id, form_id, version_group_id, game_id, sort_order);

CREATE INDEX pokemon_learnsets_move_scope_lookup_idx ON reference.pokemon_learnsets (move_id, version_group_id, game_id);

CREATE INDEX pokemon_learnsets_method_scope_lookup_idx ON reference.pokemon_learnsets (version_group_id, learn_method_id);

CREATE INDEX pokemon_learnsets_source_item_lookup_idx ON reference.pokemon_learnsets (source_item_id)
WHERE
    source_item_id IS NOT NULL;

CREATE INDEX pokemon_learnsets_move_machine_lookup_idx ON reference.pokemon_learnsets (move_machine_id)
WHERE
    move_machine_id IS NOT NULL;

COMMENT ON INDEX reference.pokemon_learnsets_vg_unique IS 'Prevents duplicate version-group-wide learnset rows while allowing distinct level, item, or machine paths.';

COMMENT ON INDEX reference.pokemon_learnsets_game_unique IS 'Prevents duplicate game-specific learnset rows while allowing distinct level, item, or machine paths.';

COMMENT ON COLUMN reference.pokemon_learnsets.id IS 'Generated surrogate key for Supabase/client ergonomics; seed files omit id and rely on natural uniqueness constraints.';

COMMENT ON TABLE reference.pokemon_learnsets IS 'Source-preserving Pokémon/form move learnset delta rows for games and version groups.';

COMMENT ON COLUMN reference.pokemon_learnsets.level_learned_at IS 'Level for level-up learn rows. Null for non-level methods such as egg, tutor, machine, event, or evolution.';

COMMENT ON COLUMN reference.pokemon_learnsets.move_machine_id IS 'Required for TM/HM/TR learn methods and must reference the matching move machine in the same resolved content-scope closure.';

COMMENT ON COLUMN reference.pokemon_learnsets.scope_operation IS 'Cumulative content-scope operation. add is the normal positive row; override/remove are reserved for source changes that supersede earlier scopes.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/038_pokedex.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.pokedex
-- Pokedex definitions by version group.
-- ============================================================================
CREATE TABLE reference.pokedex (
    id integer PRIMARY KEY,
    version_group_id integer NOT NULL REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    slug text NOT NULL,
    name text NOT NULL,
    pokedex_kind text NOT NULL,
    is_completion_relevant boolean NOT NULL DEFAULT TRUE,
    sort_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT pokedex_id_positive_check CHECK (id > 0),
    CONSTRAINT pokedex_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 120),
    CONSTRAINT pokedex_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 160),
    CONSTRAINT pokedex_kind_check CHECK (pokedex_kind IN ('national', 'regional', 'local', 'dlc', 'special')),
    CONSTRAINT pokedex_sort_order_positive_check CHECK (sort_order > 0),
    CONSTRAINT pokedex_version_group_slug_unique UNIQUE (version_group_id, slug),
    CONSTRAINT pokedex_version_group_sort_order_unique UNIQUE (version_group_id, sort_order)
);

COMMENT ON TABLE reference.pokedex IS 'Pokedex scopes by version group, including completion dexes, browse-only local sections, and optional DLC dexes.';

COMMENT ON COLUMN reference.pokedex.is_completion_relevant IS 'True when this Pokedex is a completion-counting scope. False for browse-only local sections covered by an aggregate regional Pokedex.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/039_pokedex_entries.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.pokedex_entries
-- Species-level Pokedex membership.
-- ============================================================================
CREATE TABLE reference.pokedex_entries (
    pokedex_id integer NOT NULL REFERENCES reference.pokedex (id) ON UPDATE CASCADE ON DELETE CASCADE,
    species_id integer NOT NULL REFERENCES reference.pokemon_species (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    display_form_id integer,
    pokedex_number integer NOT NULL,
    is_source_required_for_completion boolean NOT NULL DEFAULT TRUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT pokedex_entries_primary_key PRIMARY KEY (pokedex_id, species_id),
    CONSTRAINT pokedex_entries_display_form_fkey FOREIGN KEY (species_id, display_form_id) REFERENCES reference.pokemon_forms (species_id, id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT pokedex_entries_number_nonnegative_check CHECK (pokedex_number >= 0),
    CONSTRAINT pokedex_entries_pokedex_number_unique UNIQUE (pokedex_id, pokedex_number)
);

COMMENT ON TABLE reference.pokedex_entries IS 'Species-level Pokedex entries keyed by Pokedex and species. Display form is optional and does not affect completion identity.';

COMMENT ON COLUMN reference.pokedex_entries.display_form_id IS 'Optional source/display form for entries where a dex presents a specific form. Completion remains species-level.';

COMMENT ON COLUMN reference.pokedex_entries.pokedex_number IS 'Number within the source Pokedex. Zero is allowed for real cases such as Victini #000 in the Unova Pokedex.';

COMMENT ON COLUMN reference.pokedex_entries.is_source_required_for_completion IS 'True when the source/game treats this Pokedex entry as required by default. False for source-visible optional entries such as mythicals and explicit regional exceptions.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/040_move_version_group_attributes.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.move_version_group_attributes
-- Move mechanics that one version group changes against its generation row.
-- ============================================================================
CREATE TABLE reference.move_version_group_attributes (
    move_id integer NOT NULL REFERENCES reference.moves (id) ON UPDATE CASCADE ON DELETE CASCADE,
    version_group_id integer NOT NULL REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    type_id integer NOT NULL REFERENCES reference.types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    power integer,
    accuracy integer,
    pp integer,
    priority integer NOT NULL DEFAULT 0,
    damage_class text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT move_version_group_attributes_primary_key PRIMARY KEY (move_id, version_group_id),
    CONSTRAINT move_version_group_attributes_power_check CHECK (power IS NULL OR power BETWEEN 0 AND 300),
    CONSTRAINT move_version_group_attributes_accuracy_check CHECK (accuracy IS NULL OR accuracy BETWEEN 1 AND 100),
    CONSTRAINT move_version_group_attributes_pp_check CHECK (pp IS NULL OR pp BETWEEN 1 AND 64),
    CONSTRAINT move_version_group_attributes_priority_check CHECK (priority BETWEEN -7 AND 7),
    CONSTRAINT move_version_group_attributes_damage_class_check CHECK (damage_class IN ('physical', 'special', 'status', 'variable'))
);

COMMENT ON TABLE reference.move_version_group_attributes IS 'Version-group overrides for move type, power, accuracy, PP, priority, and damage class, such as Let''s Go values. A row replaces the generation row for that version group only.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/041_z_move_sources.sql
-- ============================================================================
-- ============================================================================
-- Table: reference.z_move_sources
-- Which Z-Crystal turns which move into which Z-Move.
-- ============================================================================
CREATE TABLE reference.z_move_sources (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    z_move_id integer NOT NULL REFERENCES reference.moves (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    item_id integer NOT NULL REFERENCES reference.items (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    base_type_id integer REFERENCES reference.types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    species_id integer REFERENCES reference.pokemon_species (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    form_id integer,
    base_move_id integer REFERENCES reference.moves (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT z_move_sources_form_fkey FOREIGN KEY (species_id, form_id) REFERENCES reference.pokemon_forms (species_id, id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT z_move_sources_one_source_kind_check CHECK ((base_type_id IS NOT NULL AND species_id IS NULL AND form_id IS NULL AND base_move_id IS NULL) OR (base_type_id IS NULL AND species_id IS NOT NULL AND base_move_id IS NOT NULL)),
    CONSTRAINT z_move_sources_source_unique UNIQUE NULLS NOT DISTINCT (item_id, base_type_id, species_id, form_id, base_move_id)
);

CREATE INDEX z_move_sources_z_move_idx ON reference.z_move_sources (z_move_id);

CREATE INDEX z_move_sources_item_idx ON reference.z_move_sources (item_id);

CREATE INDEX z_move_sources_species_form_idx ON reference.z_move_sources (species_id, form_id)
WHERE
    species_id IS NOT NULL;

CREATE INDEX z_move_sources_base_move_idx ON reference.z_move_sources (base_move_id)
WHERE
    base_move_id IS NOT NULL;

COMMENT ON TABLE reference.z_move_sources IS 'How a held Z-Crystal turns a move into a Z-Move. A type crystal turns any damaging move of base_type_id into the Z-Move; an exclusive crystal turns base_move_id into the Z-Move only for that species (and form, when set).';

COMMENT ON COLUMN reference.z_move_sources.base_type_id IS 'Type crystals only: the type of the damaging move the crystal powers up. Status moves keep their own move and gain a Z-effect instead.';

COMMENT ON COLUMN reference.z_move_sources.form_id IS 'Exclusive crystals only: the one form that can use it. NULL means any form of species_id.';

COMMENT ON COLUMN reference.z_move_sources.base_move_id IS 'Exclusive crystals only: the move the Pokémon must know.';

-- ============================================================================
-- Source: database/schema/02_reference/01_tables/042_g_max_move_sources.sql
