-- ============================================================================
-- Source: database/schema/03_tracking/01_tables/001_mainline_snapshot_policies.sql
-- ============================================================================
-- ============================================================================
-- Table: tracking.mainline_snapshot_policies
-- Snapshot behavior lookup for milestone completion.
-- ============================================================================
CREATE TABLE tracking.mainline_snapshot_policies (
    id integer PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    name text NOT NULL UNIQUE,
    sort_order integer NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT mainline_snapshot_policies_id_positive_check CHECK (id > 0),
    CONSTRAINT mainline_snapshot_policies_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 80),
    CONSTRAINT mainline_snapshot_policies_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 120),
    CONSTRAINT mainline_snapshot_policies_sort_order_positive_check CHECK (sort_order > 0)
);

COMMENT ON TABLE tracking.mainline_snapshot_policies IS 'Snapshot behavior lookup for story milestone completion.';

-- ============================================================================
-- Source: database/schema/03_tracking/01_tables/002_mainline_categories.sql
-- ============================================================================
-- ============================================================================
-- Table: tracking.mainline_categories
-- Tracking mainline_categories by version group.
-- ============================================================================
CREATE TABLE tracking.mainline_categories (
    id integer PRIMARY KEY,
    version_group_id integer NOT NULL REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    slug text NOT NULL,
    name text NOT NULL,
    category_kind text NOT NULL,
    sort_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT mainline_categories_id_positive_check CHECK (id > 0),
    CONSTRAINT mainline_categories_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 120),
    CONSTRAINT mainline_categories_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 160),
    CONSTRAINT mainline_categories_kind_check CHECK (category_kind IN ('story', 'collectible')),
    CONSTRAINT mainline_categories_sort_order_positive_check CHECK (sort_order > 0),
    CONSTRAINT mainline_categories_id_version_group_unique UNIQUE (id, version_group_id),
    CONSTRAINT mainline_categories_version_group_slug_unique UNIQUE (version_group_id, slug),
    CONSTRAINT mainline_categories_version_group_sort_order_unique UNIQUE (version_group_id, sort_order)
);

COMMENT ON TABLE tracking.mainline_categories IS 'Version-group tracking mainline_categories for story and collectible progress definitions.';

-- ============================================================================
-- Source: database/schema/03_tracking/01_tables/003_mainline_milestone_types.sql
-- ============================================================================
-- ============================================================================
-- Table: tracking.mainline_milestone_types
-- Story milestone type lookup.
-- ============================================================================
CREATE TABLE tracking.mainline_milestone_types (
    id integer PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    name text NOT NULL UNIQUE,
    sort_order integer NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT mainline_milestone_types_id_positive_check CHECK (id > 0),
    CONSTRAINT mainline_milestone_types_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 80),
    CONSTRAINT mainline_milestone_types_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 120),
    CONSTRAINT mainline_milestone_types_sort_order_positive_check CHECK (sort_order > 0)
);

COMMENT ON TABLE tracking.mainline_milestone_types IS 'Lookup for curated story milestone types such as story, gym, rival, boss, elite-four, champion, and decision.';

-- ============================================================================
-- Source: database/schema/03_tracking/01_tables/004_mainline_milestone_prerequisite_kinds.sql
-- ============================================================================
-- ============================================================================
-- Table: tracking.mainline_milestone_prerequisite_kinds
-- Relationship kinds for milestone prerequisite links.
-- ============================================================================
CREATE TABLE tracking.mainline_milestone_prerequisite_kinds (
    id integer PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    name text NOT NULL UNIQUE,
    description text NOT NULL,
    sort_order integer NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT mainline_milestone_prerequisite_kinds_id_positive_check CHECK (id > 0),
    CONSTRAINT mainline_milestone_prerequisite_kinds_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 80),
    CONSTRAINT mainline_milestone_prerequisite_kinds_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 120),
    CONSTRAINT mainline_milestone_prerequisite_kinds_description_length_check CHECK (CHAR_LENGTH(BTRIM(description)) BETWEEN 1 AND 500),
    CONSTRAINT mainline_milestone_prerequisite_kinds_sort_order_positive_check CHECK (sort_order > 0)
);

COMMENT ON TABLE tracking.mainline_milestone_prerequisite_kinds IS 'Lookup for milestone prerequisite relationships used by story progression prompts and unlock logic.';

-- ============================================================================
-- Source: database/schema/03_tracking/01_tables/005_mainline_milestones.sql
-- ============================================================================
-- ============================================================================
-- Table: tracking.mainline_milestones
-- Story/progression milestone definitions.
-- ============================================================================
CREATE TABLE tracking.mainline_milestones (
    id integer PRIMARY KEY,
    version_group_id integer NOT NULL REFERENCES reference.version_groups (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    game_id integer,
    category_id integer NOT NULL,
    milestone_type_id integer NOT NULL REFERENCES tracking.mainline_milestone_types (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    snapshot_policy_id integer NOT NULL REFERENCES tracking.mainline_snapshot_policies (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    parent_milestone_id integer,
    slug text NOT NULL,
    name text NOT NULL,
    description text,
    sort_order integer NOT NULL,
    is_required_for_completion boolean NOT NULL DEFAULT TRUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT mainline_milestones_id_positive_check CHECK (id > 0),
    CONSTRAINT mainline_milestones_game_scope_fkey FOREIGN KEY (game_id, version_group_id) REFERENCES reference.game_content_scopes (game_id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT mainline_milestones_category_version_group_fkey FOREIGN KEY (category_id, version_group_id) REFERENCES tracking.mainline_categories (id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT mainline_milestones_parent_version_group_fkey FOREIGN KEY (parent_milestone_id, version_group_id) REFERENCES tracking.mainline_milestones (id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT mainline_milestones_parent_not_self_check CHECK (parent_milestone_id IS NULL OR parent_milestone_id <> id),
    CONSTRAINT mainline_milestones_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 160),
    CONSTRAINT mainline_milestones_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 200),
    CONSTRAINT mainline_milestones_description_length_check CHECK (description IS NULL OR CHAR_LENGTH(BTRIM(description)) BETWEEN 1 AND 2000),
    CONSTRAINT mainline_milestones_sort_order_positive_check CHECK (sort_order > 0),
    CONSTRAINT mainline_milestones_id_version_group_unique UNIQUE (id, version_group_id)
);

CREATE UNIQUE INDEX mainline_milestones_version_group_slug_unique ON tracking.mainline_milestones (version_group_id, slug)
WHERE
    game_id IS NULL;

CREATE UNIQUE INDEX mainline_milestones_game_slug_unique ON tracking.mainline_milestones (version_group_id, game_id, slug)
WHERE
    game_id IS NOT NULL;

CREATE UNIQUE INDEX mainline_milestones_version_group_category_sort_order_unique ON tracking.mainline_milestones (version_group_id, category_id, sort_order)
WHERE
    game_id IS NULL;

CREATE UNIQUE INDEX mainline_milestones_game_category_sort_order_unique ON tracking.mainline_milestones (version_group_id, game_id, category_id, sort_order)
WHERE
    game_id IS NOT NULL;

CREATE INDEX mainline_milestones_version_group_game_idx ON tracking.mainline_milestones (version_group_id, game_id);

CREATE INDEX mainline_milestones_category_sort_idx ON tracking.mainline_milestones (version_group_id, category_id, sort_order);

CREATE INDEX mainline_milestones_milestone_type_idx ON tracking.mainline_milestones (milestone_type_id);

CREATE INDEX mainline_milestones_snapshot_policy_idx ON tracking.mainline_milestones (snapshot_policy_id);

CREATE INDEX mainline_milestones_parent_idx ON tracking.mainline_milestones (parent_milestone_id)
WHERE
    parent_milestone_id IS NOT NULL;

COMMENT ON TABLE tracking.mainline_milestones IS 'Curated story/progression milestone definitions. User completion state lives in gameplay.';

COMMENT ON COLUMN tracking.mainline_milestones.game_id IS 'Nullable for version-group-wide mainline_milestones. When set, the game must be mapped to the same content scope.';

COMMENT ON COLUMN tracking.mainline_milestones.sort_order IS 'Display order within its category in the final play scope. Game-specific rows can fill slots between version-group-wide rows. Previous-step prompts and unlock logic are modeled in mainline_milestone_prerequisites.';

COMMENT ON COLUMN tracking.mainline_milestones.snapshot_policy_id IS 'Defines whether the UI should offer or recommend a team snapshot when completing the milestone.';

