-- ============================================================================
-- Source: database/schema/04_gameplay/01_tables/001_mainline_play_statuses.sql
-- ============================================================================
-- ============================================================================
-- Table: gameplay.mainline_play_statuses
-- Play lifecycle status lookup.
-- ============================================================================
CREATE TABLE gameplay.mainline_play_statuses (
    id integer PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    name text NOT NULL UNIQUE,
    is_terminal boolean NOT NULL DEFAULT FALSE,
    sort_order integer NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT play_statuses_id_positive_check CHECK (id > 0),
    CONSTRAINT play_statuses_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:_[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 80),
    CONSTRAINT play_statuses_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 120),
    CONSTRAINT play_statuses_sort_order_positive_check CHECK (sort_order > 0)
);

COMMENT ON TABLE gameplay.mainline_play_statuses IS 'Lookup table for play lifecycle states. Archive is stored separately on gameplay.mainline_plays.';

COMMENT ON COLUMN gameplay.mainline_play_statuses.is_terminal IS 'Marks statuses where the play is no longer expected to progress.';

-- ============================================================================
-- Source: database/schema/04_gameplay/01_tables/002_mainline_plays.sql
-- ============================================================================
-- ============================================================================
-- Table: gameplay.mainline_plays
-- User-owned Pokémon playthroughs.
-- ============================================================================
CREATE TABLE gameplay.mainline_plays (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid (),
    user_id uuid NOT NULL REFERENCES public.profiles (id) ON UPDATE CASCADE ON DELETE CASCADE,
    game_id integer NOT NULL,
    version_group_id integer NOT NULL,
    status_id integer NOT NULL REFERENCES gameplay.mainline_play_statuses (id) ON UPDATE CASCADE ON DELETE RESTRICT DEFAULT 1,
    name text NOT NULL,
    trainer_name text,
    platform_id integer REFERENCES reference.platforms (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    custom_platform_name text,
    started_on date,
    completed_on date,
    playtime_minutes integer,
    notes text,
    save_notes text,
    archived_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    updated_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT plays_game_version_group_fkey FOREIGN KEY (game_id, version_group_id) REFERENCES reference.games (id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT plays_id_game_unique UNIQUE (id, game_id),
    CONSTRAINT plays_id_user_unique UNIQUE (id, user_id),
    CONSTRAINT plays_id_user_game_version_group_unique UNIQUE (id, user_id, game_id, version_group_id),
    CONSTRAINT plays_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 200),
    CONSTRAINT plays_trainer_name_length_check CHECK (trainer_name IS NULL OR CHAR_LENGTH(BTRIM(trainer_name)) BETWEEN 1 AND 120),
    CONSTRAINT plays_custom_platform_name_length_check CHECK (custom_platform_name IS NULL OR CHAR_LENGTH(BTRIM(custom_platform_name)) BETWEEN 1 AND 120),
    CONSTRAINT plays_custom_platform_without_platform_check CHECK (custom_platform_name IS NULL OR platform_id IS NULL),
    CONSTRAINT plays_completed_not_before_started_check CHECK (completed_on IS NULL OR started_on IS NULL OR completed_on >= started_on),
    CONSTRAINT plays_playtime_nonnegative_check CHECK (playtime_minutes IS NULL OR playtime_minutes >= 0),
    CONSTRAINT plays_notes_length_check CHECK (notes IS NULL OR CHAR_LENGTH(BTRIM(notes)) BETWEEN 1 AND 10000),
    CONSTRAINT plays_save_notes_length_check CHECK (save_notes IS NULL OR CHAR_LENGTH(BTRIM(save_notes)) BETWEEN 1 AND 10000)
);

CREATE TRIGGER set_plays_updated_at
    BEFORE UPDATE ON gameplay.mainline_plays
    FOR EACH ROW
    EXECUTE FUNCTION private.set_updated_at ();

CREATE INDEX plays_user_updated_at_idx ON gameplay.mainline_plays (user_id, updated_at DESC);

CREATE INDEX plays_user_status_idx ON gameplay.mainline_plays (user_id, status_id);

CREATE INDEX plays_status_idx ON gameplay.mainline_plays (status_id);

CREATE INDEX plays_user_game_idx ON gameplay.mainline_plays (user_id, game_id);

CREATE INDEX plays_game_version_group_idx ON gameplay.mainline_plays (game_id, version_group_id);

CREATE INDEX plays_user_version_group_idx ON gameplay.mainline_plays (user_id, version_group_id);

CREATE INDEX plays_version_group_idx ON gameplay.mainline_plays (version_group_id);

CREATE INDEX plays_platform_idx ON gameplay.mainline_plays (platform_id)
WHERE
    platform_id IS NOT NULL;

CREATE INDEX plays_user_archived_idx ON gameplay.mainline_plays (user_id, archived_at);

COMMENT ON TABLE gameplay.mainline_plays IS 'Central user-owned playthrough/adventure entity.';

COMMENT ON COLUMN gameplay.mainline_plays.version_group_id IS 'Stored with game_id so optional content, tracking, and availability joins can use composite integrity.';

COMMENT ON COLUMN gameplay.mainline_plays.archived_at IS 'Archive marker separate from lifecycle status.';

-- ============================================================================
-- Source: database/schema/04_gameplay/01_tables/003_mainline_play_settings.sql
-- ============================================================================
-- ============================================================================
-- Table: gameplay.mainline_play_settings
-- Play-specific completion and tracking settings.
-- ============================================================================
CREATE TABLE gameplay.mainline_play_settings (
    play_id uuid PRIMARY KEY REFERENCES gameplay.mainline_plays (id) ON UPDATE CASCADE ON DELETE CASCADE,
    story_tracking_enabled boolean NOT NULL DEFAULT TRUE,
    pokedex_tracking_enabled boolean NOT NULL DEFAULT TRUE,
    pokedex_mode text NOT NULL DEFAULT 'caught_and_seen',
    collectibles_tracking_enabled boolean NOT NULL DEFAULT TRUE,
    include_pokedex_in_completion boolean NOT NULL DEFAULT TRUE,
    include_collectibles_in_completion boolean NOT NULL DEFAULT TRUE,
    include_optional_pokedexes_in_completion boolean NOT NULL DEFAULT FALSE,
    include_optional_pokedex_entries_in_completion boolean NOT NULL DEFAULT TRUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    updated_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT play_settings_pokedex_mode_check CHECK (pokedex_mode IN ('caught_only', 'caught_and_seen')),
    CONSTRAINT play_settings_collectibles_tracking_completion_check CHECK (collectibles_tracking_enabled OR NOT include_collectibles_in_completion),
    CONSTRAINT play_settings_tracking_completion_check CHECK (pokedex_tracking_enabled OR NOT include_pokedex_in_completion),
    CONSTRAINT play_settings_opt_dex_entries_requires_dex_completion_check CHECK (include_pokedex_in_completion OR NOT include_optional_pokedex_entries_in_completion),
    CONSTRAINT play_settings_opt_dexes_requires_dex_completion_check CHECK (include_pokedex_in_completion OR NOT include_optional_pokedexes_in_completion)
);

CREATE TRIGGER set_play_settings_updated_at
    BEFORE UPDATE ON gameplay.mainline_play_settings
    FOR EACH ROW
    EXECUTE FUNCTION private.set_updated_at ();

COMMENT ON TABLE gameplay.mainline_play_settings IS 'Per-play settings that influence tracking and derived completion calculations.';

COMMENT ON COLUMN gameplay.mainline_play_settings.story_tracking_enabled IS 'When false, Story milestones are left out of the Play''s completion counts. Recorded progress is kept and returns when switched back on.';

COMMENT ON COLUMN gameplay.mainline_play_settings.pokedex_mode IS 'caught_only tracks caught Pokémon; caught_and_seen tracks both. Recorded seen state is kept either way.';

COMMENT ON COLUMN gameplay.mainline_play_settings.collectibles_tracking_enabled IS 'When false, collectible entries are left out of the Play''s completion counts and collectible tracking is off. Recorded progress is kept.';

COMMENT ON COLUMN gameplay.mainline_play_settings.include_optional_pokedexes_in_completion IS 'When true, optional Pokedex scopes such as National or special post-game Pokedexes count toward completion. DLC Pokedexes are controlled by selected optional content scopes.';

COMMENT ON COLUMN gameplay.mainline_play_settings.include_optional_pokedex_entries_in_completion IS 'When true, source-visible optional Pokedex entries count toward completion. Only meaningful when Pokedex completion is included.';

CREATE TRIGGER touch_play_after_change
    AFTER INSERT OR UPDATE OR DELETE ON gameplay.mainline_play_settings
    FOR EACH ROW
    EXECUTE FUNCTION private.touch_play ();

-- ============================================================================
-- Source: database/schema/04_gameplay/01_tables/004_mainline_play_optional_content_scopes.sql
-- ============================================================================
-- ============================================================================
-- Table: gameplay.mainline_play_optional_content_scopes
-- Optional content selected for a play.
-- ============================================================================
CREATE TABLE gameplay.mainline_play_optional_content_scopes (
    play_id uuid NOT NULL,
    game_id integer NOT NULL,
    version_group_id integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT play_optional_content_scopes_primary_key PRIMARY KEY (play_id, version_group_id),
    CONSTRAINT play_optional_content_scopes_play_game_fkey FOREIGN KEY (play_id, game_id) REFERENCES gameplay.mainline_plays (id, game_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT play_optional_content_scopes_game_scope_fkey FOREIGN KEY (game_id, version_group_id) REFERENCES reference.game_content_scopes (game_id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT
);

COMMENT ON TABLE gameplay.mainline_play_optional_content_scopes IS 'Optional game content scopes such as DLC selected for a play. The base content scope is implied by gameplay.mainline_plays.';

COMMENT ON COLUMN gameplay.mainline_play_optional_content_scopes.game_id IS 'Duplicated from the play to enforce game-specific content-scope validity with a composite FK.';

CREATE FUNCTION private.enforce_play_optional_content_scope ()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path = ''
    AS $$
DECLARE
    is_base boolean;
BEGIN
    SELECT
        game_content_scopes.is_base_scope
    INTO
        is_base
    FROM
        reference.game_content_scopes
    WHERE
        game_content_scopes.game_id = NEW.game_id
        AND game_content_scopes.version_group_id = NEW.version_group_id;
    IF is_base IS NULL THEN
        RAISE EXCEPTION 'Version group % is not a content scope for game %', NEW.version_group_id, NEW.game_id
            USING ERRCODE = '23503';
    END IF;
    IF is_base THEN
        RAISE EXCEPTION 'Base version group % for game % is implied by the play and cannot be inserted as optional content', NEW.version_group_id, NEW.game_id
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION private.enforce_play_optional_content_scope () FROM PUBLIC;

REVOKE ALL ON FUNCTION private.enforce_play_optional_content_scope () FROM anon;

REVOKE ALL ON FUNCTION private.enforce_play_optional_content_scope () FROM authenticated;

GRANT EXECUTE ON FUNCTION private.enforce_play_optional_content_scope () TO service_role;

CREATE TRIGGER enforce_play_optional_content_scope
    BEFORE INSERT OR UPDATE OF game_id,
    version_group_id ON gameplay.mainline_play_optional_content_scopes
    FOR EACH ROW
    EXECUTE FUNCTION private.enforce_play_optional_content_scope ();

CREATE INDEX play_optional_content_scopes_play_game_idx ON gameplay.mainline_play_optional_content_scopes (play_id, game_id);

CREATE INDEX play_optional_content_scopes_game_scope_idx ON gameplay.mainline_play_optional_content_scopes (game_id, version_group_id);

CREATE INDEX play_optional_content_scopes_version_group_idx ON gameplay.mainline_play_optional_content_scopes (version_group_id);

COMMENT ON FUNCTION private.enforce_play_optional_content_scope () IS 'Prevents inserting a play base content scope as optional content.';

CREATE TRIGGER touch_play_after_change
    AFTER INSERT OR UPDATE OR DELETE ON gameplay.mainline_play_optional_content_scopes
    FOR EACH ROW
    EXECUTE FUNCTION private.touch_play ();

