-- ============================================================================
-- Table: gameplay.mainline_challenge_rule_set_rules
-- The rules in each preset (they keep no order: a Play adds them all).
-- ============================================================================
CREATE TABLE gameplay.mainline_challenge_rule_set_rules (
    rule_set_id uuid NOT NULL REFERENCES gameplay.mainline_challenge_rule_sets (id) ON UPDATE CASCADE ON DELETE CASCADE,
    challenge_rule_id uuid NOT NULL REFERENCES gameplay.mainline_challenge_rules (id) ON UPDATE CASCADE ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT challenge_rule_set_rules_primary_key PRIMARY KEY (rule_set_id, challenge_rule_id)
);

CREATE INDEX challenge_rule_set_rules_challenge_rule_idx ON gameplay.mainline_challenge_rule_set_rules (challenge_rule_id);

COMMENT ON TABLE gameplay.mainline_challenge_rule_set_rules IS 'The rules in each preset; they keep no order, as a Play takes them all at once.';

CREATE FUNCTION private.enforce_challenge_rule_set_rule_scope ()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path = ''
    AS $$
DECLARE
    set_found boolean;
    set_user_id uuid;
    rule_found boolean;
    rule_user_id uuid;
BEGIN
    SELECT
        TRUE,
        mainline_challenge_rule_sets.user_id
    INTO
        set_found,
        set_user_id
    FROM
        gameplay.mainline_challenge_rule_sets
    WHERE
        mainline_challenge_rule_sets.id = NEW.rule_set_id;
    SELECT
        TRUE,
        mainline_challenge_rules.user_id
    INTO
        rule_found,
        rule_user_id
    FROM
        gameplay.mainline_challenge_rules
    WHERE
        mainline_challenge_rules.id = NEW.challenge_rule_id;
    IF set_found IS NULL THEN
        RAISE EXCEPTION 'Unknown rule_set_id %', NEW.rule_set_id
            USING ERRCODE = '23503';
    END IF;
    IF rule_found IS NULL THEN
        RAISE EXCEPTION 'Unknown challenge_rule_id %', NEW.challenge_rule_id
            USING ERRCODE = '23503';
    END IF;
    -- Voydex's presets hold only Voydex's rules; yours hold Voydex's and yours.
    IF rule_user_id IS NOT NULL AND rule_user_id IS DISTINCT FROM set_user_id THEN
        RAISE EXCEPTION 'Challenge rule % does not belong to the owner of rule set %', NEW.challenge_rule_id, NEW.rule_set_id
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION private.enforce_challenge_rule_set_rule_scope () FROM PUBLIC;

REVOKE ALL ON FUNCTION private.enforce_challenge_rule_set_rule_scope () FROM anon;

REVOKE ALL ON FUNCTION private.enforce_challenge_rule_set_rule_scope () FROM authenticated;

GRANT EXECUTE ON FUNCTION private.enforce_challenge_rule_set_rule_scope () TO service_role;

CREATE TRIGGER enforce_challenge_rule_set_rule_scope
    BEFORE INSERT OR UPDATE OF rule_set_id,
    challenge_rule_id ON gameplay.mainline_challenge_rule_set_rules
    FOR EACH ROW
    EXECUTE FUNCTION private.enforce_challenge_rule_set_rule_scope ();

COMMENT ON FUNCTION private.enforce_challenge_rule_set_rule_scope () IS 'Lets a preset hold Voydex''s rules and its owner''s own rules only, so Voydex''s presets hold only Voydex''s rules.';

-- ============================================================================
-- Source: database/schema/04_gameplay/02_functions/001_mainline_play_milestone_mutations.sql
-- ============================================================================
-- ============================================================================
-- Functions: gameplay mainline milestone mutations
-- Client-callable helpers for atomic story progress writes.
-- ============================================================================
CREATE FUNCTION gameplay.complete_mainline_play_milestone (p_play_id uuid, p_milestone_id integer, p_completed_at timestamptz DEFAULT NOW(), p_progress_notes text DEFAULT NULL, p_decision_option_id integer DEFAULT NULL, p_record_earlier_milestone_ids integer[] DEFAULT '{}'::integer[], p_create_event boolean DEFAULT FALSE, p_event_title text DEFAULT NULL, p_event_body text DEFAULT NULL, p_event_happened_at timestamptz DEFAULT NULL, p_include_team_snapshot boolean DEFAULT FALSE, p_replace_progress_notes boolean DEFAULT FALSE, p_replace_decision boolean DEFAULT FALSE)
    RETURNS TABLE (
        play_id uuid,
        milestone_id integer,
        completion_event_id uuid,
        completed_milestone_ids integer[],
        snapshot_count integer)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_target_milestone tracking.mainline_milestones%ROWTYPE;
    v_target_category_sort_order integer;
    v_play_game_id integer;
    v_requested_earlier_ids integer[];
    v_completion_milestone_ids integer[];
    v_invalid_earlier_ids integer[];
    v_unmet_required_prerequisite_ids integer[];
    v_event_id uuid;
    v_event_title text;
    v_event_type_id integer;
    v_event_origin_id integer;
    v_next_timeline_order integer;
    v_inserted_snapshot_count integer := 0;
BEGIN
    IF p_play_id IS NULL THEN
        RAISE EXCEPTION 'play_id is required'
            USING ERRCODE = '23502';
    END IF;
    IF p_milestone_id IS NULL THEN
        RAISE EXCEPTION 'milestone_id is required'
            USING ERRCODE = '23502';
    END IF;
    p_progress_notes := NULLIF (BTRIM(p_progress_notes), '');
    p_event_title := NULLIF (BTRIM(p_event_title), '');
    p_event_body := NULLIF (BTRIM(p_event_body), '');
    IF p_include_team_snapshot AND NOT p_create_event THEN
        RAISE EXCEPTION 'A team snapshot requires a linked timeline event'
            USING ERRCODE = '23514';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(p_play_id::text)::bigint);
    SELECT
        mainline_milestones.*
    INTO
        v_target_milestone
    FROM
        tracking.mainline_milestones
    WHERE
        mainline_milestones.id = p_milestone_id;
    IF v_target_milestone.id IS NULL THEN
        RAISE EXCEPTION 'Unknown milestone_id %', p_milestone_id
            USING ERRCODE = '23503';
    END IF;
    IF NOT EXISTS (
        SELECT
            1
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.id = p_play_id) THEN
    RAISE EXCEPTION 'Unknown or unavailable play_id %', p_play_id
        USING ERRCODE = '23503';
END IF;
    IF NOT EXISTS (
        SELECT
            1
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.id = p_play_id
            AND (v_target_milestone.game_id IS NULL
                OR mainline_plays.game_id = v_target_milestone.game_id)
            AND (mainline_plays.version_group_id = v_target_milestone.version_group_id
                OR EXISTS (
                    SELECT
                        1
                    FROM
                        gameplay.mainline_play_optional_content_scopes
                    WHERE
                        mainline_play_optional_content_scopes.play_id = mainline_plays.id
                        AND mainline_play_optional_content_scopes.version_group_id = v_target_milestone.version_group_id))) THEN
        RAISE EXCEPTION 'Milestone % is not available for play %', p_milestone_id, p_play_id
    USING ERRCODE = '23514';
END IF;
    SELECT
        mainline_plays.game_id
    INTO
        v_play_game_id
    FROM
        gameplay.mainline_plays
    WHERE
        mainline_plays.id = p_play_id;
    SELECT
        COALESCE(ARRAY_AGG(DISTINCT requested_id ORDER BY requested_id), '{}'::integer[])
    INTO
        v_requested_earlier_ids
    FROM
        UNNEST(COALESCE(p_record_earlier_milestone_ids, '{}'::integer[])) AS requested (requested_id)
WHERE
    requested_id IS NOT NULL
    AND requested_id <> p_milestone_id;
    IF CARDINALITY(v_requested_earlier_ids) > 0 THEN
        IF EXISTS (
            SELECT
                1
            FROM
                reference.version_groups
            WHERE
                version_groups.id = v_target_milestone.version_group_id
                AND version_groups.is_open_world) THEN
        RAISE EXCEPTION 'Milestone % is in an open-world story, so earlier milestones are recorded one by one', p_milestone_id
            USING ERRCODE = '23514';
    END IF;
    SELECT
        mainline_categories.sort_order
    INTO
        v_target_category_sort_order
    FROM
        tracking.mainline_categories
    WHERE
        mainline_categories.id = v_target_milestone.category_id;
    -- Earlier means Story's order: category, then the milestone's own order.
    -- Required milestones and choices only; a choice's decision stays unrecorded.
    SELECT
        COALESCE(ARRAY_AGG(requested_id ORDER BY requested_id), '{}'::integer[])
    INTO
        v_invalid_earlier_ids
    FROM
        UNNEST(v_requested_earlier_ids) AS requested (requested_id)
WHERE
    NOT EXISTS (
        SELECT
            1
        FROM
            tracking.mainline_milestones
            JOIN tracking.mainline_categories ON mainline_categories.id = mainline_milestones.category_id
            JOIN tracking.mainline_milestone_types ON mainline_milestone_types.id = mainline_milestones.milestone_type_id
        WHERE
            mainline_milestones.id = requested_id
            AND mainline_milestones.version_group_id = v_target_milestone.version_group_id
            AND (mainline_milestones.is_required_for_completion
                OR mainline_milestone_types.slug = 'decision')
            AND (mainline_milestones.game_id IS NULL
                OR mainline_milestones.game_id = v_play_game_id)
            AND (mainline_categories.sort_order,
                mainline_categories.id,
                mainline_milestones.sort_order,
                mainline_milestones.id) < (v_target_category_sort_order,
                v_target_milestone.category_id,
                v_target_milestone.sort_order,
                v_target_milestone.id));
    IF CARDINALITY(v_invalid_earlier_ids) > 0 THEN
        RAISE EXCEPTION 'Milestones % are not required milestones or choices before milestone %', v_invalid_earlier_ids, p_milestone_id
            USING ERRCODE = '23514';
    END IF;
    -- One already recorded keeps its own record.
    SELECT
        COALESCE(ARRAY_AGG(requested_id ORDER BY requested_id), '{}'::integer[])
    INTO
        v_requested_earlier_ids
    FROM
        UNNEST(v_requested_earlier_ids) AS requested (requested_id)
WHERE
    NOT EXISTS (
        SELECT
            1
        FROM
            gameplay.mainline_play_milestone_progress
        WHERE
            mainline_play_milestone_progress.play_id = p_play_id
            AND mainline_play_milestone_progress.milestone_id = requested_id);
END IF;
    WITH RECURSIVE blocking_prerequisites AS (
        SELECT
            mainline_milestone_prerequisites.prerequisite_milestone_id
        FROM
            tracking.mainline_milestone_prerequisites
            JOIN tracking.mainline_milestone_prerequisite_kinds ON mainline_milestone_prerequisite_kinds.id = mainline_milestone_prerequisites.prerequisite_kind_id
        WHERE
            mainline_milestone_prerequisites.milestone_id = p_milestone_id
            AND mainline_milestone_prerequisite_kinds.slug IN ('required', 'story-unlock')
        UNION
        SELECT
            nested_prerequisites.prerequisite_milestone_id
        FROM
            blocking_prerequisites
            JOIN tracking.mainline_milestone_prerequisites AS nested_prerequisites ON nested_prerequisites.milestone_id = blocking_prerequisites.prerequisite_milestone_id
            JOIN tracking.mainline_milestone_prerequisite_kinds AS nested_kinds ON nested_kinds.id = nested_prerequisites.prerequisite_kind_id
        WHERE
            nested_kinds.slug IN ('required', 'story-unlock'))
    SELECT
        COALESCE(ARRAY_AGG(blocking_prerequisites.prerequisite_milestone_id ORDER BY blocking_prerequisites.prerequisite_milestone_id), '{}'::integer[])
    INTO
        v_unmet_required_prerequisite_ids
    FROM
        blocking_prerequisites
    WHERE
        NOT (blocking_prerequisites.prerequisite_milestone_id = ANY (v_requested_earlier_ids))
        AND NOT EXISTS (
            SELECT
                1
            FROM
                gameplay.mainline_play_milestone_progress
            WHERE
                mainline_play_milestone_progress.play_id = p_play_id
                AND mainline_play_milestone_progress.milestone_id = blocking_prerequisites.prerequisite_milestone_id);
    IF ARRAY_LENGTH(v_unmet_required_prerequisite_ids, 1) IS NOT NULL THEN
        RAISE EXCEPTION 'Milestone % requires completed milestones %', p_milestone_id, v_unmet_required_prerequisite_ids
            USING ERRCODE = '23514';
    END IF;
    SELECT
        ARRAY_AGG(milestone_ids.milestone_id ORDER BY milestone_ids.sort_order)
    INTO
        v_completion_milestone_ids
    FROM (
        SELECT
            requested_id AS milestone_id,
            ROW_NUMBER() OVER (ORDER BY requested_id) AS sort_order
        FROM
            UNNEST(v_requested_earlier_ids) AS requested (requested_id)
        UNION ALL
        SELECT
            p_milestone_id,
            2147483647) AS milestone_ids;
INSERT INTO gameplay.mainline_play_milestone_progress (play_id, milestone_id, completed_at, notes)
SELECT
    p_play_id,
    milestone_ids.milestone_id,
    p_completed_at,
    CASE WHEN milestone_ids.milestone_id = p_milestone_id THEN
        p_progress_notes
    ELSE
        NULL
    END
FROM
    UNNEST(v_completion_milestone_ids) AS milestone_ids (milestone_id)
ON CONFLICT ON CONSTRAINT play_milestone_progress_primary_key
    DO UPDATE SET
        completed_at = EXCLUDED.completed_at,
        notes = CASE WHEN gameplay.mainline_play_milestone_progress.milestone_id = p_milestone_id THEN
            CASE WHEN p_replace_progress_notes THEN
                EXCLUDED.notes
            ELSE
                COALESCE(EXCLUDED.notes, gameplay.mainline_play_milestone_progress.notes)
            END
        ELSE
            gameplay.mainline_play_milestone_progress.notes
        END,
        updated_at = NOW();
    IF p_replace_decision AND p_decision_option_id IS NULL THEN
        DELETE FROM gameplay.mainline_play_milestone_decisions
        WHERE mainline_play_milestone_decisions.play_id = p_play_id
            AND mainline_play_milestone_decisions.milestone_id = p_milestone_id;
    ELSIF p_decision_option_id IS NOT NULL THEN
        INSERT INTO gameplay.mainline_play_milestone_decisions (play_id, milestone_id, decision_option_id)
            VALUES (p_play_id, p_milestone_id, p_decision_option_id)
        ON CONFLICT ON CONSTRAINT play_milestone_decisions_primary_key
            DO UPDATE SET
                decision_option_id = EXCLUDED.decision_option_id,
                updated_at = NOW();
    END IF;
    IF p_create_event THEN
        v_event_title := COALESCE(NULLIF (BTRIM(p_event_title), ''), v_target_milestone.name);
        v_event_type_id := CASE WHEN v_target_milestone.milestone_type_id = 13 THEN
            7
        ELSE
            1
        END;
        v_event_origin_id := 3;
        SELECT
            mainline_play_events.id
        INTO
            v_event_id
        FROM
            gameplay.mainline_play_events
        WHERE
            mainline_play_events.play_id = p_play_id
            AND mainline_play_events.milestone_id = p_milestone_id;
        IF v_event_id IS NULL THEN
            SELECT
                COALESCE(MAX(mainline_play_events.timeline_order), 0) + 1
            INTO
                v_next_timeline_order
            FROM
                gameplay.mainline_play_events
            WHERE
                mainline_play_events.play_id = p_play_id;
            INSERT INTO gameplay.mainline_play_events (play_id, event_type_id, event_origin_id, title, body, happened_at, timeline_order, milestone_id)
                VALUES (p_play_id, v_event_type_id, v_event_origin_id, v_event_title, p_event_body, COALESCE(p_event_happened_at, p_completed_at), v_next_timeline_order, p_milestone_id)
            RETURNING
                id
            INTO
                v_event_id;
        ELSE
            UPDATE
                gameplay.mainline_play_events
            SET
                event_type_id = v_event_type_id,
                event_origin_id = v_event_origin_id,
                title = v_event_title,
                body = COALESCE(p_event_body, gameplay.mainline_play_events.body),
                happened_at = COALESCE(p_event_happened_at, p_completed_at, gameplay.mainline_play_events.happened_at),
                updated_at = NOW()
            WHERE
                mainline_play_events.id = v_event_id
            RETURNING
                mainline_play_events.id
            INTO
                v_event_id;
        END IF;
        IF p_include_team_snapshot THEN
            DELETE FROM gameplay.mainline_play_event_team_snapshots
            WHERE event_id = v_event_id;
            INSERT INTO gameplay.mainline_play_event_team_snapshots (event_id, play_id, play_pokemon_id, position, species_id, form_id, nickname, level, gender, is_shiny, nature_id, ability_id, held_item_id)
            SELECT
                v_event_id,
                p_play_id,
                mainline_play_pokemon.id,
                mainline_play_pokemon.slot,
                mainline_play_pokemon.species_id,
                mainline_play_pokemon.form_id,
                mainline_play_pokemon.nickname,
                mainline_play_pokemon.level,
                mainline_play_pokemon.gender,
                mainline_play_pokemon.is_shiny,
                mainline_play_pokemon.nature_id,
                mainline_play_pokemon.ability_id,
                mainline_play_pokemon.held_item_id
            FROM
                gameplay.mainline_play_pokemon
            WHERE
                mainline_play_pokemon.play_id = p_play_id
                AND mainline_play_pokemon.roster_state_id = 1
                AND mainline_play_pokemon.slot BETWEEN 1 AND 6
            ORDER BY
                mainline_play_pokemon.slot;
            GET DIAGNOSTICS v_inserted_snapshot_count = ROW_COUNT;
            INSERT INTO gameplay.mainline_play_event_team_snapshot_moves (snapshot_id, slot, move_id)
            SELECT
                mainline_play_event_team_snapshots.id,
                mainline_play_pokemon_moves.slot,
                mainline_play_pokemon_moves.move_id
            FROM
                gameplay.mainline_play_event_team_snapshots
                JOIN gameplay.mainline_play_pokemon_moves ON mainline_play_pokemon_moves.play_pokemon_id = mainline_play_event_team_snapshots.play_pokemon_id
            WHERE
                mainline_play_event_team_snapshots.event_id = v_event_id
                AND mainline_play_event_team_snapshots.play_id = p_play_id
            ON CONFLICT (snapshot_id,
                slot)
                DO NOTHING;
        END IF;
    END IF;
    RETURN QUERY
    SELECT
        p_play_id,
        p_milestone_id,
        v_event_id,
        v_completion_milestone_ids,
        v_inserted_snapshot_count;
END;
$$;

REVOKE ALL ON FUNCTION gameplay.complete_mainline_play_milestone (UUID, INTEGER, TIMESTAMPTZ, TEXT, INTEGER, INTEGER[], BOOLEAN, TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, BOOLEAN, BOOLEAN) FROM PUBLIC;

REVOKE ALL ON FUNCTION gameplay.complete_mainline_play_milestone (UUID, INTEGER, TIMESTAMPTZ, TEXT, INTEGER, INTEGER[], BOOLEAN, TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, BOOLEAN, BOOLEAN) FROM anon;

GRANT EXECUTE ON FUNCTION gameplay.complete_mainline_play_milestone (UUID, INTEGER, TIMESTAMPTZ, TEXT, INTEGER, INTEGER[], BOOLEAN, TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, BOOLEAN, BOOLEAN) TO authenticated, service_role;

COMMENT ON FUNCTION gameplay.complete_mainline_play_milestone (UUID, INTEGER, TIMESTAMPTZ, TEXT, INTEGER, INTEGER[], BOOLEAN, TEXT, TEXT, TIMESTAMPTZ, BOOLEAN, BOOLEAN, BOOLEAN) IS 'Atomically completes an available play milestone, rejects unmet required or story-unlock prerequisites, optionally records the required milestones and choices before it in Story order (never in an open-world story, and without moments or decisions of their own), replaces or preserves notes and decisions explicitly, creates or updates a linked timeline event, and records or replaces its current active-team snapshot. Runs as SECURITY INVOKER so gameplay RLS still applies.';

CREATE FUNCTION gameplay.mark_mainline_play_milestone_incomplete (p_play_id uuid, p_milestone_id integer, p_expected_affected_milestone_ids integer[], p_also_clear_milestone_ids integer[] DEFAULT '{}'::integer[])
    RETURNS TABLE (
        affected_milestone_ids integer[],
        affected_milestone_count integer,
        removed_note_count integer,
        removed_decision_count integer,
        removed_history_event_count integer,
        removed_team_snapshot_count integer)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_affected_milestone_ids integer[];
    v_expected_affected_milestone_ids integer[];
    v_removed_note_count integer;
    v_removed_decision_count integer;
    v_removed_history_event_count integer;
    v_removed_team_snapshot_count integer;
    v_deleted_progress_count integer;
BEGIN
    IF p_play_id IS NULL THEN
        RAISE EXCEPTION 'play_id is required'
            USING ERRCODE = '23502';
    END IF;
    IF p_milestone_id IS NULL THEN
        RAISE EXCEPTION 'milestone_id is required'
            USING ERRCODE = '23502';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(p_play_id::text)::bigint);
    IF NOT EXISTS (
        SELECT
            1
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.id = p_play_id) THEN
    RAISE EXCEPTION 'Unknown or unavailable play_id %', p_play_id
        USING ERRCODE = '23503';
END IF;
    IF NOT EXISTS (
        SELECT
            1
        FROM
            gameplay.mainline_play_milestone_progress
        WHERE
            mainline_play_milestone_progress.play_id = p_play_id
            AND mainline_play_milestone_progress.milestone_id = p_milestone_id) THEN
    RAISE EXCEPTION 'Milestone % is not completed for play %', p_milestone_id, p_play_id
    USING ERRCODE = '23514';
END IF;
    -- The milestone, any others cleared with it (Story's "the N after it", or
    -- an Undo's "the N before it"), and everything that depends on them.
    WITH RECURSIVE dependent_closure AS (
        SELECT
            p_milestone_id AS milestone_id
        UNION
        SELECT
            also_clear_id
        FROM
            UNNEST(COALESCE(p_also_clear_milestone_ids, '{}'::integer[])) AS also_clear (also_clear_id)
        WHERE
            also_clear_id IS NOT NULL
        UNION
        SELECT
            dependent_prerequisites.milestone_id
        FROM
            dependent_closure
            JOIN tracking.mainline_milestone_prerequisites AS dependent_prerequisites ON dependent_prerequisites.prerequisite_milestone_id = dependent_closure.milestone_id
            JOIN tracking.mainline_milestone_prerequisite_kinds AS dependent_kinds ON dependent_kinds.id = dependent_prerequisites.prerequisite_kind_id
        WHERE
            dependent_kinds.slug IN ('required', 'story-unlock'))
    SELECT
        COALESCE(ARRAY_AGG(DISTINCT dependent_closure.milestone_id ORDER BY dependent_closure.milestone_id), '{}'::integer[])
    INTO
        v_affected_milestone_ids
    FROM
        dependent_closure
        JOIN gameplay.mainline_play_milestone_progress ON mainline_play_milestone_progress.play_id = p_play_id
            AND mainline_play_milestone_progress.milestone_id = dependent_closure.milestone_id;
    SELECT
        COALESCE(ARRAY_AGG(DISTINCT expected_id ORDER BY expected_id), '{}'::integer[])
    INTO
        v_expected_affected_milestone_ids
    FROM
        UNNEST(COALESCE(p_expected_affected_milestone_ids, '{}'::integer[])) AS expected (expected_id)
WHERE
    expected_id IS NOT NULL
    AND expected_id > 0;
    IF v_expected_affected_milestone_ids IS DISTINCT FROM v_affected_milestone_ids THEN
        RAISE EXCEPTION 'Milestone correction impact changed; review the updated milestone list'
            USING ERRCODE = '40001';
    END IF;
    SELECT
        COUNT(*) FILTER (WHERE NULLIF (BTRIM(mainline_play_milestone_progress.notes), '') IS NOT NULL)::integer
    INTO
        v_removed_note_count
    FROM
        gameplay.mainline_play_milestone_progress
    WHERE
        mainline_play_milestone_progress.play_id = p_play_id
        AND mainline_play_milestone_progress.milestone_id = ANY (v_affected_milestone_ids);
    SELECT
        COUNT(*)::integer
    INTO
        v_removed_decision_count
    FROM
        gameplay.mainline_play_milestone_decisions
    WHERE
        mainline_play_milestone_decisions.play_id = p_play_id
        AND mainline_play_milestone_decisions.milestone_id = ANY (v_affected_milestone_ids);
    SELECT
        COUNT(DISTINCT mainline_play_events.id)::integer,
        COUNT(DISTINCT mainline_play_events.id) FILTER (WHERE mainline_play_event_team_snapshots.event_id IS NOT NULL)::integer
    INTO
        v_removed_history_event_count,
        v_removed_team_snapshot_count
    FROM
        gameplay.mainline_play_events
    LEFT JOIN gameplay.mainline_play_event_team_snapshots ON mainline_play_event_team_snapshots.event_id = mainline_play_events.id
WHERE
    mainline_play_events.play_id = p_play_id
    AND mainline_play_events.milestone_id = ANY (v_affected_milestone_ids);
    DELETE FROM gameplay.mainline_play_events
    WHERE mainline_play_events.play_id = p_play_id
        AND mainline_play_events.milestone_id = ANY (v_affected_milestone_ids);
    DELETE FROM gameplay.mainline_play_milestone_decisions
    WHERE mainline_play_milestone_decisions.play_id = p_play_id
        AND mainline_play_milestone_decisions.milestone_id = ANY (v_affected_milestone_ids);
    DELETE FROM gameplay.mainline_play_milestone_progress
    WHERE mainline_play_milestone_progress.play_id = p_play_id
        AND mainline_play_milestone_progress.milestone_id = ANY (v_affected_milestone_ids);
    GET DIAGNOSTICS v_deleted_progress_count = ROW_COUNT;
    IF v_deleted_progress_count <> CARDINALITY(v_affected_milestone_ids) THEN
        RAISE EXCEPTION 'Milestone correction changed while it was being applied'
            USING ERRCODE = '40001';
    END IF;
    RETURN QUERY
    SELECT
        v_affected_milestone_ids,
        CARDINALITY(v_affected_milestone_ids),
        v_removed_note_count,
        v_removed_decision_count,
        v_removed_history_event_count,
        v_removed_team_snapshot_count;
END;
$$;

REVOKE ALL ON FUNCTION gameplay.mark_mainline_play_milestone_incomplete (UUID, INTEGER, INTEGER[], INTEGER[]) FROM PUBLIC;

REVOKE ALL ON FUNCTION gameplay.mark_mainline_play_milestone_incomplete (UUID, INTEGER, INTEGER[], INTEGER[]) FROM anon;

GRANT EXECUTE ON FUNCTION gameplay.mark_mainline_play_milestone_incomplete (UUID, INTEGER, INTEGER[], INTEGER[]) TO authenticated, service_role;

COMMENT ON FUNCTION gameplay.mark_mainline_play_milestone_incomplete (UUID, INTEGER, INTEGER[], INTEGER[]) IS 'Atomically marks one completed milestone, any other milestones cleared with it, and every completed transitive required or story-unlock dependent incomplete, deleting their notes, decisions, milestone-linked History events, and snapshots after validating the user-previewed impact set. Runs as SECURITY INVOKER so gameplay RLS still applies.';

-- ============================================================================
-- Source: database/schema/04_gameplay/02_functions/002_mainline_play_pokemon_mutations.sql
-- ============================================================================
-- ============================================================================
-- Functions: gameplay mainline play Pokémon mutations
-- Client-callable helpers for atomic team history writes.
-- ============================================================================
CREATE FUNCTION gameplay.add_mainline_play_pokemon (p_play_id uuid, p_roster_state_id integer, p_slot integer, p_species_id integer, p_form_id integer, p_nickname text DEFAULT NULL, p_level integer DEFAULT NULL, p_gender text DEFAULT 'unknown', p_is_shiny boolean DEFAULT FALSE, p_nature_id integer DEFAULT NULL, p_ability_id integer DEFAULT NULL, p_held_item_id integer DEFAULT NULL, p_met_location_label text DEFAULT NULL, p_met_level integer DEFAULT NULL, p_ball_item_id integer DEFAULT NULL, p_personal_notes text DEFAULT NULL, p_move_ids integer[] DEFAULT '{}'::integer[], p_create_event boolean DEFAULT TRUE, p_event_title text DEFAULT NULL, p_event_body text DEFAULT NULL, p_event_happened_at timestamptz DEFAULT NOW())
    RETURNS TABLE (
        result_play_pokemon_id uuid,
        result_event_id uuid)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play_pokemon_id uuid;
    v_event_id uuid;
    v_next_timeline_order integer;
    v_species_name text;
BEGIN
    IF p_play_id IS NULL THEN
        RAISE EXCEPTION 'play_id is required'
            USING ERRCODE = '23502';
    END IF;
    p_nickname := NULLIF (BTRIM(p_nickname), '');
    p_gender := COALESCE(NULLIF (BTRIM(p_gender), ''), 'unknown');
    p_met_location_label := NULLIF (BTRIM(p_met_location_label), '');
    p_personal_notes := NULLIF (BTRIM(p_personal_notes), '');
    p_event_title := NULLIF (BTRIM(p_event_title), '');
    p_event_body := NULLIF (BTRIM(p_event_body), '');
    p_move_ids := COALESCE(p_move_ids, '{}'::integer[]);
    IF CARDINALITY(p_move_ids) > 4 THEN
        RAISE EXCEPTION 'A play Pokémon can have at most four current moves'
            USING ERRCODE = '23514';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(p_play_id::text)::bigint);
    IF NOT EXISTS (
        SELECT
            1
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.id = p_play_id
        FOR UPDATE) THEN
RAISE EXCEPTION 'Unknown or unavailable play_id %', p_play_id
        USING ERRCODE = '23503';
END IF;
    SELECT
        pokemon_species.name
    INTO
        v_species_name
    FROM
        reference.pokemon_species
    WHERE
        pokemon_species.id = p_species_id;
    INSERT INTO gameplay.mainline_play_pokemon (play_id, roster_state_id, slot, species_id, form_id, nickname, level, gender, is_shiny, nature_id, ability_id, held_item_id, met_location_label, met_level, ball_item_id, personal_notes)
        VALUES (p_play_id, p_roster_state_id, p_slot, p_species_id, p_form_id, p_nickname, p_level, p_gender, p_is_shiny, p_nature_id, p_ability_id, p_held_item_id, p_met_location_label, p_met_level, p_ball_item_id, p_personal_notes)
    RETURNING
        id
    INTO
        v_play_pokemon_id;
    INSERT INTO gameplay.mainline_play_pokemon_moves (play_pokemon_id, slot, move_id)
    SELECT
        v_play_pokemon_id,
        moves.move_slot::integer,
        moves.move_id
    FROM
        UNNEST(p_move_ids)
    WITH ORDINALITY AS moves (move_id, move_slot)
WHERE
    moves.move_id IS NOT NULL;
    IF p_create_event THEN
        SELECT
            COALESCE(MAX(mainline_play_events.timeline_order), 0) + 1
        INTO
            v_next_timeline_order
        FROM
            gameplay.mainline_play_events
        WHERE
            mainline_play_events.play_id = p_play_id;
        INSERT INTO gameplay.mainline_play_events (play_id, event_type_id, event_origin_id, title, body, happened_at, timeline_order)
            VALUES (p_play_id, 2, 2, COALESCE(p_event_title, 'Added ' || COALESCE(v_species_name, 'Pokémon')), p_event_body, p_event_happened_at, v_next_timeline_order)
        RETURNING
            id
        INTO
            v_event_id;
        INSERT INTO gameplay.mainline_play_event_pokemon_refs (event_id, play_id, play_pokemon_id, role, species_id, form_id, nickname, level, sort_order)
            VALUES (v_event_id, p_play_id, v_play_pokemon_id, 'subject', p_species_id, p_form_id, p_nickname, p_level, 1);
    END IF;
    RETURN QUERY
    SELECT
        v_play_pokemon_id,
        v_event_id;
END;
$$;

CREATE FUNCTION gameplay.evolve_mainline_play_pokemon (p_play_pokemon_id uuid, p_to_species_id integer, p_to_form_id integer, p_level integer DEFAULT NULL, p_event_title text DEFAULT NULL, p_event_body text DEFAULT NULL, p_event_happened_at timestamptz DEFAULT NOW())
    RETURNS TABLE (
        result_play_pokemon_id uuid,
        result_event_id uuid,
        result_from_species_id integer,
        result_from_form_id integer,
        result_to_species_id integer,
        result_to_form_id integer)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play_pokemon gameplay.mainline_play_pokemon%ROWTYPE;
    v_event_id uuid;
    v_next_timeline_order integer;
    v_from_species_name text;
    v_to_species_name text;
BEGIN
    p_event_title := NULLIF (BTRIM(p_event_title), '');
    p_event_body := NULLIF (BTRIM(p_event_body), '');
    SELECT
        mainline_play_pokemon.*
    INTO
        v_play_pokemon
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id
    FOR UPDATE;
    IF v_play_pokemon.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_pokemon_id %', p_play_pokemon_id
            USING ERRCODE = '23503';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_play_pokemon.play_id::text)::bigint);
    SELECT
        pokemon_species.name
    INTO
        v_from_species_name
    FROM
        reference.pokemon_species
    WHERE
        pokemon_species.id = v_play_pokemon.species_id;
    SELECT
        pokemon_species.name
    INTO
        v_to_species_name
    FROM
        reference.pokemon_species
    WHERE
        pokemon_species.id = p_to_species_id;
    SELECT
        COALESCE(MAX(mainline_play_events.timeline_order), 0) + 1
    INTO
        v_next_timeline_order
    FROM
        gameplay.mainline_play_events
    WHERE
        mainline_play_events.play_id = v_play_pokemon.play_id;
    INSERT INTO gameplay.mainline_play_events (play_id, event_type_id, event_origin_id, title, body, happened_at, timeline_order)
        VALUES (v_play_pokemon.play_id, 3, 2, COALESCE(p_event_title, COALESCE(v_from_species_name, 'Pokémon') || ' evolved into ' || COALESCE(v_to_species_name, 'Pokémon')), p_event_body, p_event_happened_at, v_next_timeline_order)
    RETURNING
        id
    INTO
        v_event_id;
    INSERT INTO gameplay.mainline_play_event_pokemon_refs (event_id, play_id, play_pokemon_id, role, species_id, form_id, nickname, level, sort_order)
    VALUES
        (v_event_id, v_play_pokemon.play_id, p_play_pokemon_id, 'from', v_play_pokemon.species_id, v_play_pokemon.form_id, v_play_pokemon.nickname, COALESCE(p_level, v_play_pokemon.level), 1),
        (v_event_id, v_play_pokemon.play_id, p_play_pokemon_id, 'to', p_to_species_id, p_to_form_id, v_play_pokemon.nickname, COALESCE(p_level, v_play_pokemon.level), 2);
    UPDATE
        gameplay.mainline_play_pokemon
    SET
        species_id = p_to_species_id,
        form_id = p_to_form_id,
        level = COALESCE(p_level, gameplay.mainline_play_pokemon.level),
        updated_at = NOW()
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id;
    RETURN QUERY
    SELECT
        p_play_pokemon_id,
        v_event_id,
        v_play_pokemon.species_id,
        v_play_pokemon.form_id,
        p_to_species_id,
        p_to_form_id;
END;
$$;

CREATE FUNCTION gameplay.change_mainline_play_pokemon_form (p_play_pokemon_id uuid, p_to_form_id integer, p_level integer DEFAULT NULL, p_held_item_id integer DEFAULT NULL, p_clear_held_item boolean DEFAULT FALSE, p_event_title text DEFAULT NULL, p_event_body text DEFAULT NULL, p_event_happened_at timestamptz DEFAULT NOW())
    RETURNS TABLE (
        result_play_pokemon_id uuid,
        result_event_id uuid,
        result_species_id integer,
        result_from_form_id integer,
        result_to_form_id integer)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play_pokemon gameplay.mainline_play_pokemon%ROWTYPE;
    v_event_id uuid;
    v_next_timeline_order integer;
    v_species_name text;
BEGIN
    p_event_title := NULLIF (BTRIM(p_event_title), '');
    p_event_body := NULLIF (BTRIM(p_event_body), '');
    SELECT
        mainline_play_pokemon.*
    INTO
        v_play_pokemon
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id
    FOR UPDATE;
    IF v_play_pokemon.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_pokemon_id %', p_play_pokemon_id
            USING ERRCODE = '23503';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_play_pokemon.play_id::text)::bigint);
    SELECT
        pokemon_species.name
    INTO
        v_species_name
    FROM
        reference.pokemon_species
    WHERE
        pokemon_species.id = v_play_pokemon.species_id;
    SELECT
        COALESCE(MAX(mainline_play_events.timeline_order), 0) + 1
    INTO
        v_next_timeline_order
    FROM
        gameplay.mainline_play_events
    WHERE
        mainline_play_events.play_id = v_play_pokemon.play_id;
    INSERT INTO gameplay.mainline_play_events (play_id, event_type_id, event_origin_id, title, body, happened_at, timeline_order)
        VALUES (v_play_pokemon.play_id, 6, 2, COALESCE(p_event_title, COALESCE(v_species_name, 'Pokémon') || ' changed form'), p_event_body, p_event_happened_at, v_next_timeline_order)
    RETURNING
        id
    INTO
        v_event_id;
    INSERT INTO gameplay.mainline_play_event_pokemon_refs (event_id, play_id, play_pokemon_id, role, species_id, form_id, nickname, level, sort_order)
    VALUES
        (v_event_id, v_play_pokemon.play_id, p_play_pokemon_id, 'from', v_play_pokemon.species_id, v_play_pokemon.form_id, v_play_pokemon.nickname, COALESCE(p_level, v_play_pokemon.level), 1),
        (v_event_id, v_play_pokemon.play_id, p_play_pokemon_id, 'to', v_play_pokemon.species_id, p_to_form_id, v_play_pokemon.nickname, COALESCE(p_level, v_play_pokemon.level), 2);
    UPDATE
        gameplay.mainline_play_pokemon
    SET
        form_id = p_to_form_id,
        level = COALESCE(p_level, gameplay.mainline_play_pokemon.level),
        held_item_id = CASE WHEN p_clear_held_item THEN
            NULL
        WHEN p_held_item_id IS NOT NULL THEN
            p_held_item_id
        ELSE
            gameplay.mainline_play_pokemon.held_item_id
        END,
        tera_type_id = CASE WHEN gameplay.mainline_play_pokemon.tera_type_id IS NULL THEN
            NULL
        ELSE
            COALESCE((
                SELECT
                    pokemon_fixed_tera_types.tera_type_id
                FROM reference.pokemon_fixed_tera_types
                WHERE
                    pokemon_fixed_tera_types.form_id = p_to_form_id), gameplay.mainline_play_pokemon.tera_type_id)
        END,
        updated_at = NOW()
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id;
    RETURN QUERY
    SELECT
        p_play_pokemon_id,
        v_event_id,
        v_play_pokemon.species_id,
        v_play_pokemon.form_id,
        p_to_form_id;
END;
$$;

CREATE FUNCTION gameplay.retire_mainline_play_pokemon (p_play_pokemon_id uuid, p_final_status text DEFAULT 'retired', p_create_event boolean DEFAULT TRUE, p_event_title text DEFAULT NULL, p_event_body text DEFAULT NULL, p_event_happened_at timestamptz DEFAULT NOW())
    RETURNS TABLE (
        result_play_pokemon_id uuid,
        result_event_id uuid)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play_pokemon gameplay.mainline_play_pokemon%ROWTYPE;
    v_event_id uuid;
    v_next_timeline_order integer;
    v_species_name text;
BEGIN
    p_final_status := COALESCE(NULLIF (BTRIM(p_final_status), ''), 'retired');
    p_event_title := NULLIF (BTRIM(p_event_title), '');
    p_event_body := NULLIF (BTRIM(p_event_body), '');
    SELECT
        mainline_play_pokemon.*
    INTO
        v_play_pokemon
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id
    FOR UPDATE;
    IF v_play_pokemon.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_pokemon_id %', p_play_pokemon_id
            USING ERRCODE = '23503';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_play_pokemon.play_id::text)::bigint);
    SELECT
        pokemon_species.name
    INTO
        v_species_name
    FROM
        reference.pokemon_species
    WHERE
        pokemon_species.id = v_play_pokemon.species_id;
    UPDATE
        gameplay.mainline_play_pokemon
    SET
        roster_state_id = 3,
        slot = NULL,
        final_status = p_final_status,
        updated_at = NOW()
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id;
    IF p_create_event THEN
        SELECT
            COALESCE(MAX(mainline_play_events.timeline_order), 0) + 1
        INTO
            v_next_timeline_order
        FROM
            gameplay.mainline_play_events
        WHERE
            mainline_play_events.play_id = v_play_pokemon.play_id;
        INSERT INTO gameplay.mainline_play_events (play_id, event_type_id, event_origin_id, title, body, happened_at, timeline_order)
            VALUES (v_play_pokemon.play_id, 4, 2, COALESCE(p_event_title, 'Retired ' || COALESCE(v_species_name, 'Pokémon')), p_event_body, p_event_happened_at, v_next_timeline_order)
        RETURNING
            id
        INTO
            v_event_id;
        INSERT INTO gameplay.mainline_play_event_pokemon_refs (event_id, play_id, play_pokemon_id, role, species_id, form_id, nickname, level, sort_order)
            VALUES (v_event_id, v_play_pokemon.play_id, p_play_pokemon_id, 'subject', v_play_pokemon.species_id, v_play_pokemon.form_id, v_play_pokemon.nickname, v_play_pokemon.level, 1);
    END IF;
    RETURN QUERY
    SELECT
        p_play_pokemon_id,
        v_event_id;
END;
$$;

CREATE FUNCTION gameplay.replace_mainline_play_pokemon (p_replaced_play_pokemon_id uuid, p_replacement_species_id integer, p_replacement_form_id integer, p_replacement_roster_state_id integer DEFAULT NULL, p_replacement_slot integer DEFAULT NULL, p_replacement_nickname text DEFAULT NULL, p_replacement_level integer DEFAULT NULL, p_replacement_gender text DEFAULT 'unknown', p_replacement_is_shiny boolean DEFAULT FALSE, p_replacement_nature_id integer DEFAULT NULL, p_replacement_ability_id integer DEFAULT NULL, p_replacement_held_item_id integer DEFAULT NULL, p_replacement_met_location_label text DEFAULT NULL, p_replacement_met_level integer DEFAULT NULL, p_replacement_ball_item_id integer DEFAULT NULL, p_replacement_personal_notes text DEFAULT NULL, p_replacement_move_ids integer[] DEFAULT '{}'::integer[], p_replaced_final_status text DEFAULT 'replaced', p_create_event boolean DEFAULT TRUE, p_event_title text DEFAULT NULL, p_event_body text DEFAULT NULL, p_event_happened_at timestamptz DEFAULT NOW())
    RETURNS TABLE (
        result_replaced_play_pokemon_id uuid,
        result_replacement_play_pokemon_id uuid,
        result_event_id uuid)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_replaced_pokemon gameplay.mainline_play_pokemon%ROWTYPE;
    v_replacement_play_pokemon_id uuid;
    v_replacement_roster_state_id integer;
    v_replacement_slot integer;
    v_event_id uuid;
    v_next_timeline_order integer;
    v_replaced_species_name text;
    v_replacement_species_name text;
BEGIN
    p_replacement_nickname := NULLIF (BTRIM(p_replacement_nickname), '');
    p_replacement_gender := COALESCE(NULLIF (BTRIM(p_replacement_gender), ''), 'unknown');
    p_replacement_met_location_label := NULLIF (BTRIM(p_replacement_met_location_label), '');
    p_replacement_personal_notes := NULLIF (BTRIM(p_replacement_personal_notes), '');
    p_replaced_final_status := COALESCE(NULLIF (BTRIM(p_replaced_final_status), ''), 'replaced');
    p_event_title := NULLIF (BTRIM(p_event_title), '');
    p_event_body := NULLIF (BTRIM(p_event_body), '');
    p_replacement_move_ids := COALESCE(p_replacement_move_ids, '{}'::integer[]);
    IF CARDINALITY(p_replacement_move_ids) > 4 THEN
        RAISE EXCEPTION 'A play Pokémon can have at most four current moves'
            USING ERRCODE = '23514';
    END IF;
    SELECT
        mainline_play_pokemon.*
    INTO
        v_replaced_pokemon
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id = p_replaced_play_pokemon_id
    FOR UPDATE;
    IF v_replaced_pokemon.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_pokemon_id %', p_replaced_play_pokemon_id
            USING ERRCODE = '23503';
    END IF;
    IF v_replaced_pokemon.roster_state_id NOT IN (1, 2) OR v_replaced_pokemon.slot IS NULL THEN
        RAISE EXCEPTION 'Only current active or reserve Pokémon can be replaced'
            USING ERRCODE = '23514';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_replaced_pokemon.play_id::text)::bigint);
    v_replacement_roster_state_id := COALESCE(p_replacement_roster_state_id, v_replaced_pokemon.roster_state_id);
    v_replacement_slot := COALESCE(p_replacement_slot, v_replaced_pokemon.slot);
    SELECT
        pokemon_species.name
    INTO
        v_replaced_species_name
    FROM
        reference.pokemon_species
    WHERE
        pokemon_species.id = v_replaced_pokemon.species_id;
    SELECT
        pokemon_species.name
    INTO
        v_replacement_species_name
    FROM
        reference.pokemon_species
    WHERE
        pokemon_species.id = p_replacement_species_id;
    UPDATE
        gameplay.mainline_play_pokemon
    SET
        roster_state_id = 4,
        slot = NULL,
        final_status = p_replaced_final_status,
        updated_at = NOW()
    WHERE
        mainline_play_pokemon.id = p_replaced_play_pokemon_id;
    INSERT INTO gameplay.mainline_play_pokemon (play_id, roster_state_id, slot, species_id, form_id, nickname, level, gender, is_shiny, nature_id, ability_id, held_item_id, met_location_label, met_level, ball_item_id, personal_notes)
        VALUES (v_replaced_pokemon.play_id, v_replacement_roster_state_id, v_replacement_slot, p_replacement_species_id, p_replacement_form_id, p_replacement_nickname, p_replacement_level, p_replacement_gender, p_replacement_is_shiny, p_replacement_nature_id, p_replacement_ability_id, p_replacement_held_item_id, p_replacement_met_location_label, p_replacement_met_level, p_replacement_ball_item_id, p_replacement_personal_notes)
    RETURNING
        id
    INTO
        v_replacement_play_pokemon_id;
    INSERT INTO gameplay.mainline_play_pokemon_moves (play_pokemon_id, slot, move_id)
    SELECT
        v_replacement_play_pokemon_id,
        moves.move_slot::integer,
        moves.move_id
    FROM
        UNNEST(p_replacement_move_ids)
    WITH ORDINALITY AS moves (move_id, move_slot)
WHERE
    moves.move_id IS NOT NULL;
    IF p_create_event THEN
        SELECT
            COALESCE(MAX(mainline_play_events.timeline_order), 0) + 1
        INTO
            v_next_timeline_order
        FROM
            gameplay.mainline_play_events
        WHERE
            mainline_play_events.play_id = v_replaced_pokemon.play_id;
        INSERT INTO gameplay.mainline_play_events (play_id, event_type_id, event_origin_id, title, body, happened_at, timeline_order)
            VALUES (v_replaced_pokemon.play_id, 5, 2, COALESCE(p_event_title, 'Replaced ' || COALESCE(v_replaced_species_name, 'Pokémon') || ' with ' || COALESCE(v_replacement_species_name, 'Pokémon')), p_event_body, p_event_happened_at, v_next_timeline_order)
        RETURNING
            id
        INTO
            v_event_id;
        INSERT INTO gameplay.mainline_play_event_pokemon_refs (event_id, play_id, play_pokemon_id, role, species_id, form_id, nickname, level, sort_order)
        VALUES
            (v_event_id, v_replaced_pokemon.play_id, p_replaced_play_pokemon_id, 'replaced', v_replaced_pokemon.species_id, v_replaced_pokemon.form_id, v_replaced_pokemon.nickname, v_replaced_pokemon.level, 1),
            (v_event_id, v_replaced_pokemon.play_id, v_replacement_play_pokemon_id, 'replacement', p_replacement_species_id, p_replacement_form_id, p_replacement_nickname, p_replacement_level, 2);
    END IF;
    RETURN QUERY
    SELECT
        p_replaced_play_pokemon_id,
        v_replacement_play_pokemon_id,
        v_event_id;
END;
$$;

CREATE FUNCTION gameplay.update_mainline_play_pokemon (p_play_pokemon_id uuid, p_nickname text DEFAULT NULL, p_level integer DEFAULT NULL, p_gender text DEFAULT 'unknown', p_is_shiny boolean DEFAULT FALSE, p_nature_id integer DEFAULT NULL, p_ability_id integer DEFAULT NULL, p_held_item_id integer DEFAULT NULL, p_met_location_label text DEFAULT NULL, p_met_level integer DEFAULT NULL, p_ball_item_id integer DEFAULT NULL, p_personal_notes text DEFAULT NULL, p_move_ids integer[] DEFAULT '{}'::integer[], p_tera_type_id integer DEFAULT NULL, p_has_gigantamax_factor boolean DEFAULT FALSE)
    RETURNS TABLE (
        result_play_pokemon_id uuid,
        result_move_count integer)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play_pokemon gameplay.mainline_play_pokemon%ROWTYPE;
    v_move_count integer;
    v_form_id integer;
    v_generation_id integer;
    v_version_group_id integer;
BEGIN
    IF p_play_pokemon_id IS NULL THEN
        RAISE EXCEPTION 'play_pokemon_id is required'
            USING ERRCODE = '23502';
    END IF;
    p_nickname := NULLIF (BTRIM(p_nickname), '');
    p_gender := COALESCE(NULLIF (BTRIM(p_gender), ''), 'unknown');
    p_met_location_label := NULLIF (BTRIM(p_met_location_label), '');
    p_personal_notes := NULLIF (BTRIM(p_personal_notes), '');
    p_move_ids := COALESCE(p_move_ids, '{}'::integer[]);
    IF CARDINALITY(p_move_ids) > 4 THEN
        RAISE EXCEPTION 'A play Pokémon can have at most four current moves'
            USING ERRCODE = '23514';
    END IF;
    SELECT
        mainline_play_pokemon.*
    INTO
        v_play_pokemon
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id
    FOR UPDATE;
    IF v_play_pokemon.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_pokemon_id %', p_play_pokemon_id
            USING ERRCODE = '23503';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_play_pokemon.play_id::text)::bigint);
    SELECT
        version_groups.generation_id,
        mainline_plays.version_group_id
    INTO
        v_generation_id,
        v_version_group_id
    FROM
        gameplay.mainline_plays
        JOIN reference.version_groups ON version_groups.id = mainline_plays.version_group_id
    WHERE
        mainline_plays.id = v_play_pokemon.play_id;
    -- A form driven by a held item follows a change of held item in the
    -- Play's game (Arceus's Plates, Silvally's Memories, Genesect's Drives,
    -- Ogerpon's masks): taking one selects its form, and taking away the item
    -- that selected the current form brings back the default. A game without
    -- held items never changes it here.
    WITH held_item_forms AS (
        SELECT
            requirements.form_id,
            requirements.item_id
        FROM
            reference.pokemon_form_item_requirements AS requirements
            JOIN reference.pokemon_forms ON pokemon_forms.id = requirements.form_id
            JOIN reference.pokemon_form_rules ON pokemon_form_rules.form_id = requirements.form_id
        WHERE
            pokemon_forms.species_id = v_play_pokemon.species_id
            AND pokemon_form_rules.form_class = 'form'
            AND requirements.requirement_kind IN ('required_held_item', 'alternative_held_item')
            AND requirements.generation_start_id <= v_generation_id
            AND (requirements.generation_end_id IS NULL
                OR requirements.generation_end_id >= v_generation_id)
            AND (requirements.version_group_start_id IS NULL
                OR requirements.version_group_start_id <= v_version_group_id)
            AND (requirements.version_group_end_id IS NULL
                OR requirements.version_group_end_id >= v_version_group_id))
    SELECT
        COALESCE((
            SELECT
                held_item_forms.form_id
            FROM held_item_forms
            WHERE
                held_item_forms.item_id = p_held_item_id ORDER BY held_item_forms.form_id LIMIT 1), CASE WHEN EXISTS (
        SELECT
            1
        FROM held_item_forms
    WHERE
        held_item_forms.form_id = v_play_pokemon.form_id
        AND held_item_forms.item_id = v_play_pokemon.held_item_id) THEN
(
    SELECT
        pokemon_forms.id
    FROM reference.pokemon_forms
WHERE
    pokemon_forms.species_id = v_play_pokemon.species_id
        AND pokemon_forms.is_default)
    END, v_play_pokemon.form_id)
    INTO
        v_form_id;
    UPDATE
        gameplay.mainline_play_pokemon
    SET
        nickname = p_nickname,
        level = p_level,
        gender = p_gender,
        is_shiny = COALESCE(p_is_shiny, FALSE),
        nature_id = p_nature_id,
        ability_id = p_ability_id,
        form_id = v_form_id,
        held_item_id = p_held_item_id,
        -- When the held item changes its form, a recorded Tera Type follows a
        -- form whose Tera Type is fixed.
        tera_type_id = CASE WHEN p_tera_type_id IS NULL
            OR v_form_id = v_play_pokemon.form_id THEN
            p_tera_type_id
        ELSE
            COALESCE((
                SELECT
                    pokemon_fixed_tera_types.tera_type_id
                FROM reference.pokemon_fixed_tera_types
                WHERE
                    pokemon_fixed_tera_types.form_id = v_form_id), p_tera_type_id)
        END,
        has_gigantamax_factor = COALESCE(p_has_gigantamax_factor, FALSE),
        met_location_label = p_met_location_label,
        met_level = p_met_level,
        ball_item_id = p_ball_item_id,
        personal_notes = p_personal_notes
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id;
    DELETE FROM gameplay.mainline_play_pokemon_moves
    WHERE mainline_play_pokemon_moves.play_pokemon_id = p_play_pokemon_id;
    INSERT INTO gameplay.mainline_play_pokemon_moves (play_pokemon_id, slot, move_id)
    SELECT
        p_play_pokemon_id,
        moves.move_slot::integer,
        moves.move_id
    FROM
        UNNEST(p_move_ids)
    WITH ORDINALITY AS moves (move_id, move_slot)
WHERE
    moves.move_id IS NOT NULL;
    GET DIAGNOSTICS v_move_count = ROW_COUNT;
    RETURN QUERY
    SELECT
        p_play_pokemon_id,
        v_move_count;
END;
$$;

CREATE FUNCTION gameplay.move_mainline_play_pokemon (p_play_pokemon_id uuid, p_to_slot integer)
    RETURNS TABLE (
        result_play_pokemon_id uuid,
        result_swapped_play_pokemon_id uuid)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play_pokemon gameplay.mainline_play_pokemon%ROWTYPE;
    v_occupant_id uuid;
    v_locked_occupant_id uuid;
BEGIN
    IF p_play_pokemon_id IS NULL THEN
        RAISE EXCEPTION 'play_pokemon_id is required'
            USING ERRCODE = '23502';
    END IF;
    IF p_to_slot IS NULL OR p_to_slot NOT BETWEEN 1 AND 12 THEN
        RAISE EXCEPTION 'A roster slot runs from 1 to 12'
            USING ERRCODE = '23514';
    END IF;
    SELECT
        mainline_play_pokemon.*
    INTO
        v_play_pokemon
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id;
    IF v_play_pokemon.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_pokemon_id %', p_play_pokemon_id
            USING ERRCODE = '23503';
    END IF;
    SELECT
        mainline_play_pokemon.id
    INTO
        v_occupant_id
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.play_id = v_play_pokemon.play_id
        AND mainline_play_pokemon.slot = p_to_slot
        AND mainline_play_pokemon.id <> p_play_pokemon_id;
    -- Rows first, then the Play lock, in the order every roster function
    -- takes them, so a move never waits on a row while holding the Play.
    -- Both rows lock in id order, so two crossing moves queue.
    PERFORM
        1
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id IN (p_play_pokemon_id, v_occupant_id)
    ORDER BY
        mainline_play_pokemon.id
    FOR UPDATE;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_play_pokemon.play_id::text)::bigint);
    -- Read again under the locks: another write may have landed meanwhile.
    SELECT
        mainline_play_pokemon.*
    INTO
        v_play_pokemon
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id;
    IF v_play_pokemon.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_pokemon_id %', p_play_pokemon_id
            USING ERRCODE = '23503';
    END IF;
    IF v_play_pokemon.slot IS NULL THEN
        RAISE EXCEPTION 'Only team and reserve Pokémon can move'
            USING ERRCODE = '23514';
    END IF;
    IF v_play_pokemon.slot = p_to_slot THEN
        RETURN QUERY
        SELECT
            p_play_pokemon_id,
            NULL::uuid;
        RETURN;
    END IF;
    SELECT
        mainline_play_pokemon.id
    INTO
        v_locked_occupant_id
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.play_id = v_play_pokemon.play_id
        AND mainline_play_pokemon.slot = p_to_slot;
    IF v_locked_occupant_id IS DISTINCT FROM v_occupant_id THEN
        RAISE EXCEPTION 'The roster changed while moving'
            USING ERRCODE = '40001', HINT = 'Try the move again.';
    END IF;
    -- The team keeps at least one Pokémon: a team Pokémon may leave for an
    -- empty reserve slot only while another Pokémon stays on the team.
    IF v_play_pokemon.slot <= 6 AND p_to_slot >= 7 AND v_occupant_id IS NULL AND NOT EXISTS (
        SELECT
            1
        FROM
            gameplay.mainline_play_pokemon
        WHERE
            mainline_play_pokemon.play_id = v_play_pokemon.play_id AND mainline_play_pokemon.roster_state_id = 1 AND mainline_play_pokemon.id <> p_play_pokemon_id) THEN
        RAISE EXCEPTION 'The team needs at least one Pokémon'
            USING ERRCODE = '23514', HINT = 'team-needs-one';
    END IF;
    -- One statement moves both Pokémon; the deferrable slot constraint is
    -- checked once both have their new slots. The state follows the slot.
    UPDATE
        gameplay.mainline_play_pokemon
    SET
        slot = placements.to_slot,
        roster_state_id = CASE WHEN placements.to_slot <= 6 THEN
            1
        ELSE
            2
        END
    FROM (
        VALUES (p_play_pokemon_id, p_to_slot),
            (v_occupant_id, v_play_pokemon.slot)) AS placements (play_pokemon_id, to_slot)
WHERE
    mainline_play_pokemon.id = placements.play_pokemon_id;
    RETURN QUERY
    SELECT
        p_play_pokemon_id,
        v_occupant_id;
END;
$$;

CREATE FUNCTION gameplay.remove_mainline_play_pokemon (p_play_pokemon_id uuid, p_remove_added_moment boolean DEFAULT FALSE)
    RETURNS TABLE (
        result_play_pokemon_id uuid,
        result_removed_event_ids uuid[])
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play_pokemon gameplay.mainline_play_pokemon%ROWTYPE;
    v_removed_event_ids uuid[] := '{}'::uuid[];
BEGIN
    IF p_play_pokemon_id IS NULL THEN
        RAISE EXCEPTION 'play_pokemon_id is required'
            USING ERRCODE = '23502';
    END IF;
    SELECT
        mainline_play_pokemon.*
    INTO
        v_play_pokemon
    FROM
        gameplay.mainline_play_pokemon
    WHERE
        mainline_play_pokemon.id = p_play_pokemon_id
    FOR UPDATE;
    IF v_play_pokemon.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_pokemon_id %', p_play_pokemon_id
            USING ERRCODE = '23503';
    END IF;
    PERFORM
        pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_play_pokemon.play_id::text)::bigint);
    -- Only this Pokémon's own Added moments: events of type pokemon_added
    -- whose subject is this Pokémon. Its other moments stay in History.
    IF COALESCE(p_remove_added_moment, FALSE) THEN
        WITH removed_events AS (
            DELETE FROM gameplay.mainline_play_events
            WHERE mainline_play_events.play_id = v_play_pokemon.play_id
                AND mainline_play_events.event_type_id = 2
                AND EXISTS (
                    SELECT
                        1
                    FROM
                        gameplay.mainline_play_event_pokemon_refs
                    WHERE
                        mainline_play_event_pokemon_refs.event_id = mainline_play_events.id
                        AND mainline_play_event_pokemon_refs.play_pokemon_id = p_play_pokemon_id
                        AND mainline_play_event_pokemon_refs.role = 'subject')
                RETURNING
                    mainline_play_events.id
)
        SELECT
            COALESCE(ARRAY_AGG(removed_events.id ORDER BY removed_events.id), '{}'::uuid[])
        INTO
            v_removed_event_ids
        FROM
            removed_events;
    END IF;
    DELETE FROM gameplay.mainline_play_pokemon
    WHERE mainline_play_pokemon.id = p_play_pokemon_id;
    RETURN QUERY
    SELECT
        p_play_pokemon_id,
        v_removed_event_ids;
END;
$$;

