-- ============================================================================
-- Source: database/schema/05_planning/01_tables/001_mainline_team_plan_statuses.sql
-- ============================================================================
-- ============================================================================
-- Table: planning.mainline_team_plan_statuses
-- Team plan lifecycle status lookup.
-- ============================================================================
CREATE TABLE planning.mainline_team_plan_statuses (
    id integer PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    name text NOT NULL UNIQUE,
    sort_order integer NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT team_plan_statuses_id_positive_check CHECK (id > 0),
    CONSTRAINT team_plan_statuses_slug_format_check CHECK (slug = LOWER(slug) AND slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND CHAR_LENGTH(slug) <= 80),
    CONSTRAINT team_plan_statuses_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 120),
    CONSTRAINT team_plan_statuses_sort_order_positive_check CHECK (sort_order > 0)
);

COMMENT ON TABLE planning.mainline_team_plan_statuses IS 'Lookup for team plan lifecycle states such as draft, active, and archived.';

-- ============================================================================
-- Source: database/schema/05_planning/01_tables/002_mainline_team_plans.sql
-- ============================================================================
-- ============================================================================
-- Table: planning.mainline_team_plans
-- User-owned reusable team plans.
-- ============================================================================
CREATE TABLE planning.mainline_team_plans (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid (),
    user_id uuid NOT NULL REFERENCES public.profiles (id) ON UPDATE CASCADE ON DELETE CASCADE,
    game_id integer NOT NULL,
    version_group_id integer NOT NULL,
    status_id integer NOT NULL REFERENCES planning.mainline_team_plan_statuses (id) ON UPDATE CASCADE ON DELETE RESTRICT DEFAULT 1,
    name text NOT NULL,
    notes text,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    updated_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT team_plans_game_version_group_fkey FOREIGN KEY (game_id, version_group_id) REFERENCES reference.games (id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT team_plans_id_user_unique UNIQUE (id, user_id),
    CONSTRAINT team_plans_id_game_unique UNIQUE (id, game_id),
    CONSTRAINT team_plans_id_user_game_version_group_unique UNIQUE (id, user_id, game_id, version_group_id),
    CONSTRAINT team_plans_name_length_check CHECK (CHAR_LENGTH(BTRIM(name)) BETWEEN 1 AND 200),
    CONSTRAINT team_plans_notes_length_check CHECK (notes IS NULL OR CHAR_LENGTH(BTRIM(notes)) BETWEEN 1 AND 10000)
);

CREATE TRIGGER set_team_plans_updated_at
    BEFORE UPDATE ON planning.mainline_team_plans
    FOR EACH ROW
    EXECUTE FUNCTION private.set_updated_at ();

CREATE INDEX team_plans_user_updated_at_idx ON planning.mainline_team_plans (user_id, updated_at DESC);

CREATE INDEX team_plans_user_status_idx ON planning.mainline_team_plans (user_id, status_id);

CREATE INDEX team_plans_status_idx ON planning.mainline_team_plans (status_id);

CREATE INDEX team_plans_user_game_idx ON planning.mainline_team_plans (user_id, game_id);

CREATE INDEX team_plans_game_version_group_idx ON planning.mainline_team_plans (game_id, version_group_id);

CREATE INDEX team_plans_user_version_group_idx ON planning.mainline_team_plans (user_id, version_group_id);

CREATE INDEX team_plans_version_group_idx ON planning.mainline_team_plans (version_group_id);

COMMENT ON TABLE planning.mainline_team_plans IS 'Reusable user-owned Pokémon team plan for a game and base version group.';

COMMENT ON COLUMN planning.mainline_team_plans.version_group_id IS 'Stored with game_id so optional content and availability joins can use composite integrity.';

-- ============================================================================
-- Source: database/schema/05_planning/01_tables/003_mainline_team_plan_optional_content_scopes.sql
-- ============================================================================
-- ============================================================================
-- Table: planning.mainline_team_plan_optional_content_scopes
-- Optional content selected for a team plan.
-- ============================================================================
CREATE TABLE planning.mainline_team_plan_optional_content_scopes (
    team_plan_id uuid NOT NULL,
    game_id integer NOT NULL,
    version_group_id integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT team_plan_optional_content_scopes_primary_key PRIMARY KEY (team_plan_id, version_group_id),
    CONSTRAINT team_plan_optional_content_scopes_plan_game_fkey FOREIGN KEY (team_plan_id, game_id) REFERENCES planning.mainline_team_plans (id, game_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT team_plan_optional_content_scopes_game_scope_fkey FOREIGN KEY (game_id, version_group_id) REFERENCES reference.game_content_scopes (game_id, version_group_id) ON UPDATE CASCADE ON DELETE RESTRICT
);

COMMENT ON TABLE planning.mainline_team_plan_optional_content_scopes IS 'Optional game content scopes such as DLC selected for a team plan. The base content scope is implied by planning.mainline_team_plans.';

COMMENT ON COLUMN planning.mainline_team_plan_optional_content_scopes.game_id IS 'Duplicated from the plan to enforce game-specific content-scope validity with a composite FK.';

CREATE FUNCTION private.enforce_team_plan_optional_content_scope ()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path = ''
    AS $$
DECLARE
    is_base boolean;
BEGIN
    SELECT
        game_content_scopes.is_base_scope
    INTO
        is_base
    FROM
        reference.game_content_scopes
    WHERE
        game_content_scopes.game_id = NEW.game_id
        AND game_content_scopes.version_group_id = NEW.version_group_id;
    IF is_base IS NULL THEN
        RAISE EXCEPTION 'Version group % is not a content scope for game %', NEW.version_group_id, NEW.game_id
            USING ERRCODE = '23503';
    END IF;
    IF is_base THEN
        RAISE EXCEPTION 'Base version group % for game % is implied by the plan and cannot be inserted as optional content', NEW.version_group_id, NEW.game_id
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION private.enforce_team_plan_optional_content_scope () FROM PUBLIC;

REVOKE ALL ON FUNCTION private.enforce_team_plan_optional_content_scope () FROM anon;

REVOKE ALL ON FUNCTION private.enforce_team_plan_optional_content_scope () FROM authenticated;

GRANT EXECUTE ON FUNCTION private.enforce_team_plan_optional_content_scope () TO service_role;

CREATE TRIGGER enforce_team_plan_optional_content_scope
    BEFORE INSERT OR UPDATE OF game_id,
    version_group_id ON planning.mainline_team_plan_optional_content_scopes
    FOR EACH ROW
    EXECUTE FUNCTION private.enforce_team_plan_optional_content_scope ();

CREATE INDEX team_plan_optional_content_scopes_plan_game_idx ON planning.mainline_team_plan_optional_content_scopes (team_plan_id, game_id);

CREATE INDEX team_plan_optional_content_scopes_game_scope_idx ON planning.mainline_team_plan_optional_content_scopes (game_id, version_group_id);

CREATE INDEX team_plan_optional_content_scopes_version_group_idx ON planning.mainline_team_plan_optional_content_scopes (version_group_id);

COMMENT ON FUNCTION private.enforce_team_plan_optional_content_scope () IS 'Prevents inserting a team plan base content scope as optional content.';

