-- Source: database/schema/05_planning/01_tables/006_mainline_play_plan_links.sql
-- ============================================================================
-- ============================================================================
-- Table: planning.mainline_play_plan_links
-- Links mainline plays to their single reusable team plan.
-- ============================================================================
CREATE TABLE planning.mainline_play_plan_links (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid (),
    play_id uuid NOT NULL,
    team_plan_id uuid NOT NULL,
    user_id uuid NOT NULL,
    game_id integer NOT NULL,
    version_group_id integer NOT NULL,
    created_from_plan boolean NOT NULL DEFAULT FALSE,
    created_at timestamptz NOT NULL DEFAULT NOW(),
    CONSTRAINT play_plan_links_play_scope_fkey FOREIGN KEY (play_id, user_id, game_id, version_group_id) REFERENCES gameplay.mainline_plays (id, user_id, game_id, version_group_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT play_plan_links_plan_scope_fkey FOREIGN KEY (team_plan_id, user_id, game_id, version_group_id) REFERENCES planning.mainline_team_plans (id, user_id, game_id, version_group_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT play_plan_links_play_unique UNIQUE (play_id),
    CONSTRAINT play_plan_links_id_play_plan_unique UNIQUE (id, play_id, team_plan_id)
);

CREATE INDEX play_plan_links_team_plan_idx ON planning.mainline_play_plan_links (team_plan_id);

CREATE INDEX play_plan_links_game_version_group_idx ON planning.mainline_play_plan_links (game_id, version_group_id);

CREATE INDEX play_plan_links_user_idx ON planning.mainline_play_plan_links (user_id);

CREATE INDEX play_plan_links_play_scope_idx ON planning.mainline_play_plan_links (play_id, user_id, game_id, version_group_id);

CREATE INDEX play_plan_links_plan_scope_idx ON planning.mainline_play_plan_links (team_plan_id, user_id, game_id, version_group_id);

COMMENT ON TABLE planning.mainline_play_plan_links IS 'Links each play to zero or one reusable team plan while enforcing that the play and plan share owner, game, and version group.';

COMMENT ON COLUMN planning.mainline_play_plan_links.game_id IS 'Duplicated from both play and plan to enforce same-game play-plan integrity.';

COMMENT ON COLUMN planning.mainline_play_plan_links.version_group_id IS 'Duplicated from both play and plan to enforce same-version-group play-plan integrity.';

COMMENT ON COLUMN planning.mainline_play_plan_links.created_from_plan IS 'True when the play was originally created from the linked plan.';

-- ============================================================================
-- Source: database/schema/05_planning/02_functions/001_mainline_team_plan_play_mutations.sql
-- ============================================================================
-- ============================================================================
-- Functions: planning mainline team plan to play mutations
-- Client-callable helpers for linking and Play-scoped Plan cloning.
-- ============================================================================
CREATE FUNCTION planning.link_mainline_team_plan_to_play (p_play_id uuid, p_team_plan_id uuid, p_created_from_plan boolean DEFAULT FALSE, p_replace_existing boolean DEFAULT FALSE)
    RETURNS TABLE (
        result_play_plan_link_id uuid)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play gameplay.mainline_plays%ROWTYPE;
    v_team_plan planning.mainline_team_plans%ROWTYPE;
    v_existing_play_plan_link planning.mainline_play_plan_links%ROWTYPE;
    v_play_plan_link_id uuid;
BEGIN
    IF p_play_id IS NULL THEN
        RAISE EXCEPTION 'play_id is required'
            USING ERRCODE = '23502';
    END IF;
    IF p_team_plan_id IS NULL THEN
        RAISE EXCEPTION 'team_plan_id is required'
            USING ERRCODE = '23502';
    END IF;
    SELECT
        mainline_plays.*
    INTO
        v_play
    FROM
        gameplay.mainline_plays
    WHERE
        mainline_plays.id = p_play_id
    FOR UPDATE;
    IF v_play.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable play_id %', p_play_id
            USING ERRCODE = '23503';
    END IF;
    SELECT
        mainline_team_plans.*
    INTO
        v_team_plan
    FROM
        planning.mainline_team_plans
    WHERE
        mainline_team_plans.id = p_team_plan_id
    FOR UPDATE;
    IF v_team_plan.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable team_plan_id %', p_team_plan_id
            USING ERRCODE = '23503';
    END IF;
    IF v_play.user_id <> v_team_plan.user_id OR v_play.game_id <> v_team_plan.game_id OR v_play.version_group_id <> v_team_plan.version_group_id THEN
        RAISE EXCEPTION 'Play and team plan must have the same owner, game, and version group'
            USING ERRCODE = '23514';
    END IF;
    SELECT
        mainline_play_plan_links.*
    INTO
        v_existing_play_plan_link
    FROM
        planning.mainline_play_plan_links
    WHERE
        mainline_play_plan_links.play_id = v_play.id
    FOR UPDATE;
    IF v_existing_play_plan_link.id IS NOT NULL AND v_existing_play_plan_link.team_plan_id <> v_team_plan.id AND NOT COALESCE(p_replace_existing, FALSE) THEN
        RAISE EXCEPTION 'Play already has a linked team plan. Unlink or replace it explicitly before linking another team plan.'
            USING ERRCODE = '23505';
    END IF;
    IF v_existing_play_plan_link.id IS NULL THEN
        INSERT INTO planning.mainline_play_plan_links (play_id, team_plan_id, user_id, game_id, version_group_id, created_from_plan)
            VALUES (v_play.id, v_team_plan.id, v_play.user_id, v_play.game_id, v_play.version_group_id, p_created_from_plan)
        RETURNING
            id
        INTO
            v_play_plan_link_id;
    ELSIF v_existing_play_plan_link.team_plan_id <> v_team_plan.id THEN
        -- Following another Plan: the link moves to it.
        UPDATE
            planning.mainline_play_plan_links
        SET
            team_plan_id = v_team_plan.id,
            created_from_plan = p_created_from_plan
        WHERE
            mainline_play_plan_links.id = v_existing_play_plan_link.id
        RETURNING
            id
        INTO
            v_play_plan_link_id;
    ELSE
        UPDATE
            planning.mainline_play_plan_links
        SET
            created_from_plan = planning.mainline_play_plan_links.created_from_plan
            OR p_created_from_plan
        WHERE
            mainline_play_plan_links.id = v_existing_play_plan_link.id
        RETURNING
            id
        INTO
            v_play_plan_link_id;
    END IF;
    RETURN QUERY
    SELECT
        v_play_plan_link_id;
END;
$$;

CREATE FUNCTION planning.clone_mainline_team_plan_for_play (p_play_id uuid, p_name text DEFAULT NULL)
    RETURNS TABLE (
        result_source_team_plan_id uuid,
        result_team_plan_id uuid,
        result_play_plan_link_id uuid)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_play_plan_link planning.mainline_play_plan_links%ROWTYPE;
    v_source_plan planning.mainline_team_plans%ROWTYPE;
    v_source_member planning.mainline_team_plan_members%ROWTYPE;
    v_new_plan_id uuid;
    v_new_member_id uuid;
    v_name text;
BEGIN
    IF p_play_id IS NULL THEN
        RAISE EXCEPTION 'play_id is required'
            USING ERRCODE = '23502';
    END IF;
    SELECT
        mainline_play_plan_links.*
    INTO
        v_play_plan_link
    FROM
        planning.mainline_play_plan_links
    WHERE
        mainline_play_plan_links.play_id = p_play_id
    FOR UPDATE;
    IF v_play_plan_link.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable linked Plan for play_id %', p_play_id
            USING ERRCODE = '23503';
    END IF;
    SELECT
        mainline_team_plans.*
    INTO
        v_source_plan
    FROM
        planning.mainline_team_plans
    WHERE
        mainline_team_plans.id = v_play_plan_link.team_plan_id
    FOR UPDATE;
    IF v_source_plan.id IS NULL THEN
        RAISE EXCEPTION 'Unknown or unavailable source team Plan'
            USING ERRCODE = '23503';
    END IF;
    v_name := COALESCE(NULLIF (BTRIM(p_name), ''), v_source_plan.name);
    INSERT INTO planning.mainline_team_plans (user_id, game_id, version_group_id, status_id, name, notes)
        VALUES (v_source_plan.user_id, v_source_plan.game_id, v_source_plan.version_group_id, v_source_plan.status_id, v_name, v_source_plan.notes)
    RETURNING
        id
    INTO
        v_new_plan_id;
    INSERT INTO planning.mainline_team_plan_optional_content_scopes (team_plan_id, game_id, version_group_id)
    SELECT
        v_new_plan_id,
        mainline_team_plan_optional_content_scopes.game_id,
        mainline_team_plan_optional_content_scopes.version_group_id
    FROM
        planning.mainline_team_plan_optional_content_scopes
    WHERE
        mainline_team_plan_optional_content_scopes.team_plan_id = v_source_plan.id;
    FOR v_source_member IN
    SELECT
        mainline_team_plan_members.*
    FROM
        planning.mainline_team_plan_members
    WHERE
        mainline_team_plan_members.team_plan_id = v_source_plan.id
    ORDER BY
        mainline_team_plan_members.slot LOOP
            INSERT INTO planning.mainline_team_plan_members (team_plan_id, slot, target_species_id, target_form_id, notes, gender, nature_id, ability_id, held_item_id)
                VALUES (v_new_plan_id, v_source_member.slot, v_source_member.target_species_id, v_source_member.target_form_id, v_source_member.notes, v_source_member.gender, v_source_member.nature_id, v_source_member.ability_id, v_source_member.held_item_id)
            RETURNING
                id
            INTO
                v_new_member_id;
            INSERT INTO planning.mainline_team_plan_member_moves (team_plan_member_id, slot, move_id)
            SELECT
                v_new_member_id,
                mainline_team_plan_member_moves.slot,
                mainline_team_plan_member_moves.move_id
            FROM
                planning.mainline_team_plan_member_moves
            WHERE
                mainline_team_plan_member_moves.team_plan_member_id = v_source_member.id;
        END LOOP;
    UPDATE
        planning.mainline_play_plan_links
    SET
        team_plan_id = v_new_plan_id,
        created_from_plan = FALSE
    WHERE
        mainline_play_plan_links.id = v_play_plan_link.id;
    RETURN QUERY
    SELECT
        v_source_plan.id,
        v_new_plan_id,
        v_play_plan_link.id;
END;
$$;

REVOKE ALL ON FUNCTION planning.link_mainline_team_plan_to_play (UUID, UUID, BOOLEAN, BOOLEAN) FROM PUBLIC;

REVOKE ALL ON FUNCTION planning.link_mainline_team_plan_to_play (UUID, UUID, BOOLEAN, BOOLEAN) FROM anon;

GRANT EXECUTE ON FUNCTION planning.link_mainline_team_plan_to_play (UUID, UUID, BOOLEAN, BOOLEAN) TO authenticated, service_role;

REVOKE ALL ON FUNCTION planning.clone_mainline_team_plan_for_play (UUID, TEXT) FROM PUBLIC;

REVOKE ALL ON FUNCTION planning.clone_mainline_team_plan_for_play (UUID, TEXT) FROM anon;

GRANT EXECUTE ON FUNCTION planning.clone_mainline_team_plan_for_play (UUID, TEXT) TO authenticated, service_role;

COMMENT ON FUNCTION planning.link_mainline_team_plan_to_play (UUID, UUID, BOOLEAN, BOOLEAN) IS 'Links a mainline play to its single reusable team Plan, moving an existing link when asked. Plan comparison is derived at read time instead of stored in per-member relationship rows.';

COMMENT ON FUNCTION planning.clone_mainline_team_plan_for_play (UUID, TEXT) IS 'Clones the complete reusable Plan linked to one Play and atomically relinks only that Play to the clone. Runs as SECURITY INVOKER so planning RLS applies.';

-- ============================================================================
-- Source: database/schema/05_planning/02_functions/002_mainline_team_plan_save_mutations.sql
-- ============================================================================
-- ============================================================================
-- Functions: planning mainline team plan save mutations
-- Client-callable helper that writes a whole Plan in one transaction.
-- ============================================================================
CREATE FUNCTION planning.save_mainline_team_plan (p_version_group_id integer, p_name text, p_members jsonb DEFAULT '[]'::jsonb, p_expansion_version_group_ids integer[] DEFAULT '{}'::integer[], p_team_plan_id uuid DEFAULT NULL, p_game_id integer DEFAULT NULL)
    RETURNS TABLE (
        result_team_plan_id uuid,
        result_created boolean)
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = ''
    AS $$
DECLARE
    v_user_id uuid := auth.uid ();
    v_version_group reference.version_groups%ROWTYPE;
    v_existing_plan planning.mainline_team_plans%ROWTYPE;
    v_game_id integer;
    v_status_id integer;
    v_plan_id uuid;
    v_created boolean;
    v_expansion_ids integer[];
    v_invalid_expansion_ids integer[];
    v_member record;
    v_member_id uuid;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'An authenticated user is required to save a Plan'
            USING ERRCODE = '42501';
    END IF;
    IF p_version_group_id IS NULL THEN
        RAISE EXCEPTION 'version_group_id is required'
            USING ERRCODE = '23502';
    END IF;
    p_name := NULLIF (BTRIM(p_name), '');
    IF p_name IS NULL THEN
        RAISE EXCEPTION 'name is required'
            USING ERRCODE = '23502';
    END IF;
    p_members := COALESCE(p_members, '[]'::jsonb);
    IF jsonb_typeof(p_members) <> 'array' THEN
        RAISE EXCEPTION 'members must be a JSON array'
            USING ERRCODE = '22023';
    END IF;
    IF EXISTS (
        SELECT
            1
        FROM
            jsonb_array_elements(p_members) AS members (member)
        WHERE
            jsonb_typeof(members.member) <> 'object'
            OR jsonb_typeof(COALESCE(members.member -> 'move_ids', '[]'::jsonb))
            NOT IN ('array', 'null')) THEN
    RAISE EXCEPTION 'Each member must be a JSON object whose move_ids is an array'
        USING ERRCODE = '22023';
END IF;
    IF jsonb_array_length(p_members) > 6 THEN
        RAISE EXCEPTION 'A Plan can have at most six members'
            USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
        SELECT
            1
        FROM
            jsonb_array_elements(p_members) AS members (member)
        WHERE
            jsonb_typeof(members.member -> 'move_ids') = 'array'
            AND jsonb_array_length(members.member -> 'move_ids') > 4) THEN
    RAISE EXCEPTION 'A planned Pokémon can have at most four moves'
    USING ERRCODE = '23514';
END IF;
    IF EXISTS (
        SELECT
            1
        FROM
            jsonb_to_recordset(p_members) AS members (slot integer)
        GROUP BY
            members.slot
        HAVING
            members.slot IS NULL
            OR COUNT(*) > 1) THEN
    RAISE EXCEPTION 'Every Plan member needs its own slot' USING ERRCODE = '23514';
END IF;
    SELECT
        version_groups.*
    INTO
        v_version_group
    FROM
        reference.version_groups
    WHERE
        version_groups.id = p_version_group_id;
    IF v_version_group.id IS NULL THEN
        RAISE EXCEPTION 'Unknown version_group_id %', p_version_group_id
            USING ERRCODE = '23503';
    END IF;
    IF v_version_group.parent_version_group_id IS NOT NULL THEN
        RAISE EXCEPTION 'Version group % is an expansion, not a game a Plan can be for', p_version_group_id
            USING ERRCODE = '23514';
    END IF;
    IF p_team_plan_id IS NOT NULL THEN
        SELECT
            mainline_team_plans.*
        INTO
            v_existing_plan
        FROM
            planning.mainline_team_plans
        WHERE
            mainline_team_plans.id = p_team_plan_id
        FOR UPDATE;
        IF v_existing_plan.id IS NULL THEN
            RAISE EXCEPTION 'Unknown or unavailable team_plan_id %', p_team_plan_id
                USING ERRCODE = '23503';
        END IF;
    END IF;
    -- The Plan's game: the one asked for, else the one it keeps while its
    -- version group is unchanged, else the version group's first game.
    IF p_game_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT
                1
            FROM
                reference.games
            WHERE
                games.id = p_game_id
                AND games.version_group_id = p_version_group_id) THEN
        RAISE EXCEPTION 'Game % is not part of version group %', p_game_id, p_version_group_id
            USING ERRCODE = '23514';
    END IF;
    v_game_id := p_game_id;
ELSIF v_existing_plan.id IS NOT NULL
    AND v_existing_plan.version_group_id = p_version_group_id THEN
    v_game_id := v_existing_plan.game_id;
ELSE
    SELECT
        games.id
    INTO
        v_game_id
    FROM
        reference.games
    WHERE
        games.version_group_id = p_version_group_id
    ORDER BY
        games.sort_order,
        games.id
    LIMIT 1;
    IF v_game_id IS NULL THEN
        RAISE EXCEPTION 'Version group % has no games', p_version_group_id
            USING ERRCODE = '23503';
    END IF;
END IF;
    SELECT
        COALESCE(ARRAY_AGG(DISTINCT requested_id ORDER BY requested_id), '{}'::integer[])
    INTO
        v_expansion_ids
    FROM
        UNNEST(COALESCE(p_expansion_version_group_ids, '{}'::integer[])) AS requested (requested_id)
WHERE
    requested_id IS NOT NULL;
    SELECT
        COALESCE(ARRAY_AGG(requested_id ORDER BY requested_id), '{}'::integer[])
    INTO
        v_invalid_expansion_ids
    FROM
        UNNEST(v_expansion_ids) AS requested (requested_id)
WHERE
    NOT EXISTS (
        SELECT
            1
        FROM
            reference.game_content_scopes
            JOIN reference.version_groups ON version_groups.id = game_content_scopes.version_group_id
        WHERE
            game_content_scopes.game_id = v_game_id
            AND game_content_scopes.version_group_id = requested_id
            AND NOT game_content_scopes.is_base_scope
            AND version_groups.parent_version_group_id = p_version_group_id);
    IF ARRAY_LENGTH(v_invalid_expansion_ids, 1) IS NOT NULL THEN
        RAISE EXCEPTION 'Version groups % are not expansions of version group %', v_invalid_expansion_ids, p_version_group_id
            USING ERRCODE = '23514';
    END IF;
    IF v_existing_plan.id IS NULL THEN
        SELECT
            mainline_team_plan_statuses.id
        INTO
            v_status_id
        FROM
            planning.mainline_team_plan_statuses
        WHERE
            mainline_team_plan_statuses.slug = 'active';
        IF v_status_id IS NULL THEN
            RAISE EXCEPTION 'Plan status active is not set up'
                USING ERRCODE = '23503';
        END IF;
        INSERT INTO planning.mainline_team_plans (user_id, game_id, version_group_id, status_id, name)
            VALUES (v_user_id, v_game_id, p_version_group_id, v_status_id, p_name)
        RETURNING
            id
        INTO
            v_plan_id;
        v_created := TRUE;
    ELSE
        v_plan_id := v_existing_plan.id;
        v_created := FALSE;
        IF (v_existing_plan.version_group_id <> p_version_group_id OR v_existing_plan.game_id <> v_game_id) AND EXISTS (
        SELECT
            1
        FROM
            planning.mainline_play_plan_links
        WHERE
            mainline_play_plan_links.team_plan_id = v_plan_id) THEN
            RAISE EXCEPTION 'A Play follows team plan %, so its game cannot change', v_plan_id
                USING ERRCODE = '55000';
        END IF;
        -- Expansions are rewritten below; clearing them first lets the game change.
        DELETE FROM planning.mainline_team_plan_optional_content_scopes
        WHERE mainline_team_plan_optional_content_scopes.team_plan_id = v_plan_id;
        UPDATE
            planning.mainline_team_plans
        SET
            game_id = v_game_id,
            version_group_id = p_version_group_id,
            name = p_name
        WHERE
            mainline_team_plans.id = v_plan_id;
        -- Planned moves cascade with their members.
        DELETE FROM planning.mainline_team_plan_members
        WHERE mainline_team_plan_members.team_plan_id = v_plan_id;
    END IF;
    FOR v_member IN
    SELECT
        members.*
    FROM
        jsonb_to_recordset(p_members) AS members (slot integer,
        target_species_id integer,
        target_form_id integer,
        notes text,
        gender text,
        nature_id integer,
        ability_id integer,
        held_item_id integer,
        move_ids jsonb)
ORDER BY
    members.slot LOOP
        INSERT INTO planning.mainline_team_plan_members (team_plan_id, slot, target_species_id, target_form_id, notes, gender, nature_id, ability_id, held_item_id)
            VALUES (v_plan_id, v_member.slot, v_member.target_species_id, v_member.target_form_id, NULLIF (BTRIM(v_member.notes), ''), v_member.gender, v_member.nature_id, v_member.ability_id, v_member.held_item_id)
        RETURNING
            id
        INTO
            v_member_id;
        -- move_ids holds the four move slots in order; null leaves a slot empty.
        INSERT INTO planning.mainline_team_plan_member_moves (team_plan_member_id, slot, move_id)
        SELECT
            v_member_id,
            moves.move_slot::integer,
            (moves.move_id #>> '{}')::integer
        FROM
            jsonb_array_elements(COALESCE(NULLIF (v_member.move_ids, 'null'::jsonb), '[]'::jsonb))
            WITH ORDINALITY AS moves (move_id, move_slot)
        WHERE
            jsonb_typeof(moves.move_id) <> 'null';
    END LOOP;
INSERT INTO planning.mainline_team_plan_optional_content_scopes (team_plan_id, game_id, version_group_id)
SELECT
    v_plan_id,
    v_game_id,
    expansion_ids.version_group_id
FROM
    UNNEST(v_expansion_ids) AS expansion_ids (version_group_id);
    RETURN QUERY
    SELECT
        v_plan_id,
        v_created;
END;
$$;

REVOKE ALL ON FUNCTION planning.save_mainline_team_plan (INTEGER, TEXT, JSONB, INTEGER[], UUID, INTEGER) FROM PUBLIC;

REVOKE ALL ON FUNCTION planning.save_mainline_team_plan (INTEGER, TEXT, JSONB, INTEGER[], UUID, INTEGER) FROM anon;

GRANT EXECUTE ON FUNCTION planning.save_mainline_team_plan (INTEGER, TEXT, JSONB, INTEGER[], UUID, INTEGER) TO authenticated, service_role;

COMMENT ON FUNCTION planning.save_mainline_team_plan (INTEGER, TEXT, JSONB, INTEGER[], UUID, INTEGER) IS 'Atomically creates (no team_plan_id) or rewrites a Plan: its row, ordered members, planned move slots, and expansions. Refuses a game change while a Play follows the Plan. Build validation against reference data stays with the caller; ownership comes from planning RLS. Runs as SECURITY INVOKER.';

