GRANT ALL ON TABLE planning.mainline_play_plan_links TO service_role;

CREATE POLICY team_plan_statuses_read_all ON planning.mainline_team_plan_statuses
    FOR SELECT TO authenticated
    USING (TRUE);

CREATE POLICY team_plans_select_own ON planning.mainline_team_plans
    FOR SELECT TO authenticated
    USING (user_id = auth.uid ());

CREATE POLICY team_plans_insert_own ON planning.mainline_team_plans
    FOR INSERT TO authenticated
    WITH CHECK (user_id = auth.uid ());

CREATE POLICY team_plans_update_own ON planning.mainline_team_plans
    FOR UPDATE TO authenticated
    USING (user_id = auth.uid ())
    WITH CHECK (user_id = auth.uid ());

CREATE POLICY team_plans_delete_own ON planning.mainline_team_plans
    FOR DELETE TO authenticated
    USING (user_id = auth.uid ());

CREATE POLICY play_plan_links_select_own ON planning.mainline_play_plan_links
    FOR SELECT TO authenticated
    USING (user_id = auth.uid ());

CREATE POLICY play_plan_links_insert_own ON planning.mainline_play_plan_links
    FOR INSERT TO authenticated
    WITH CHECK (user_id = auth.uid ());

CREATE POLICY play_plan_links_update_own ON planning.mainline_play_plan_links
    FOR UPDATE TO authenticated
    USING (user_id = auth.uid ())
    WITH CHECK (user_id = auth.uid ());

CREATE POLICY play_plan_links_delete_own ON planning.mainline_play_plan_links
    FOR DELETE TO authenticated
    USING (user_id = auth.uid ());

CREATE POLICY team_plan_optional_content_scopes_owned ON planning.mainline_team_plan_optional_content_scopes
    FOR ALL TO authenticated
    USING (EXISTS (
        SELECT
            1
        FROM
            planning.mainline_team_plans
        WHERE
            mainline_team_plans.id = team_plan_id
            AND mainline_team_plans.user_id = auth.uid ()))
    WITH CHECK (EXISTS (
        SELECT
            1
        FROM
            planning.mainline_team_plans
        WHERE
            mainline_team_plans.id = team_plan_id
            AND mainline_team_plans.user_id = auth.uid ()));

CREATE POLICY team_plan_members_owned ON planning.mainline_team_plan_members
    FOR ALL TO authenticated
    USING (EXISTS (
        SELECT
            1
        FROM
            planning.mainline_team_plans
        WHERE
            mainline_team_plans.id = team_plan_id
            AND mainline_team_plans.user_id = auth.uid ()))
    WITH CHECK (EXISTS (
        SELECT
            1
        FROM
            planning.mainline_team_plans
        WHERE
            mainline_team_plans.id = team_plan_id
            AND mainline_team_plans.user_id = auth.uid ()));

CREATE POLICY team_plan_member_moves_owned ON planning.mainline_team_plan_member_moves
    FOR ALL TO authenticated
    USING (EXISTS (
        SELECT
            1
        FROM
            planning.mainline_team_plan_members
            JOIN planning.mainline_team_plans ON mainline_team_plans.id = mainline_team_plan_members.team_plan_id
        WHERE
            mainline_team_plan_members.id = team_plan_member_id
            AND mainline_team_plans.user_id = auth.uid ()))
    WITH CHECK (EXISTS (
        SELECT
            1
        FROM
            planning.mainline_team_plan_members
            JOIN planning.mainline_team_plans ON mainline_team_plans.id = mainline_team_plan_members.team_plan_id
        WHERE
            mainline_team_plan_members.id = team_plan_member_id
            AND mainline_team_plans.user_id = auth.uid ()));

-- ============================================================================
-- Source: database/schema/06_views/01_views/001_mainline_play_summary.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_summary
-- Compact play rows for libraries, dashboards, and navigation.
-- ============================================================================
CREATE VIEW views.mainline_play_summary WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_plays.id AS play_id,
    mainline_plays.user_id,
    mainline_plays.name AS play_name,
    mainline_plays.trainer_name,
    mainline_plays.game_id,
    games.slug AS game_slug,
    games.name AS game_name,
    mainline_plays.version_group_id,
    version_groups.slug AS version_group_slug,
    version_groups.name AS version_group_name,
    games.generation_id,
    generations.slug AS generation_slug,
    generations.name AS generation_name,
    mainline_plays.status_id,
    mainline_play_statuses.slug AS status_slug,
    mainline_play_statuses.name AS status_name,
    mainline_plays.started_on,
    mainline_plays.completed_on,
    mainline_plays.playtime_minutes,
    mainline_plays.archived_at,
    mainline_plays.created_at,
    mainline_plays.updated_at,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_play_pokemon
        WHERE
            mainline_play_pokemon.play_id = mainline_plays.id
            AND mainline_play_pokemon.roster_state_id = 1
) AS active_team_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_play_pokemon
        WHERE
            mainline_play_pokemon.play_id = mainline_plays.id
            AND mainline_play_pokemon.roster_state_id = 2
) AS reserve_team_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_play_pokemon
        WHERE
            mainline_play_pokemon.play_id = mainline_plays.id
            AND mainline_play_pokemon.roster_state_id IN (
                3, 4
)
) AS historical_pokemon_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_play_milestone_progress
            JOIN tracking.mainline_milestones ON mainline_milestones.id = mainline_play_milestone_progress.milestone_id
        WHERE
            mainline_play_milestone_progress.play_id = mainline_plays.id
            AND (
                mainline_milestones.game_id IS NULL
                OR mainline_milestones.game_id = mainline_plays.game_id
)
            AND (
                mainline_milestones.version_group_id = mainline_plays.version_group_id
                OR EXISTS (
                    SELECT
                        1
                    FROM
                        gameplay.mainline_play_optional_content_scopes
                    WHERE
                        mainline_play_optional_content_scopes.play_id = mainline_plays.id
                        AND mainline_play_optional_content_scopes.version_group_id = mainline_milestones.version_group_id
)
)
) AS completed_milestone_count,
        (
            SELECT
                COUNT(
                    *
)
            FROM
                gameplay.mainline_play_collectible_entry_progress
                JOIN tracking.mainline_collectible_entries ON mainline_collectible_entries.id = mainline_play_collectible_entry_progress.collectible_entry_id
                JOIN tracking.mainline_collectibles ON mainline_collectibles.id = mainline_collectible_entries.collectible_id
            WHERE
                mainline_play_collectible_entry_progress.play_id = mainline_plays.id
                AND (
                    mainline_collectibles.game_id IS NULL
                    OR mainline_collectibles.game_id = mainline_plays.game_id
)
                AND (
                    mainline_collectibles.version_group_id = mainline_plays.version_group_id
                    OR EXISTS (
                        SELECT
                            1
                        FROM
                            gameplay.mainline_play_optional_content_scopes
                        WHERE
                            mainline_play_optional_content_scopes.play_id = mainline_plays.id
                            AND mainline_play_optional_content_scopes.version_group_id = mainline_collectibles.version_group_id
)
)
) AS collected_entry_count,
            (
                SELECT
                    COUNT(
                        *
)
                FROM
                    gameplay.mainline_play_pokedex_species_progress
                WHERE
                    mainline_play_pokedex_species_progress.play_id = mainline_plays.id
                    AND mainline_play_pokedex_species_progress.is_seen
                    AND COALESCE(
                        mainline_play_settings.include_pokedex_in_completion, TRUE
)
                    AND EXISTS (
                        SELECT
                            1
                        FROM
                            reference.pokedex_entries
                            JOIN reference.pokedex ON pokedex.id = pokedex_entries.pokedex_id
                        WHERE
                            pokedex_entries.species_id = mainline_play_pokedex_species_progress.species_id
                            AND pokedex.is_completion_relevant
                            AND (
                                pokedex.pokedex_kind NOT IN (
                                    'national', 'special'
)
                                OR COALESCE(
                                    mainline_play_settings.include_optional_pokedexes_in_completion, FALSE
)
)
                            AND (
                                pokedex_entries.is_source_required_for_completion
                                OR COALESCE(
                                    mainline_play_settings.include_optional_pokedex_entries_in_completion, TRUE
)
)
                            AND (
                                pokedex.version_group_id = mainline_plays.version_group_id
                                OR EXISTS (
                                    SELECT
                                        1
                                    FROM
                                        gameplay.mainline_play_optional_content_scopes
                                    WHERE
                                        mainline_play_optional_content_scopes.play_id = mainline_plays.id
                                        AND mainline_play_optional_content_scopes.version_group_id = pokedex.version_group_id
)
)
)
) AS pokedex_seen_count,
                    (
                        SELECT
                            COUNT(
                                *
)
                        FROM
                            gameplay.mainline_play_pokedex_species_progress
                        WHERE
                            mainline_play_pokedex_species_progress.play_id = mainline_plays.id
                            AND mainline_play_pokedex_species_progress.is_caught
                            AND COALESCE(
                                mainline_play_settings.include_pokedex_in_completion, TRUE
)
                            AND EXISTS (
                                SELECT
                                    1
                                FROM
                                    reference.pokedex_entries
                                    JOIN reference.pokedex ON pokedex.id = pokedex_entries.pokedex_id
                                WHERE
                                    pokedex_entries.species_id = mainline_play_pokedex_species_progress.species_id
                                    AND pokedex.is_completion_relevant
                                    AND (
                                        pokedex.pokedex_kind NOT IN (
                                            'national', 'special'
)
                                        OR COALESCE(
                                            mainline_play_settings.include_optional_pokedexes_in_completion, FALSE
)
)
                                    AND (
                                        pokedex_entries.is_source_required_for_completion
                                        OR COALESCE(
                                            mainline_play_settings.include_optional_pokedex_entries_in_completion, TRUE
)
)
                                    AND (
                                        pokedex.version_group_id = mainline_plays.version_group_id
                                        OR EXISTS (
                                            SELECT
                                                1
                                            FROM
                                                gameplay.mainline_play_optional_content_scopes
                                            WHERE
                                                mainline_play_optional_content_scopes.play_id = mainline_plays.id
                                                AND mainline_play_optional_content_scopes.version_group_id = pokedex.version_group_id
)
)
)
) AS pokedex_caught_count,
                            (
                                SELECT
                                    COUNT(
                                        *
)
                                FROM
                                    gameplay.mainline_play_events
                                WHERE
                                    mainline_play_events.play_id = mainline_plays.id
) AS timeline_event_count
                        FROM
                            gameplay.mainline_plays
                        LEFT JOIN gameplay.mainline_play_settings ON mainline_play_settings.play_id = mainline_plays.id
                        JOIN gameplay.mainline_play_statuses ON mainline_play_statuses.id = mainline_plays.status_id
                        JOIN reference.games ON games.id = mainline_plays.game_id
                        JOIN reference.version_groups ON version_groups.id = mainline_plays.version_group_id
                        JOIN reference.generations ON generations.id = games.generation_id;

COMMENT ON VIEW views.mainline_play_summary IS 'Compact play summary rows. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/002_mainline_play_completion_summary.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_completion_summary
-- Derived completion denominators and progress counts per play.
-- ============================================================================
CREATE VIEW views.mainline_play_completion_summary WITH ( security_invoker = TRUE
) AS
WITH play_settings AS (
    SELECT
        mainline_plays.id AS play_id,
        mainline_plays.user_id,
        mainline_plays.game_id,
        mainline_plays.version_group_id,
        COALESCE(mainline_play_settings.story_tracking_enabled, TRUE) AS story_tracking_enabled,
        COALESCE(mainline_play_settings.collectibles_tracking_enabled, TRUE) AS collectibles_tracking_enabled,
        COALESCE(mainline_play_settings.include_pokedex_in_completion, TRUE) AS include_pokedex_in_completion,
        COALESCE(mainline_play_settings.include_collectibles_in_completion, TRUE) AS include_collectibles_in_completion,
        COALESCE(mainline_play_settings.include_optional_pokedexes_in_completion, FALSE) AS include_optional_pokedexes_in_completion,
        COALESCE(mainline_play_settings.include_optional_pokedex_entries_in_completion, TRUE) AS include_optional_pokedex_entries_in_completion
    FROM
        gameplay.mainline_plays
        LEFT JOIN gameplay.mainline_play_settings ON mainline_play_settings.play_id = mainline_plays.id
),
play_scopes AS (
    SELECT
        play_settings.play_id,
        play_settings.game_id,
        play_settings.version_group_id
    FROM
        play_settings
UNION ALL
SELECT
    mainline_play_optional_content_scopes.play_id,
    mainline_play_optional_content_scopes.game_id,
    mainline_play_optional_content_scopes.version_group_id
FROM
    gameplay.mainline_play_optional_content_scopes
),
eligible_milestones AS (
    SELECT DISTINCT
        play_scopes.play_id,
        mainline_milestones.id AS milestone_id
    FROM
        play_scopes
        JOIN play_settings ON play_settings.play_id = play_scopes.play_id
        JOIN tracking.mainline_milestones ON mainline_milestones.version_group_id = play_scopes.version_group_id
            AND (mainline_milestones.game_id IS NULL
                OR mainline_milestones.game_id = play_scopes.game_id)
    WHERE
        play_settings.story_tracking_enabled
        AND mainline_milestones.is_required_for_completion
),
milestone_counts AS (
    SELECT
        eligible_milestones.play_id,
        COUNT(*) AS required_milestone_count,
        COUNT(mainline_play_milestone_progress.milestone_id) AS completed_required_milestone_count
    FROM
        eligible_milestones
        LEFT JOIN gameplay.mainline_play_milestone_progress ON mainline_play_milestone_progress.play_id = eligible_milestones.play_id
            AND mainline_play_milestone_progress.milestone_id = eligible_milestones.milestone_id
    GROUP BY
        eligible_milestones.play_id
),
eligible_collectible_entries AS (
    SELECT DISTINCT
        play_settings.play_id,
        mainline_collectible_entries.id AS collectible_entry_id
    FROM
        play_settings
        JOIN play_scopes ON play_scopes.play_id = play_settings.play_id
        JOIN tracking.mainline_collectibles ON mainline_collectibles.version_group_id = play_scopes.version_group_id
            AND (mainline_collectibles.game_id IS NULL
                OR mainline_collectibles.game_id = play_scopes.game_id)
        JOIN tracking.mainline_collectible_entries ON mainline_collectible_entries.collectible_id = mainline_collectibles.id
    WHERE
        play_settings.collectibles_tracking_enabled
        AND play_settings.include_collectibles_in_completion
        AND mainline_collectibles.is_required_for_completion
),
collectible_counts AS (
    SELECT
        eligible_collectible_entries.play_id,
        COUNT(*) AS required_collectible_entry_count,
        COUNT(mainline_play_collectible_entry_progress.collectible_entry_id) AS collected_required_collectible_entry_count
    FROM
        eligible_collectible_entries
        LEFT JOIN gameplay.mainline_play_collectible_entry_progress ON mainline_play_collectible_entry_progress.play_id = eligible_collectible_entries.play_id
            AND mainline_play_collectible_entry_progress.collectible_entry_id = eligible_collectible_entries.collectible_entry_id
    GROUP BY
        eligible_collectible_entries.play_id
),
eligible_pokedex_species AS (
    SELECT DISTINCT
        play_settings.play_id,
        pokedex_entries.species_id
    FROM
        play_settings
        JOIN play_scopes ON play_scopes.play_id = play_settings.play_id
        JOIN reference.pokedex ON pokedex.version_group_id = play_scopes.version_group_id
        JOIN reference.pokedex_entries ON pokedex_entries.pokedex_id = pokedex.id
    WHERE
        play_settings.include_pokedex_in_completion
        AND pokedex.is_completion_relevant
        AND (pokedex.pokedex_kind NOT IN ('national', 'special')
            OR play_settings.include_optional_pokedexes_in_completion)
        AND (pokedex_entries.is_source_required_for_completion
            OR play_settings.include_optional_pokedex_entries_in_completion)
),
pokedex_counts AS (
    SELECT
        eligible_pokedex_species.play_id,
        COUNT(*) AS required_pokedex_species_count,
        COUNT(mainline_play_pokedex_species_progress.species_id) FILTER (WHERE mainline_play_pokedex_species_progress.is_seen) AS seen_required_pokedex_species_count,
        COUNT(mainline_play_pokedex_species_progress.species_id) FILTER (WHERE mainline_play_pokedex_species_progress.is_caught) AS caught_required_pokedex_species_count
    FROM
        eligible_pokedex_species
        LEFT JOIN gameplay.mainline_play_pokedex_species_progress ON mainline_play_pokedex_species_progress.play_id = eligible_pokedex_species.play_id
            AND mainline_play_pokedex_species_progress.species_id = eligible_pokedex_species.species_id
    GROUP BY
        eligible_pokedex_species.play_id
),
completion_counts AS (
    SELECT
        play_settings.play_id,
        play_settings.user_id,
        COALESCE(milestone_counts.required_milestone_count, 0) AS required_milestone_count,
        COALESCE(milestone_counts.completed_required_milestone_count, 0) AS completed_required_milestone_count,
        COALESCE(collectible_counts.required_collectible_entry_count, 0) AS required_collectible_entry_count,
        COALESCE(collectible_counts.collected_required_collectible_entry_count, 0) AS collected_required_collectible_entry_count,
        COALESCE(pokedex_counts.required_pokedex_species_count, 0) AS required_pokedex_species_count,
        COALESCE(pokedex_counts.seen_required_pokedex_species_count, 0) AS seen_required_pokedex_species_count,
        COALESCE(pokedex_counts.caught_required_pokedex_species_count, 0) AS caught_required_pokedex_species_count
    FROM
        play_settings
        LEFT JOIN milestone_counts ON milestone_counts.play_id = play_settings.play_id
        LEFT JOIN collectible_counts ON collectible_counts.play_id = play_settings.play_id
        LEFT JOIN pokedex_counts ON pokedex_counts.play_id = play_settings.play_id
),
completion_totals AS (
    SELECT
        completion_counts.*,
        (completion_counts.required_milestone_count + completion_counts.required_collectible_entry_count + completion_counts.required_pokedex_species_count) AS total_completion_unit_count,
        (completion_counts.completed_required_milestone_count + completion_counts.collected_required_collectible_entry_count + completion_counts.caught_required_pokedex_species_count) AS completed_completion_unit_count
    FROM
        completion_counts
)
SELECT
    completion_totals.play_id,
    completion_totals.user_id,
    completion_totals.required_milestone_count,
    completion_totals.completed_required_milestone_count,
    CASE WHEN completion_totals.required_milestone_count = 0 THEN
        0
    ELSE
        ROUND((completion_totals.completed_required_milestone_count::numeric * 100) / completion_totals.required_milestone_count, 2)
    END AS milestone_completion_percent,
    completion_totals.required_collectible_entry_count,
    completion_totals.collected_required_collectible_entry_count,
    CASE WHEN completion_totals.required_collectible_entry_count = 0 THEN
        0
    ELSE
        ROUND((completion_totals.collected_required_collectible_entry_count::numeric * 100) / completion_totals.required_collectible_entry_count, 2)
    END AS collectible_completion_percent,
    completion_totals.required_pokedex_species_count,
    completion_totals.seen_required_pokedex_species_count,
    completion_totals.caught_required_pokedex_species_count,
    CASE WHEN completion_totals.required_pokedex_species_count = 0 THEN
        0
    ELSE
        ROUND((completion_totals.caught_required_pokedex_species_count::numeric * 100) / completion_totals.required_pokedex_species_count, 2)
    END AS pokedex_completion_percent,
    completion_totals.total_completion_unit_count,
    completion_totals.completed_completion_unit_count,
    CASE WHEN completion_totals.total_completion_unit_count = 0 THEN
        0
    ELSE
        ROUND((completion_totals.completed_completion_unit_count::numeric * 100) / completion_totals.total_completion_unit_count, 2)
    END AS overall_completion_percent
FROM
    completion_totals;

COMMENT ON VIEW views.mainline_play_completion_summary IS 'Derived completion counts and percentages per play. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/003_mainline_play_overview.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_overview
-- Play hub overview with settings and optional content counts.
-- ============================================================================
CREATE VIEW views.mainline_play_overview WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_play_summary.*,
    COALESCE(
        mainline_play_settings.story_tracking_enabled, TRUE
) AS story_tracking_enabled,
    COALESCE(
        mainline_play_settings.pokedex_tracking_enabled, TRUE
) AS pokedex_tracking_enabled,
    COALESCE(
        mainline_play_settings.pokedex_mode, 'caught_and_seen'
) AS pokedex_mode,
    COALESCE(
        mainline_play_settings.collectibles_tracking_enabled, TRUE
) AS collectibles_tracking_enabled,
    COALESCE(
        mainline_play_settings.include_pokedex_in_completion, TRUE
) AS include_pokedex_in_completion,
    COALESCE(
        mainline_play_settings.include_collectibles_in_completion, TRUE
) AS include_collectibles_in_completion,
    COALESCE(
        mainline_play_settings.include_optional_pokedexes_in_completion, FALSE
) AS include_optional_pokedexes_in_completion,
    COALESCE(
        mainline_play_settings.include_optional_pokedex_entries_in_completion, TRUE
) AS include_optional_pokedex_entries_in_completion,
    COALESCE(
        mainline_play_completion_summary.required_milestone_count, 0
) AS required_milestone_count,
    COALESCE(
        mainline_play_completion_summary.completed_required_milestone_count, 0
) AS completed_required_milestone_count,
    COALESCE(
        mainline_play_completion_summary.milestone_completion_percent, 0
) AS milestone_completion_percent,
    COALESCE(
        mainline_play_completion_summary.required_collectible_entry_count, 0
) AS required_collectible_entry_count,
    COALESCE(
        mainline_play_completion_summary.collected_required_collectible_entry_count, 0
) AS collected_required_collectible_entry_count,
    COALESCE(
        mainline_play_completion_summary.collectible_completion_percent, 0
) AS collectible_completion_percent,
    COALESCE(
        mainline_play_completion_summary.required_pokedex_species_count, 0
) AS required_pokedex_species_count,
    COALESCE(
        mainline_play_completion_summary.seen_required_pokedex_species_count, 0
) AS seen_required_pokedex_species_count,
    COALESCE(
        mainline_play_completion_summary.caught_required_pokedex_species_count, 0
) AS caught_required_pokedex_species_count,
    COALESCE(
        mainline_play_completion_summary.pokedex_completion_percent, 0
) AS pokedex_completion_percent,
    COALESCE(
        mainline_play_completion_summary.total_completion_unit_count, 0
) AS total_completion_unit_count,
    COALESCE(
        mainline_play_completion_summary.completed_completion_unit_count, 0
) AS completed_completion_unit_count,
    COALESCE(
        mainline_play_completion_summary.overall_completion_percent, 0
) AS overall_completion_percent,
    COALESCE(
        optional_content.optional_content_scopes, '[]'::jsonb
) AS optional_content_scopes
FROM
    views.mainline_play_summary
    LEFT JOIN gameplay.mainline_play_settings ON mainline_play_settings.play_id = mainline_play_summary.play_id
    LEFT JOIN views.mainline_play_completion_summary ON mainline_play_completion_summary.play_id = mainline_play_summary.play_id
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(
                jsonb_build_object(
                    'version_group_id', version_groups.id, 'slug', version_groups.slug, 'name', version_groups.name
) ORDER BY game_content_scopes.sort_order
) AS optional_content_scopes
        FROM
            gameplay.mainline_play_optional_content_scopes
            JOIN reference.game_content_scopes ON game_content_scopes.game_id = mainline_play_optional_content_scopes.game_id
                AND game_content_scopes.version_group_id = mainline_play_optional_content_scopes.version_group_id
            JOIN reference.version_groups ON version_groups.id = mainline_play_optional_content_scopes.version_group_id
        WHERE
            mainline_play_optional_content_scopes.play_id = mainline_play_summary.play_id
) AS optional_content ON TRUE;

COMMENT ON VIEW views.mainline_play_overview IS 'Play hub overview with settings and optional content. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/004_mainline_play_milestone_detail.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_milestone_detail
-- Story milestones available to each play with progress, decisions, and refs.
-- ============================================================================
CREATE VIEW views.mainline_play_milestone_detail WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_plays.id AS play_id,
    mainline_plays.user_id,
    mainline_milestones.id AS milestone_id,
    mainline_milestones.version_group_id,
    version_groups.slug AS version_group_slug,
    version_groups.name AS version_group_name,
    mainline_milestones.game_id,
    games.slug AS milestone_game_slug,
    games.name AS milestone_game_name,
    mainline_milestones.category_id,
    mainline_categories.slug AS category_slug,
    mainline_categories.name AS category_name,
    mainline_categories.category_kind,
    mainline_categories.sort_order AS category_sort_order,
    mainline_milestones.milestone_type_id,
    mainline_milestone_types.slug AS milestone_type_slug,
    mainline_milestone_types.name AS milestone_type_name,
    mainline_milestones.snapshot_policy_id,
    mainline_snapshot_policies.slug AS snapshot_policy_slug,
    mainline_snapshot_policies.name AS snapshot_policy_name,
    mainline_milestones.parent_milestone_id,
    mainline_milestones.slug AS milestone_slug,
    mainline_milestones.name AS milestone_name,
    mainline_milestones.description,
    mainline_milestones.sort_order,
    mainline_milestones.is_required_for_completion,
    (
        COALESCE(
            mainline_play_settings.story_tracking_enabled, TRUE
)
        AND mainline_milestones.is_required_for_completion
) AS is_included_in_completion,
    (
        mainline_play_milestone_progress.play_id IS NOT NULL
) AS is_completed,
mainline_play_milestone_progress.completed_at,
mainline_play_milestone_progress.notes AS progress_notes,
completion_events.id AS completion_event_id,
completion_events.happened_at AS completion_event_happened_at,
completion_events.timeline_order AS completion_event_timeline_order,
COALESCE(completion_event_snapshots.team_snapshot_count, 0) AS completion_event_team_snapshot_count,
mainline_play_milestone_decisions.decision_option_id AS selected_decision_option_id,
selected_decision_options.slug AS selected_decision_option_slug,
selected_decision_options.label AS selected_decision_option_label,
COALESCE(prerequisites.prerequisites, '[]'::jsonb) AS prerequisites,
COALESCE(decision_options.decision_options, '[]'::jsonb) AS decision_options,
COALESCE(pokemon_refs.pokemon_refs, '[]'::jsonb) AS pokemon_refs,
COALESCE(opponent_refs.opponent_refs, '[]'::jsonb) AS opponent_refs,
COALESCE(badge_refs.badge_refs, '[]'::jsonb) AS badge_refs,
COALESCE(collectible_refs.collectible_refs, '[]'::jsonb) AS collectible_refs
FROM
    gameplay.mainline_plays
    LEFT JOIN gameplay.mainline_play_settings ON mainline_play_settings.play_id = mainline_plays.id
    JOIN tracking.mainline_milestones ON (mainline_milestones.version_group_id = mainline_plays.version_group_id
            OR EXISTS (
                SELECT
                    1
                FROM
                    gameplay.mainline_play_optional_content_scopes
            WHERE
                mainline_play_optional_content_scopes.play_id = mainline_plays.id
                AND mainline_play_optional_content_scopes.version_group_id = mainline_milestones.version_group_id))
    AND (mainline_milestones.game_id IS NULL
        OR mainline_milestones.game_id = mainline_plays.game_id)
    JOIN reference.version_groups ON version_groups.id = mainline_milestones.version_group_id
    LEFT JOIN reference.games ON games.id = mainline_milestones.game_id
    JOIN tracking.mainline_categories ON mainline_categories.id = mainline_milestones.category_id
        AND mainline_categories.version_group_id = mainline_milestones.version_group_id
    JOIN tracking.mainline_milestone_types ON mainline_milestone_types.id = mainline_milestones.milestone_type_id
    JOIN tracking.mainline_snapshot_policies ON mainline_snapshot_policies.id = mainline_milestones.snapshot_policy_id
    LEFT JOIN gameplay.mainline_play_milestone_progress ON mainline_play_milestone_progress.play_id = mainline_plays.id
        AND mainline_play_milestone_progress.milestone_id = mainline_milestones.id
    LEFT JOIN gameplay.mainline_play_events AS completion_events ON completion_events.play_id = mainline_plays.id
        AND completion_events.milestone_id = mainline_milestones.id
    LEFT JOIN gameplay.mainline_play_milestone_decisions ON mainline_play_milestone_decisions.play_id = mainline_plays.id
        AND mainline_play_milestone_decisions.milestone_id = mainline_milestones.id
    LEFT JOIN tracking.mainline_milestone_decision_options AS selected_decision_options ON selected_decision_options.id = mainline_play_milestone_decisions.decision_option_id
        AND selected_decision_options.milestone_id = mainline_milestones.id
    LEFT JOIN LATERAL (
        SELECT
            COUNT(*) AS team_snapshot_count
        FROM
            gameplay.mainline_play_event_team_snapshots
        WHERE
            mainline_play_event_team_snapshots.event_id = completion_events.id) AS completion_event_snapshots ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(jsonb_build_object('prerequisite_milestone_id', prerequisite_milestones.id, 'prerequisite_milestone_slug', prerequisite_milestones.slug, 'prerequisite_milestone_name', prerequisite_milestones.name, 'prerequisite_category_id', prerequisite_milestones.category_id, 'prerequisite_kind_id', mainline_milestone_prerequisite_kinds.id, 'prerequisite_kind_slug', mainline_milestone_prerequisite_kinds.slug, 'prerequisite_kind_name', mainline_milestone_prerequisite_kinds.name, 'notes', mainline_milestone_prerequisites.notes, 'sort_order', mainline_milestone_prerequisites.sort_order)
            ORDER BY mainline_milestone_prerequisites.sort_order) AS prerequisites
        FROM
            tracking.mainline_milestone_prerequisites
            JOIN tracking.mainline_milestones AS prerequisite_milestones ON prerequisite_milestones.id = mainline_milestone_prerequisites.prerequisite_milestone_id
                AND prerequisite_milestones.version_group_id = mainline_milestone_prerequisites.version_group_id
            JOIN tracking.mainline_milestone_prerequisite_kinds ON mainline_milestone_prerequisite_kinds.id = mainline_milestone_prerequisites.prerequisite_kind_id
        WHERE
            mainline_milestone_prerequisites.milestone_id = mainline_milestones.id
            AND (prerequisite_milestones.game_id IS NULL
                OR prerequisite_milestones.game_id = mainline_plays.game_id)) AS prerequisites ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(jsonb_build_object('decision_option_id', mainline_milestone_decision_options.id, 'slug', mainline_milestone_decision_options.slug, 'label', mainline_milestone_decision_options.label, 'description', mainline_milestone_decision_options.description, 'pokemon_species_id', mainline_milestone_decision_options.pokemon_species_id, 'pokemon_species_name', pokemon_species.name, 'pokemon_form_id', mainline_milestone_decision_options.pokemon_form_id, 'pokemon_form_name', pokemon_forms.name, 'item_id', mainline_milestone_decision_options.item_id, 'item_name', items.name, 'sort_order', mainline_milestone_decision_options.sort_order)
            ORDER BY mainline_milestone_decision_options.sort_order) AS decision_options
        FROM
            tracking.mainline_milestone_decision_options
        LEFT JOIN reference.pokemon_species ON pokemon_species.id = mainline_milestone_decision_options.pokemon_species_id
        LEFT JOIN reference.pokemon_forms ON pokemon_forms.species_id = mainline_milestone_decision_options.pokemon_species_id
            AND pokemon_forms.id = mainline_milestone_decision_options.pokemon_form_id
    LEFT JOIN reference.items ON items.id = mainline_milestone_decision_options.item_id
WHERE
    mainline_milestone_decision_options.milestone_id = mainline_milestones.id) AS decision_options ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(jsonb_build_object('relation_kind', mainline_milestone_pokemon_refs.relation_kind, 'species_id', mainline_milestone_pokemon_refs.species_id, 'species_name', pokemon_species.name, 'form_id', mainline_milestone_pokemon_refs.form_id, 'form_name', pokemon_forms.name, 'notes', mainline_milestone_pokemon_refs.notes, 'sort_order', mainline_milestone_pokemon_refs.sort_order)
            ORDER BY mainline_milestone_pokemon_refs.sort_order) AS pokemon_refs
        FROM
            tracking.mainline_milestone_pokemon_refs
            JOIN reference.pokemon_species ON pokemon_species.id = mainline_milestone_pokemon_refs.species_id
            LEFT JOIN reference.pokemon_forms ON pokemon_forms.species_id = mainline_milestone_pokemon_refs.species_id
                AND pokemon_forms.id = mainline_milestone_pokemon_refs.form_id
        WHERE
            mainline_milestone_pokemon_refs.milestone_id = mainline_milestones.id) AS pokemon_refs ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(jsonb_build_object('relation_kind', mainline_milestone_opponent_refs.relation_kind, 'opponent_id', mainline_opponents.id, 'slug', mainline_opponents.slug, 'name', mainline_opponents.name, 'opponent_role', mainline_opponents.opponent_role, 'primary_type_id', mainline_opponents.primary_type_id, 'secondary_type_id', mainline_opponents.secondary_type_id, 'sprite_slug', mainline_opponents.sprite_slug, 'notes', mainline_milestone_opponent_refs.notes, 'player_side', mainline_milestone_opponent_refs.player_side, 'sort_order', mainline_milestone_opponent_refs.sort_order)
            ORDER BY mainline_milestone_opponent_refs.sort_order) AS opponent_refs
        FROM
            tracking.mainline_milestone_opponent_refs
            JOIN tracking.mainline_opponents ON mainline_opponents.id = mainline_milestone_opponent_refs.opponent_id
                AND mainline_opponents.version_group_id = mainline_milestone_opponent_refs.version_group_id
        WHERE
            mainline_milestone_opponent_refs.milestone_id = mainline_milestones.id) AS opponent_refs ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(jsonb_build_object('relation_kind', mainline_milestone_badge_refs.relation_kind, 'badge_id', mainline_badges.id, 'slug', mainline_badges.slug, 'name', mainline_badges.name, 'type_id', mainline_badges.type_id, 'sprite_slug', mainline_badges.sprite_slug, 'notes', mainline_milestone_badge_refs.notes, 'sort_order', mainline_milestone_badge_refs.sort_order)
            ORDER BY mainline_milestone_badge_refs.sort_order) AS badge_refs
        FROM
            tracking.mainline_milestone_badge_refs
            JOIN tracking.mainline_badges ON mainline_badges.id = mainline_milestone_badge_refs.badge_id
                AND mainline_badges.version_group_id = mainline_milestone_badge_refs.version_group_id
        WHERE
            mainline_milestone_badge_refs.milestone_id = mainline_milestones.id) AS badge_refs ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(jsonb_build_object('relation_kind', mainline_milestone_collectible_refs.relation_kind, 'collectible_id', mainline_collectibles.id, 'collectible_slug', mainline_collectibles.slug, 'collectible_name', mainline_collectibles.name, 'collectible_entry_id', mainline_collectible_entries.id, 'collectible_entry_slug', mainline_collectible_entries.slug, 'collectible_entry_name', mainline_collectible_entries.name, 'notes', mainline_milestone_collectible_refs.notes, 'sort_order', mainline_milestone_collectible_refs.sort_order)
            ORDER BY mainline_milestone_collectible_refs.sort_order) AS collectible_refs
        FROM
            tracking.mainline_milestone_collectible_refs
            JOIN tracking.mainline_collectibles ON mainline_collectibles.id = mainline_milestone_collectible_refs.collectible_id
                AND mainline_collectibles.version_group_id = mainline_milestone_collectible_refs.version_group_id
        LEFT JOIN tracking.mainline_collectible_entries ON mainline_collectible_entries.id = mainline_milestone_collectible_refs.collectible_entry_id
            AND mainline_collectible_entries.collectible_id = mainline_milestone_collectible_refs.collectible_id
    WHERE
        mainline_milestone_collectible_refs.milestone_id = mainline_milestones.id) AS collectible_refs ON TRUE;

COMMENT ON VIEW views.mainline_play_milestone_detail IS 'Story milestones available to each play with progress, prerequisites, decisions, static refs, and linked completion event state. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/005_mainline_play_team_detail.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_team_detail
-- Current and historical Pokémon rows with display metadata and moves.
-- ============================================================================
CREATE VIEW views.mainline_play_team_detail WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_play_pokemon.id AS play_pokemon_id,
    mainline_play_pokemon.play_id,
    mainline_play_pokemon.roster_state_id,
    roster_states.slug AS roster_state_slug,
    roster_states.name AS roster_state_name,
    mainline_play_pokemon.slot,
    mainline_play_pokemon.species_id,
    pokemon_species.slug AS species_slug,
    pokemon_species.name AS species_name,
    pokemon_species.national_number,
    pokemon_species.evolution_family_id,
    mainline_play_pokemon.form_id,
    pokemon_forms.slug AS form_slug,
    pokemon_forms.name AS form_name,
    pokemon_forms.is_default AS is_default_form,
    mainline_play_pokemon.nickname,
    mainline_play_pokemon.level,
    mainline_play_pokemon.gender,
    mainline_play_pokemon.is_shiny,
    mainline_play_pokemon.nature_id,
    natures.name AS nature_name,
    mainline_play_pokemon.ability_id,
    abilities.name AS ability_name,
    mainline_play_pokemon.held_item_id,
    held_items.name AS held_item_name,
    mainline_play_pokemon.tera_type_id,
    tera_types.slug AS tera_type_slug,
    tera_types.name AS tera_type_name,
    mainline_play_pokemon.has_gigantamax_factor,
    mainline_play_pokemon.ball_item_id,
    ball_items.name AS ball_item_name,
    mainline_play_pokemon.met_location_label,
    mainline_play_pokemon.met_level,
    mainline_play_pokemon.is_mvp,
    mainline_play_pokemon.final_status,
    mainline_play_pokemon.personal_notes,
    mainline_play_pokemon.created_at,
    mainline_play_pokemon.updated_at,
    COALESCE(
        moves.moves, '[]'::jsonb
) AS moves,
    pokemon_fixed_tera_types.tera_type_id AS fixed_tera_type_id,
    fixed_tera_types.slug AS fixed_tera_type_slug,
    fixed_tera_types.name AS fixed_tera_type_name
FROM
    gameplay.mainline_play_pokemon
    JOIN gameplay.mainline_play_pokemon_roster_states AS roster_states ON roster_states.id = mainline_play_pokemon.roster_state_id
    JOIN reference.pokemon_species ON pokemon_species.id = mainline_play_pokemon.species_id
    JOIN reference.pokemon_forms ON pokemon_forms.species_id = mainline_play_pokemon.species_id
        AND pokemon_forms.id = mainline_play_pokemon.form_id
    LEFT JOIN reference.natures ON natures.id = mainline_play_pokemon.nature_id
    LEFT JOIN reference.abilities ON abilities.id = mainline_play_pokemon.ability_id
    LEFT JOIN reference.items AS held_items ON held_items.id = mainline_play_pokemon.held_item_id
    LEFT JOIN reference.tera_types ON tera_types.id = mainline_play_pokemon.tera_type_id
    LEFT JOIN reference.pokemon_fixed_tera_types ON pokemon_fixed_tera_types.form_id = mainline_play_pokemon.form_id
    LEFT JOIN reference.tera_types AS fixed_tera_types ON fixed_tera_types.id = pokemon_fixed_tera_types.tera_type_id
    LEFT JOIN reference.items AS ball_items ON ball_items.id = mainline_play_pokemon.ball_item_id
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(
                jsonb_build_object(
                    'slot', mainline_play_pokemon_moves.slot, 'move_id', moves.id, 'slug', moves.slug, 'name', moves.name
) ORDER BY mainline_play_pokemon_moves.slot
) AS moves
        FROM
            gameplay.mainline_play_pokemon_moves
            JOIN reference.moves ON moves.id = mainline_play_pokemon_moves.move_id
        WHERE
            mainline_play_pokemon_moves.play_pokemon_id = mainline_play_pokemon.id
) AS moves ON TRUE;

COMMENT ON VIEW views.mainline_play_team_detail IS 'Pokémon team detail rows with display identity, move slots and the form''s fixed Tera Type, if any. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/006_mainline_play_timeline_detail.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_timeline_detail
-- Timeline events with type/origin labels and linked Pokémon refs.
-- ============================================================================
CREATE VIEW views.mainline_play_timeline_detail WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_play_events.id AS event_id,
    mainline_play_events.play_id,
    mainline_play_events.event_type_id,
    event_types.slug AS event_type_slug,
    event_types.name AS event_type_name,
    mainline_play_events.event_origin_id,
    event_origins.slug AS event_origin_slug,
    event_origins.name AS event_origin_name,
    mainline_play_events.title,
    mainline_play_events.body,
    mainline_play_events.happened_at,
    mainline_play_events.timeline_order,
    mainline_play_events.milestone_id,
    mainline_milestones.slug AS milestone_slug,
    mainline_milestones.name AS milestone_name,
    mainline_milestones.description AS milestone_description,
    mainline_play_events.is_pinned,
    mainline_play_events.created_at,
    mainline_play_events.updated_at,
    COALESCE(
        pokemon_refs.pokemon_refs, '[]'::jsonb
) AS pokemon_refs,
    COALESCE(
        team_snapshots.team_snapshots, '[]'::jsonb
) AS team_snapshots
FROM
    gameplay.mainline_play_events
    JOIN gameplay.mainline_play_event_types AS event_types ON event_types.id = mainline_play_events.event_type_id
    JOIN gameplay.mainline_play_event_origins AS event_origins ON event_origins.id = mainline_play_events.event_origin_id
    LEFT JOIN tracking.mainline_milestones ON mainline_milestones.id = mainline_play_events.milestone_id
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(
                jsonb_build_object(
                    'role', mainline_play_event_pokemon_refs.role, 'sort_order', mainline_play_event_pokemon_refs.sort_order, 'play_pokemon_id', mainline_play_event_pokemon_refs.play_pokemon_id, 'species_id', mainline_play_event_pokemon_refs.species_id, 'species_name', pokemon_species.name, 'form_id', mainline_play_event_pokemon_refs.form_id, 'form_name', pokemon_forms.name, 'nickname', mainline_play_event_pokemon_refs.nickname, 'level', mainline_play_event_pokemon_refs.level
) ORDER BY mainline_play_event_pokemon_refs.sort_order
) AS pokemon_refs
        FROM
            gameplay.mainline_play_event_pokemon_refs
            JOIN reference.pokemon_species ON pokemon_species.id = mainline_play_event_pokemon_refs.species_id
            JOIN reference.pokemon_forms ON pokemon_forms.species_id = mainline_play_event_pokemon_refs.species_id
                AND pokemon_forms.id = mainline_play_event_pokemon_refs.form_id
        WHERE
            mainline_play_event_pokemon_refs.event_id = mainline_play_events.id
) AS pokemon_refs ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(
                jsonb_build_object(
                    'snapshot_id', mainline_play_event_team_snapshots.id, 'position', mainline_play_event_team_snapshots.position, 'play_pokemon_id', mainline_play_event_team_snapshots.play_pokemon_id, 'species_id', mainline_play_event_team_snapshots.species_id, 'species_name', pokemon_species.name, 'form_id', mainline_play_event_team_snapshots.form_id, 'form_name', pokemon_forms.name, 'nickname', mainline_play_event_team_snapshots.nickname, 'level', mainline_play_event_team_snapshots.level, 'gender', mainline_play_event_team_snapshots.gender, 'is_shiny', mainline_play_event_team_snapshots.is_shiny, 'nature_id', mainline_play_event_team_snapshots.nature_id, 'nature_name', natures.name, 'ability_id', mainline_play_event_team_snapshots.ability_id, 'ability_name', abilities.name, 'held_item_id', mainline_play_event_team_snapshots.held_item_id, 'held_item_name', held_items.name, 'notes', mainline_play_event_team_snapshots.notes, 'moves', COALESCE(
                        snapshot_moves.moves, '[]'::jsonb
)
) ORDER BY mainline_play_event_team_snapshots.position
) AS team_snapshots
        FROM
            gameplay.mainline_play_event_team_snapshots
            JOIN reference.pokemon_species ON pokemon_species.id = mainline_play_event_team_snapshots.species_id
            JOIN reference.pokemon_forms ON pokemon_forms.species_id = mainline_play_event_team_snapshots.species_id
                AND pokemon_forms.id = mainline_play_event_team_snapshots.form_id
        LEFT JOIN reference.natures ON natures.id = mainline_play_event_team_snapshots.nature_id
        LEFT JOIN reference.abilities ON abilities.id = mainline_play_event_team_snapshots.ability_id
        LEFT JOIN reference.items AS held_items ON held_items.id = mainline_play_event_team_snapshots.held_item_id
        LEFT JOIN LATERAL (
            SELECT
                jsonb_agg(
                    jsonb_build_object(
                        'slot', mainline_play_event_team_snapshot_moves.slot, 'move_id', moves.id, 'slug', moves.slug, 'name', moves.name
) ORDER BY mainline_play_event_team_snapshot_moves.slot
) AS moves
            FROM
                gameplay.mainline_play_event_team_snapshot_moves
                JOIN reference.moves ON moves.id = mainline_play_event_team_snapshot_moves.move_id
            WHERE
                mainline_play_event_team_snapshot_moves.snapshot_id = mainline_play_event_team_snapshots.id
) AS snapshot_moves ON TRUE
        WHERE
            mainline_play_event_team_snapshots.event_id = mainline_play_events.id
) AS team_snapshots ON TRUE;

COMMENT ON VIEW views.mainline_play_timeline_detail IS 'Timeline events with display labels and attached Pokémon history. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/007_mainline_play_pokedex_detail.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_pokedex_detail
-- Species-level Pokedex entries available to each play.
-- ============================================================================
CREATE VIEW views.mainline_play_pokedex_detail WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_plays.id AS play_id,
    mainline_plays.user_id,
    pokedex.id AS pokedex_id,
    pokedex.slug AS pokedex_slug,
    pokedex.name AS pokedex_name,
    pokedex.pokedex_kind,
    pokedex.is_completion_relevant,
    (
        pokedex.pokedex_kind IN (
            'national', 'special'
)
) AS is_optional_pokedex_scope,
    COALESCE(
        mainline_play_settings.pokedex_mode, 'caught_and_seen'
) AS pokedex_mode,
    pokedex_entries.pokedex_number,
    pokedex_entries.is_source_required_for_completion,
    (
        COALESCE(
            mainline_play_settings.include_pokedex_in_completion, TRUE
)
        AND pokedex.is_completion_relevant
        AND (
            pokedex.pokedex_kind NOT IN (
                'national', 'special'
)
            OR COALESCE(
                mainline_play_settings.include_optional_pokedexes_in_completion, FALSE
)
)
        AND (
            pokedex_entries.is_source_required_for_completion
            OR COALESCE(
                mainline_play_settings.include_optional_pokedex_entries_in_completion, TRUE
)
)
) AS is_included_in_completion,
    pokedex_entries.species_id,
    pokemon_species.slug AS species_slug,
    pokemon_species.name AS species_name,
    pokemon_species.national_number,
    pokemon_species.is_mythical,
    pokedex_entries.display_form_id,
    display_forms.slug AS display_form_slug,
    display_forms.name AS display_form_name,
    COALESCE(
        mainline_play_pokedex_species_progress.is_seen, FALSE
) AS is_seen,
    COALESCE(
        mainline_play_pokedex_species_progress.is_caught, FALSE
) AS is_caught,
    mainline_play_pokedex_species_progress.seen_at,
    mainline_play_pokedex_species_progress.caught_at
FROM
    gameplay.mainline_plays
    LEFT JOIN gameplay.mainline_play_settings ON mainline_play_settings.play_id = mainline_plays.id
    JOIN reference.pokedex ON pokedex.version_group_id = mainline_plays.version_group_id
        OR EXISTS (
            SELECT
                1
            FROM
                gameplay.mainline_play_optional_content_scopes
        WHERE
            mainline_play_optional_content_scopes.play_id = mainline_plays.id
            AND mainline_play_optional_content_scopes.version_group_id = pokedex.version_group_id)
    JOIN reference.pokedex_entries ON pokedex_entries.pokedex_id = pokedex.id
    JOIN reference.pokemon_species ON pokemon_species.id = pokedex_entries.species_id
    LEFT JOIN reference.pokemon_forms AS display_forms ON display_forms.species_id = pokedex_entries.species_id
        AND display_forms.id = pokedex_entries.display_form_id
    LEFT JOIN gameplay.mainline_play_pokedex_species_progress ON mainline_play_pokedex_species_progress.play_id = mainline_plays.id
        AND mainline_play_pokedex_species_progress.species_id = pokedex_entries.species_id;

COMMENT ON VIEW views.mainline_play_pokedex_detail IS 'Available Pokedex entries for each play with species-level progress. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/008_mainline_play_collectible_detail.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_collectible_detail
-- Collectible entries available to each play.
-- ============================================================================
CREATE VIEW views.mainline_play_collectible_detail WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_plays.id AS play_id,
    mainline_plays.user_id,
    mainline_collectibles.id AS collectible_id,
    mainline_collectibles.slug AS collectible_slug,
    mainline_collectibles.name AS collectible_name,
    mainline_collectibles.version_group_id,
    mainline_collectibles.game_id,
    mainline_collectible_types.id AS collectible_type_id,
    mainline_collectible_types.slug AS collectible_type_slug,
    mainline_collectible_types.name AS collectible_type_name,
    mainline_collectibles.is_required_for_completion,
    COALESCE(
        mainline_play_settings.collectibles_tracking_enabled, TRUE
) AS collectibles_tracking_enabled,
    (
        COALESCE(
            mainline_play_settings.collectibles_tracking_enabled, TRUE
)
        AND COALESCE(
            mainline_play_settings.include_collectibles_in_completion, TRUE
)
        AND mainline_collectibles.is_required_for_completion
) AS is_included_in_completion,
    mainline_collectible_entries.id AS collectible_entry_id,
    mainline_collectible_entries.slug AS collectible_entry_slug,
    mainline_collectible_entries.name AS collectible_entry_name,
    mainline_collectible_entries.location_label,
    mainline_collectible_entries.sub_location_label,
    mainline_collectible_entries.description,
    mainline_collectible_entries.sort_order AS collectible_entry_sort_order,
    (
        mainline_play_collectible_entry_progress.play_id IS NOT NULL
) AS is_collected,
mainline_play_collectible_entry_progress.collected_at
FROM
    gameplay.mainline_plays
    LEFT JOIN gameplay.mainline_play_settings ON mainline_play_settings.play_id = mainline_plays.id
    JOIN tracking.mainline_collectibles ON (mainline_collectibles.version_group_id = mainline_plays.version_group_id
            OR EXISTS (
                SELECT
                    1
                FROM
                    gameplay.mainline_play_optional_content_scopes
            WHERE
                mainline_play_optional_content_scopes.play_id = mainline_plays.id
                AND mainline_play_optional_content_scopes.version_group_id = mainline_collectibles.version_group_id))
    AND (mainline_collectibles.game_id IS NULL
        OR mainline_collectibles.game_id = mainline_plays.game_id)
    JOIN tracking.mainline_collectible_types ON mainline_collectible_types.id = mainline_collectibles.collectible_type_id
    JOIN tracking.mainline_collectible_entries ON mainline_collectible_entries.collectible_id = mainline_collectibles.id
    LEFT JOIN gameplay.mainline_play_collectible_entry_progress ON mainline_play_collectible_entry_progress.play_id = mainline_plays.id
        AND mainline_play_collectible_entry_progress.collectible_entry_id = mainline_collectible_entries.id;

COMMENT ON VIEW views.mainline_play_collectible_detail IS 'Available collectible entries for each play with collected state. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/009_mainline_team_plan_summary.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_team_plan_summary
-- Compact team plan rows for plan libraries and play setup.
-- ============================================================================
CREATE VIEW views.mainline_team_plan_summary WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_team_plans.id AS team_plan_id,
    mainline_team_plans.user_id,
    mainline_team_plans.name AS team_plan_name,
    mainline_team_plans.game_id,
    games.slug AS game_slug,
    games.name AS game_name,
    mainline_team_plans.version_group_id,
    version_groups.slug AS version_group_slug,
    version_groups.name AS version_group_name,
    games.generation_id,
    generations.slug AS generation_slug,
    generations.name AS generation_name,
    mainline_team_plans.status_id,
    mainline_team_plan_statuses.slug AS status_slug,
    mainline_team_plan_statuses.name AS status_name,
    mainline_team_plans.notes,
    mainline_team_plans.created_at,
    mainline_team_plans.updated_at,
    (
        SELECT
            COUNT(
                *
)
        FROM
            planning.mainline_team_plan_members
        WHERE
            mainline_team_plan_members.team_plan_id = mainline_team_plans.id
) AS member_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            planning.mainline_play_plan_links
        WHERE
            mainline_play_plan_links.team_plan_id = mainline_team_plans.id
) AS linked_play_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            planning.mainline_team_plan_optional_content_scopes
        WHERE
            mainline_team_plan_optional_content_scopes.team_plan_id = mainline_team_plans.id
) AS optional_content_scope_count
FROM
    planning.mainline_team_plans
    JOIN planning.mainline_team_plan_statuses ON mainline_team_plan_statuses.id = mainline_team_plans.status_id
    JOIN reference.games ON games.id = mainline_team_plans.game_id
    JOIN reference.version_groups ON version_groups.id = mainline_team_plans.version_group_id
    JOIN reference.generations ON generations.id = games.generation_id;

COMMENT ON VIEW views.mainline_team_plan_summary IS 'Compact team Plan summary rows with ordered-member and linked-Play counts. Uses security_invoker so planning RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/010_mainline_team_plan_detail.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_team_plan_detail
-- Ordered planned Pokémon targets with display metadata and planned moves.
-- ============================================================================
CREATE VIEW views.mainline_team_plan_detail WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_team_plan_members.id AS team_plan_member_id,
    mainline_team_plan_members.team_plan_id,
    mainline_team_plans.user_id,
    mainline_team_plan_members.slot,
    mainline_team_plan_members.target_species_id,
    target_species.slug AS target_species_slug,
    target_species.name AS target_species_name,
    target_species.national_number AS target_national_number,
    target_species.evolution_family_id AS target_evolution_family_id,
    mainline_team_plan_members.target_form_id,
    target_forms.slug AS target_form_slug,
    target_forms.name AS target_form_name,
    mainline_team_plan_members.notes,
    mainline_team_plan_members.gender,
    mainline_team_plan_members.nature_id,
    natures.name AS nature_name,
    mainline_team_plan_members.ability_id,
    abilities.name AS ability_name,
    mainline_team_plan_members.held_item_id,
    held_items.name AS held_item_name,
    mainline_team_plan_members.created_at,
    mainline_team_plan_members.updated_at,
    COALESCE(
        moves.moves, '[]'::jsonb
) AS moves
FROM
    planning.mainline_team_plan_members
    JOIN planning.mainline_team_plans ON mainline_team_plans.id = mainline_team_plan_members.team_plan_id
    JOIN reference.pokemon_species AS target_species ON target_species.id = mainline_team_plan_members.target_species_id
    JOIN reference.pokemon_forms AS target_forms ON target_forms.species_id = mainline_team_plan_members.target_species_id
        AND target_forms.id = mainline_team_plan_members.target_form_id
    LEFT JOIN reference.natures ON natures.id = mainline_team_plan_members.nature_id
    LEFT JOIN reference.abilities ON abilities.id = mainline_team_plan_members.ability_id
    LEFT JOIN reference.items AS held_items ON held_items.id = mainline_team_plan_members.held_item_id
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(
                jsonb_build_object(
                    'slot', mainline_team_plan_member_moves.slot, 'move_id', reference_moves.id, 'slug', reference_moves.slug, 'name', reference_moves.name
) ORDER BY mainline_team_plan_member_moves.slot
) AS moves
        FROM
            planning.mainline_team_plan_member_moves
            JOIN reference.moves AS reference_moves ON reference_moves.id = mainline_team_plan_member_moves.move_id
        WHERE
            mainline_team_plan_member_moves.team_plan_member_id = mainline_team_plan_members.id
) AS moves ON TRUE;

COMMENT ON VIEW views.mainline_team_plan_detail IS 'Ordered team Plan members with target identity, optional build preferences, and planned moves. Uses security_invoker so planning RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/011_mainline_collection_used_identities.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_collection_used_identities
-- Normalized Pokémon identities used across current team and history.
-- ============================================================================
CREATE VIEW views.mainline_collection_used_identities WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_plays.user_id,
    mainline_play_pokemon.play_id,
    'mainline_play_pokemon'::text AS source_kind,
    mainline_play_pokemon.id AS source_row_id,
    mainline_play_pokemon.species_id,
    pokemon_species.slug AS species_slug,
    pokemon_species.name AS species_name,
    pokemon_species.national_number,
    pokemon_species.evolution_family_id,
    mainline_play_pokemon.form_id,
    pokemon_forms.slug AS form_slug,
    pokemon_forms.name AS form_name,
    mainline_play_pokemon.created_at AS used_at,
    NULL::uuid AS event_id
FROM
    gameplay.mainline_play_pokemon
    JOIN gameplay.mainline_plays ON mainline_plays.id = mainline_play_pokemon.play_id
    JOIN reference.pokemon_species ON pokemon_species.id = mainline_play_pokemon.species_id
    JOIN reference.pokemon_forms ON pokemon_forms.species_id = mainline_play_pokemon.species_id
        AND pokemon_forms.id = mainline_play_pokemon.form_id
    UNION ALL
    SELECT
        mainline_plays.user_id,
        mainline_play_event_pokemon_refs.play_id,
        'event_pokemon_ref'::text AS source_kind,
        mainline_play_event_pokemon_refs.id AS source_row_id,
        mainline_play_event_pokemon_refs.species_id,
        pokemon_species.slug AS species_slug,
        pokemon_species.name AS species_name,
        pokemon_species.national_number,
        pokemon_species.evolution_family_id,
        mainline_play_event_pokemon_refs.form_id,
        pokemon_forms.slug AS form_slug,
        pokemon_forms.name AS form_name,
        COALESCE(
            mainline_play_events.happened_at, mainline_play_events.created_at
) AS used_at,
        mainline_play_event_pokemon_refs.event_id
    FROM
        gameplay.mainline_play_event_pokemon_refs
    JOIN gameplay.mainline_play_events ON mainline_play_events.id = mainline_play_event_pokemon_refs.event_id
        AND mainline_play_events.play_id = mainline_play_event_pokemon_refs.play_id
    JOIN gameplay.mainline_plays ON mainline_plays.id = mainline_play_event_pokemon_refs.play_id
    JOIN reference.pokemon_species ON pokemon_species.id = mainline_play_event_pokemon_refs.species_id
    JOIN reference.pokemon_forms ON pokemon_forms.species_id = mainline_play_event_pokemon_refs.species_id
        AND pokemon_forms.id = mainline_play_event_pokemon_refs.form_id
    UNION ALL
    SELECT
        mainline_plays.user_id,
        mainline_play_event_team_snapshots.play_id,
        'team_snapshot'::text AS source_kind,
        mainline_play_event_team_snapshots.id AS source_row_id,
        mainline_play_event_team_snapshots.species_id,
        pokemon_species.slug AS species_slug,
        pokemon_species.name AS species_name,
        pokemon_species.national_number,
        pokemon_species.evolution_family_id,
        mainline_play_event_team_snapshots.form_id,
        pokemon_forms.slug AS form_slug,
        pokemon_forms.name AS form_name,
        COALESCE(
            mainline_play_events.happened_at, mainline_play_events.created_at
) AS used_at,
        mainline_play_event_team_snapshots.event_id
    FROM
        gameplay.mainline_play_event_team_snapshots
    JOIN gameplay.mainline_play_events ON mainline_play_events.id = mainline_play_event_team_snapshots.event_id
        AND mainline_play_events.play_id = mainline_play_event_team_snapshots.play_id
    JOIN gameplay.mainline_plays ON mainline_plays.id = mainline_play_event_team_snapshots.play_id
    JOIN reference.pokemon_species ON pokemon_species.id = mainline_play_event_team_snapshots.species_id
    JOIN reference.pokemon_forms ON pokemon_forms.species_id = mainline_play_event_team_snapshots.species_id
        AND pokemon_forms.id = mainline_play_event_team_snapshots.form_id;

COMMENT ON VIEW views.mainline_collection_used_identities IS 'Pokémon identities used across current play Pokémon, event refs, and team snapshots. event_id names the History moment for event refs and snapshots. Uses security_invoker so gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/012_mainline_collection_detail.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_collection_detail
-- Aggregated Pokémon collection/use rows by user and species/form.
-- ============================================================================
CREATE VIEW views.mainline_collection_detail WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_collection_used_identities.user_id,
    mainline_collection_used_identities.species_id,
    mainline_collection_used_identities.species_slug,
    mainline_collection_used_identities.species_name,
    mainline_collection_used_identities.national_number,
    mainline_collection_used_identities.evolution_family_id,
    mainline_collection_used_identities.form_id,
    mainline_collection_used_identities.form_slug,
    mainline_collection_used_identities.form_name,
    COUNT(
        *
) AS usage_event_count,
    COUNT(
        DISTINCT mainline_collection_used_identities.play_id
) AS play_count,
    MIN(
        mainline_collection_used_identities.used_at
) AS first_used_at,
    MAX(
        mainline_collection_used_identities.used_at
) AS last_used_at
FROM
    views.mainline_collection_used_identities
GROUP BY
    mainline_collection_used_identities.user_id,
    mainline_collection_used_identities.species_id,
    mainline_collection_used_identities.species_slug,
    mainline_collection_used_identities.species_name,
    mainline_collection_used_identities.national_number,
    mainline_collection_used_identities.evolution_family_id,
    mainline_collection_used_identities.form_id,
    mainline_collection_used_identities.form_slug,
    mainline_collection_used_identities.form_name;

COMMENT ON VIEW views.mainline_collection_detail IS 'Aggregated Pokémon usage by user and species/form. Uses security_invoker so underlying gameplay RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/013_mainline_dashboard_summary.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_dashboard_summary
-- One-row dashboard counters per authenticated user profile.
-- ============================================================================
CREATE VIEW views.mainline_dashboard_summary WITH ( security_invoker = TRUE
) AS
SELECT
    profiles.id AS user_id,
    profiles.display_name,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.user_id = profiles.id
            AND mainline_plays.archived_at IS NULL
) AS active_library_play_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.user_id = profiles.id
) AS total_play_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_plays
            JOIN gameplay.mainline_play_statuses ON mainline_play_statuses.id = mainline_plays.status_id
        WHERE
            mainline_plays.user_id = profiles.id
            AND mainline_play_statuses.slug = 'completed'
) AS completed_play_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            planning.mainline_team_plans
        WHERE
            mainline_team_plans.user_id = profiles.id
) AS team_plan_count,
    (
        SELECT
            COUNT(
                DISTINCT mainline_collection_detail.species_id
)
        FROM
            views.mainline_collection_detail
        WHERE
            mainline_collection_detail.user_id = profiles.id
) AS used_species_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            views.mainline_collection_detail
        WHERE
            mainline_collection_detail.user_id = profiles.id
) AS used_form_count,
    (
        SELECT
            MAX(
                updated_at
)
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.user_id = profiles.id
) AS last_play_updated_at
FROM
    public.profiles;

COMMENT ON VIEW views.mainline_dashboard_summary IS 'Dashboard counters scoped by profile ownership. Uses security_invoker so public/gameplay/planning RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/014_mainline_stats_summary.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_stats_summary
-- User-level aggregate stats across mainline_plays, plans, and Pokémon usage.
-- ============================================================================
CREATE VIEW views.mainline_stats_summary WITH ( security_invoker = TRUE
) AS
SELECT
    profiles.id AS user_id,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.user_id = profiles.id
) AS total_play_count,
    (
        SELECT
            COUNT(
                DISTINCT mainline_plays.game_id
)
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.user_id = profiles.id
) AS played_game_count,
    (
        SELECT
            COUNT(
                DISTINCT games.generation_id
)
        FROM
            gameplay.mainline_plays
            JOIN reference.games ON games.id = mainline_plays.game_id
        WHERE
            mainline_plays.user_id = profiles.id
) AS played_generation_count,
    (
        SELECT
            COALESCE(
                SUM(
                    mainline_plays.playtime_minutes
), 0
)
        FROM
            gameplay.mainline_plays
        WHERE
            mainline_plays.user_id = profiles.id
) AS total_playtime_minutes,
    (
        SELECT
            COUNT(
                *
)
        FROM
            planning.mainline_team_plans
        WHERE
            mainline_team_plans.user_id = profiles.id
) AS total_team_plan_count,
    (
        SELECT
            COUNT(
                DISTINCT mainline_collection_detail.species_id
)
        FROM
            views.mainline_collection_detail
        WHERE
            mainline_collection_detail.user_id = profiles.id
) AS used_species_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            views.mainline_collection_detail
        WHERE
            mainline_collection_detail.user_id = profiles.id
) AS used_form_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_play_events
            JOIN gameplay.mainline_plays ON mainline_plays.id = mainline_play_events.play_id
        WHERE
            mainline_plays.user_id = profiles.id
) AS timeline_event_count,
    (
        SELECT
            COUNT(
                *
)
        FROM
            gameplay.mainline_play_milestone_progress
            JOIN gameplay.mainline_plays ON mainline_plays.id = mainline_play_milestone_progress.play_id
        WHERE
            mainline_plays.user_id = profiles.id
) AS completed_milestone_count
FROM
    public.profiles;

COMMENT ON VIEW views.mainline_stats_summary IS 'User-level aggregate stats. Uses security_invoker so public/gameplay/planning RLS applies to the caller.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/015_reference_content_scope_closure.sql
-- ============================================================================
-- ============================================================================
-- View: views.reference_content_scope_closure
-- Canonical parent/dependency closure for cumulative reference content scopes.
-- ============================================================================
CREATE VIEW views.reference_content_scope_closure WITH ( security_invoker = TRUE
) AS
WITH RECURSIVE dependency_edges AS (
    SELECT
        version_groups.id AS version_group_id,
        version_groups.parent_version_group_id AS required_version_group_id
    FROM
        reference.version_groups
    WHERE
        version_groups.parent_version_group_id IS NOT NULL
    UNION ALL
    SELECT
        content_scope_dependencies.version_group_id,
        content_scope_dependencies.required_version_group_id
    FROM
        reference.content_scope_dependencies
),
content_scope_closure AS (
    SELECT
        version_groups.id AS target_version_group_id,
        version_groups.id AS included_version_group_id,
        0 AS depth,
        ARRAY[version_groups.id] AS visited_version_group_ids
    FROM
        reference.version_groups
    UNION ALL
    SELECT
        content_scope_closure.target_version_group_id,
        dependency_edges.required_version_group_id AS included_version_group_id,
        content_scope_closure.depth + 1 AS depth,
        content_scope_closure.visited_version_group_ids || dependency_edges.required_version_group_id
    FROM
        content_scope_closure
        JOIN dependency_edges ON dependency_edges.version_group_id = content_scope_closure.included_version_group_id
    WHERE
        dependency_edges.required_version_group_id <> ALL (content_scope_closure.visited_version_group_ids)
),
deduped_closure AS (
    SELECT
        content_scope_closure.target_version_group_id,
        content_scope_closure.included_version_group_id,
        MIN(content_scope_closure.depth) AS depth
    FROM
        content_scope_closure
    GROUP BY
        content_scope_closure.target_version_group_id,
        content_scope_closure.included_version_group_id
)
SELECT
    deduped_closure.target_version_group_id,
    target_version_groups.slug AS target_version_group_slug,
    deduped_closure.included_version_group_id,
    included_version_groups.slug AS included_version_group_slug,
    deduped_closure.depth,
    ROW_NUMBER() OVER (PARTITION BY deduped_closure.target_version_group_id ORDER BY CASE WHEN included_version_groups.parent_version_group_id IS NULL THEN
            0
        ELSE
            1
        END, included_version_groups.sort_order, included_version_groups.id) AS resolution_order
FROM
    deduped_closure
    JOIN reference.version_groups AS target_version_groups ON target_version_groups.id = deduped_closure.target_version_group_id
    JOIN reference.version_groups AS included_version_groups ON included_version_groups.id = deduped_closure.included_version_group_id;

-- ============================================================================
-- Source: database/schema/06_views/01_views/016_reference_resolved_pokemon_availability.sql
-- ============================================================================
-- ============================================================================
-- View: views.reference_resolved_pokemon_availability
-- Effective Pokémon availability after applying cumulative content scopes.
-- ============================================================================
CREATE VIEW views.reference_resolved_pokemon_availability WITH ( security_invoker = TRUE
) AS
WITH ranked_rows AS (
    SELECT
        content_scope_closure.target_version_group_id,
        pokemon_availability.version_group_id AS source_version_group_id,
        pokemon_availability.id,
        pokemon_availability.species_id,
        pokemon_availability.form_id,
        pokemon_availability.game_id,
        pokemon_availability.availability_method_id,
        pokemon_availability.scope_operation,
        pokemon_availability.notes,
        pokemon_availability.created_at,
        ROW_NUMBER() OVER (PARTITION BY content_scope_closure.target_version_group_id,
            pokemon_availability.species_id,
            pokemon_availability.form_id,
            COALESCE(pokemon_availability.game_id, 0),
            pokemon_availability.availability_method_id ORDER BY content_scope_closure.resolution_order DESC,
            pokemon_availability.id DESC) AS resolution_rank
    FROM
        views.reference_content_scope_closure AS content_scope_closure
        JOIN reference.pokemon_availability ON pokemon_availability.version_group_id = content_scope_closure.included_version_group_id
)
SELECT
    ranked_rows.target_version_group_id,
    ranked_rows.source_version_group_id,
    ranked_rows.id,
    ranked_rows.species_id,
    ranked_rows.form_id,
    ranked_rows.game_id,
    ranked_rows.availability_method_id,
    ranked_rows.notes,
    ranked_rows.created_at
FROM
    ranked_rows
WHERE
    ranked_rows.resolution_rank = 1
    AND ranked_rows.scope_operation <> 'remove';

-- ============================================================================
-- Source: database/schema/06_views/01_views/017_reference_resolved_move_availability.sql
-- ============================================================================
-- ============================================================================
-- View: views.reference_resolved_move_availability
-- Effective move availability after applying cumulative content scopes.
-- ============================================================================
CREATE VIEW views.reference_resolved_move_availability WITH ( security_invoker = TRUE
) AS
WITH ranked_rows AS (
    SELECT
        content_scope_closure.target_version_group_id,
        move_availability.version_group_id AS source_version_group_id,
        move_availability.id,
        move_availability.move_id,
        move_availability.game_id,
        move_availability.scope_operation,
        move_availability.created_at,
        ROW_NUMBER() OVER (PARTITION BY content_scope_closure.target_version_group_id,
            move_availability.move_id,
            COALESCE(move_availability.game_id, 0) ORDER BY content_scope_closure.resolution_order DESC,
            move_availability.id DESC) AS resolution_rank
    FROM
        views.reference_content_scope_closure AS content_scope_closure
        JOIN reference.move_availability ON move_availability.version_group_id = content_scope_closure.included_version_group_id
)
SELECT
    ranked_rows.target_version_group_id,
    ranked_rows.source_version_group_id,
    ranked_rows.id,
    ranked_rows.move_id,
    ranked_rows.game_id,
    ranked_rows.created_at
FROM
    ranked_rows
WHERE
    ranked_rows.resolution_rank = 1
    AND ranked_rows.scope_operation <> 'remove';

-- ============================================================================
-- Source: database/schema/06_views/01_views/018_reference_resolved_item_availability.sql
