-- ============================================================================
-- Source: database/schema/06_views/01_views/019_reference_resolved_move_machines.sql
-- ============================================================================
-- ============================================================================
-- View: views.reference_resolved_move_machines
-- Effective TM/HM/TR catalog after applying cumulative content scopes.
-- ============================================================================
CREATE VIEW views.reference_resolved_move_machines WITH ( security_invoker = TRUE
) AS
WITH ranked_rows AS (
    SELECT
        content_scope_closure.target_version_group_id,
        move_machines.version_group_id AS source_version_group_id,
        move_machines.id,
        move_machines.move_id,
        move_machines.game_id,
        move_machines.learn_method_id,
        move_machines.machine_label,
        move_machines.scope_operation,
        move_machines.sort_order,
        move_machines.created_at,
        ROW_NUMBER() OVER (PARTITION BY content_scope_closure.target_version_group_id,
            COALESCE(move_machines.game_id, 0),
            move_machines.learn_method_id,
            move_machines.machine_label ORDER BY content_scope_closure.resolution_order DESC,
            move_machines.sort_order DESC,
            move_machines.id DESC) AS resolution_rank
    FROM
        views.reference_content_scope_closure AS content_scope_closure
        JOIN reference.move_machines ON move_machines.version_group_id = content_scope_closure.included_version_group_id
)
SELECT
    ranked_rows.target_version_group_id,
    ranked_rows.source_version_group_id,
    ranked_rows.id,
    ranked_rows.move_id,
    ranked_rows.game_id,
    ranked_rows.learn_method_id,
    ranked_rows.machine_label,
    ranked_rows.sort_order,
    ranked_rows.created_at
FROM
    ranked_rows
WHERE
    ranked_rows.resolution_rank = 1
    AND ranked_rows.scope_operation <> 'remove';

-- ============================================================================
-- Source: database/schema/06_views/01_views/020_reference_resolved_pokemon_learnsets.sql
-- ============================================================================
-- ============================================================================
-- View: views.reference_resolved_pokemon_learnsets
-- Effective Pokémon learnsets after applying cumulative content scopes.
-- ============================================================================
CREATE VIEW views.reference_resolved_pokemon_learnsets WITH ( security_invoker = TRUE
) AS
WITH ranked_rows AS (
    SELECT
        content_scope_closure.target_version_group_id,
        pokemon_learnsets.version_group_id AS source_version_group_id,
        pokemon_learnsets.id,
        pokemon_learnsets.species_id,
        pokemon_learnsets.form_id,
        pokemon_learnsets.move_id,
        pokemon_learnsets.game_id,
        pokemon_learnsets.learn_method_id,
        pokemon_learnsets.level_learned_at,
        pokemon_learnsets.source_item_id,
        pokemon_learnsets.move_machine_id,
        move_machines.machine_label,
        pokemon_learnsets.condition_summary,
        pokemon_learnsets.scope_operation,
        pokemon_learnsets.sort_order,
        pokemon_learnsets.created_at,
        ROW_NUMBER() OVER (PARTITION BY content_scope_closure.target_version_group_id,
            pokemon_learnsets.species_id,
            pokemon_learnsets.form_id,
            pokemon_learnsets.move_id,
            COALESCE(pokemon_learnsets.game_id, 0),
            pokemon_learnsets.learn_method_id,
            COALESCE(pokemon_learnsets.level_learned_at, 0),
            COALESCE(pokemon_learnsets.source_item_id, 0),
            COALESCE(move_machines.machine_label, 'no-machine'),
            COALESCE(pokemon_learnsets.condition_summary, '') ORDER BY content_scope_closure.resolution_order DESC,
            pokemon_learnsets.sort_order DESC,
            pokemon_learnsets.id DESC) AS resolution_rank
    FROM
        views.reference_content_scope_closure AS content_scope_closure
        JOIN reference.pokemon_learnsets ON pokemon_learnsets.version_group_id = content_scope_closure.included_version_group_id
        LEFT JOIN reference.move_machines ON move_machines.id = pokemon_learnsets.move_machine_id
)
SELECT
    ranked_rows.target_version_group_id,
    ranked_rows.source_version_group_id,
    ranked_rows.id,
    ranked_rows.species_id,
    ranked_rows.form_id,
    ranked_rows.move_id,
    ranked_rows.game_id,
    ranked_rows.learn_method_id,
    ranked_rows.level_learned_at,
    ranked_rows.source_item_id,
    ranked_rows.move_machine_id,
    ranked_rows.machine_label,
    ranked_rows.condition_summary,
    ranked_rows.sort_order,
    ranked_rows.created_at
FROM
    ranked_rows
WHERE
    ranked_rows.resolution_rank = 1
    AND ranked_rows.scope_operation <> 'remove';

-- ============================================================================
-- Source: database/schema/06_views/01_views/021_mainline_play_milestone_category_summary.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_milestone_category_summary
-- Milestone category progress counts available to each play.
-- ============================================================================
CREATE VIEW views.mainline_play_milestone_category_summary WITH ( security_invoker = TRUE
) AS
WITH play_scopes AS (
    SELECT
        mainline_plays.id AS play_id,
        mainline_plays.user_id,
        mainline_plays.game_id,
        mainline_plays.version_group_id,
        game_content_scopes.sort_order AS content_scope_sort_order
    FROM
        gameplay.mainline_plays
        JOIN reference.game_content_scopes ON game_content_scopes.game_id = mainline_plays.game_id
            AND game_content_scopes.version_group_id = mainline_plays.version_group_id
        UNION ALL
        SELECT
            mainline_play_optional_content_scopes.play_id,
            mainline_plays.user_id,
            mainline_play_optional_content_scopes.game_id,
            mainline_play_optional_content_scopes.version_group_id,
            game_content_scopes.sort_order AS content_scope_sort_order
        FROM
            gameplay.mainline_play_optional_content_scopes
        JOIN gameplay.mainline_plays ON mainline_plays.id = mainline_play_optional_content_scopes.play_id
        JOIN reference.game_content_scopes ON game_content_scopes.game_id = mainline_play_optional_content_scopes.game_id
            AND game_content_scopes.version_group_id = mainline_play_optional_content_scopes.version_group_id
),
category_counts AS (
    SELECT
        play_scopes.play_id,
        play_scopes.user_id,
        play_scopes.game_id,
        games.slug AS game_slug,
        games.name AS game_name,
        play_scopes.version_group_id,
        version_groups.slug AS version_group_slug,
        version_groups.name AS version_group_name,
        version_groups.is_open_world,
        play_scopes.content_scope_sort_order,
        mainline_categories.id AS category_id,
        mainline_categories.slug AS category_slug,
        mainline_categories.name AS category_name,
        mainline_categories.category_kind,
        mainline_categories.sort_order AS category_sort_order,
        COUNT(mainline_milestones.id) AS milestone_count,
        COUNT(mainline_milestones.id) FILTER (WHERE mainline_milestones.is_required_for_completion) AS required_milestone_count,
        COUNT(mainline_milestones.id) FILTER (WHERE NOT mainline_milestones.is_required_for_completion) AS optional_milestone_count,
        COUNT(mainline_play_milestone_progress.milestone_id) AS completed_milestone_count,
        COUNT(mainline_play_milestone_progress.milestone_id) FILTER (WHERE mainline_milestones.is_required_for_completion) AS completed_required_milestone_count,
        COUNT(mainline_play_milestone_progress.milestone_id) FILTER (WHERE NOT mainline_milestones.is_required_for_completion) AS completed_optional_milestone_count
    FROM
        play_scopes
    JOIN reference.games ON games.id = play_scopes.game_id
    JOIN reference.version_groups ON version_groups.id = play_scopes.version_group_id
    JOIN tracking.mainline_categories ON mainline_categories.version_group_id = play_scopes.version_group_id
        LEFT JOIN tracking.mainline_milestones ON mainline_milestones.version_group_id = mainline_categories.version_group_id
            AND mainline_milestones.category_id = mainline_categories.id
            AND (mainline_milestones.game_id IS NULL
                OR mainline_milestones.game_id = play_scopes.game_id)
        LEFT JOIN gameplay.mainline_play_milestone_progress ON mainline_play_milestone_progress.play_id = play_scopes.play_id
            AND mainline_play_milestone_progress.milestone_id = mainline_milestones.id
    GROUP BY
        play_scopes.play_id,
        play_scopes.user_id,
        play_scopes.game_id,
        games.slug,
        games.name,
        play_scopes.version_group_id,
        version_groups.slug,
        version_groups.name,
        version_groups.is_open_world,
        play_scopes.content_scope_sort_order,
        mainline_categories.id,
        mainline_categories.slug,
        mainline_categories.name,
        mainline_categories.category_kind,
        mainline_categories.sort_order
)
SELECT
    category_counts.play_id,
    category_counts.user_id,
    category_counts.game_id,
    category_counts.game_slug,
    category_counts.game_name,
    category_counts.version_group_id,
    category_counts.version_group_slug,
    category_counts.version_group_name,
    category_counts.is_open_world,
    category_counts.content_scope_sort_order,
    category_counts.category_id,
    category_counts.category_slug,
    category_counts.category_name,
    category_counts.category_kind,
    category_counts.category_sort_order,
    category_counts.milestone_count,
    category_counts.required_milestone_count,
    category_counts.completed_required_milestone_count,
    CASE WHEN category_counts.required_milestone_count = 0 THEN
        0
    ELSE
        ROUND((category_counts.completed_required_milestone_count::numeric * 100) / category_counts.required_milestone_count, 2)
    END AS required_milestone_completion_percent,
    category_counts.optional_milestone_count,
    category_counts.completed_optional_milestone_count,
    category_counts.completed_milestone_count,
    CASE WHEN category_counts.milestone_count = 0 THEN
        0
    ELSE
        ROUND((category_counts.completed_milestone_count::numeric * 100) / category_counts.milestone_count, 2)
    END AS all_milestone_completion_percent,
    CASE WHEN category_counts.required_milestone_count > 0 THEN
        'required'
    WHEN category_counts.optional_milestone_count > 0 THEN
        'optional'
    ELSE
        'empty'
    END AS completion_scope
FROM
    category_counts;

COMMENT ON VIEW views.mainline_play_milestone_category_summary IS 'Per-play milestone category progress counts for Story UI sections. Required completion uses milestone-level is_required_for_completion; optional rows remain visible without contributing to play completion.';

-- ============================================================================
-- Source: database/schema/06_views/01_views/022_mainline_play_team_plan_detail.sql
-- ============================================================================
-- ============================================================================
-- View: views.mainline_play_team_plan_detail
-- Play-scoped reusable Plan context and ordered planned members.
-- ============================================================================
CREATE VIEW views.mainline_play_team_plan_detail WITH ( security_invoker = TRUE
) AS
SELECT
    mainline_play_plan_links.id AS play_plan_link_id,
    mainline_play_plan_links.play_id,
    mainline_play_plan_links.team_plan_id,
    mainline_play_plan_links.user_id,
    mainline_play_plan_links.game_id,
    games.slug AS game_slug,
    games.name AS game_name,
    mainline_play_plan_links.version_group_id,
    version_groups.slug AS version_group_slug,
    version_groups.name AS version_group_name,
    games.generation_id,
    generations.slug AS generation_slug,
    generations.name AS generation_name,
    mainline_play_plan_links.created_from_plan,
    mainline_play_plan_links.created_at AS linked_plan_at,
    mainline_team_plans.name AS team_plan_name,
    mainline_team_plans.status_id AS team_plan_status_id,
    team_plan_statuses.slug AS team_plan_status_slug,
    team_plan_statuses.name AS team_plan_status_name,
    mainline_team_plans.notes AS team_plan_notes,
    mainline_team_plans.updated_at AS team_plan_updated_at,
    linked_plays.linked_play_count,
    mainline_team_plan_members.id AS team_plan_member_id,
    mainline_team_plan_members.slot,
    mainline_team_plan_members.target_species_id,
    target_species.slug AS target_species_slug,
    target_species.name AS target_species_name,
    target_species.national_number AS target_national_number,
    target_species.evolution_family_id AS target_evolution_family_id,
    mainline_team_plan_members.target_form_id,
    target_forms.slug AS target_form_slug,
    target_forms.name AS target_form_name,
    mainline_team_plan_members.notes AS team_plan_member_notes,
    mainline_team_plan_members.gender AS planned_gender,
    mainline_team_plan_members.nature_id AS planned_nature_id,
    planned_natures.name AS planned_nature_name,
    mainline_team_plan_members.ability_id AS planned_ability_id,
    planned_abilities.name AS planned_ability_name,
    mainline_team_plan_members.held_item_id AS planned_held_item_id,
    planned_held_items.name AS planned_held_item_name,
    COALESCE(
        moves.moves, '[]'::jsonb
) AS planned_moves
FROM
    planning.mainline_play_plan_links
    JOIN planning.mainline_team_plans ON mainline_team_plans.id = mainline_play_plan_links.team_plan_id
    JOIN planning.mainline_team_plan_statuses AS team_plan_statuses ON team_plan_statuses.id = mainline_team_plans.status_id
    JOIN reference.games ON games.id = mainline_play_plan_links.game_id
    JOIN reference.version_groups ON version_groups.id = mainline_play_plan_links.version_group_id
    JOIN reference.generations ON generations.id = games.generation_id
    LEFT JOIN planning.mainline_team_plan_members ON mainline_team_plan_members.team_plan_id = mainline_team_plans.id
    LEFT JOIN reference.pokemon_species AS target_species ON target_species.id = mainline_team_plan_members.target_species_id
    LEFT JOIN reference.pokemon_forms AS target_forms ON target_forms.species_id = mainline_team_plan_members.target_species_id
        AND target_forms.id = mainline_team_plan_members.target_form_id
    LEFT JOIN reference.natures AS planned_natures ON planned_natures.id = mainline_team_plan_members.nature_id
    LEFT JOIN reference.abilities AS planned_abilities ON planned_abilities.id = mainline_team_plan_members.ability_id
    LEFT JOIN reference.items AS planned_held_items ON planned_held_items.id = mainline_team_plan_members.held_item_id
    LEFT JOIN LATERAL (
        SELECT
            COUNT(
                *
) AS linked_play_count
        FROM
            planning.mainline_play_plan_links AS plan_usage
        WHERE
            plan_usage.team_plan_id = mainline_team_plans.id
) AS linked_plays ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            jsonb_agg(
                jsonb_build_object(
                    'slot', mainline_team_plan_member_moves.slot, 'move_id', reference_moves.id, 'slug', reference_moves.slug, 'name', reference_moves.name
) ORDER BY mainline_team_plan_member_moves.slot
) AS moves
        FROM
            planning.mainline_team_plan_member_moves
            JOIN reference.moves AS reference_moves ON reference_moves.id = mainline_team_plan_member_moves.move_id
        WHERE
            mainline_team_plan_member_moves.team_plan_member_id = mainline_team_plan_members.id
) AS moves ON TRUE;

COMMENT ON VIEW views.mainline_play_team_plan_detail IS 'Play-scoped reusable Plan context and ordered planned members. Automatic comparison with current and historical Play Pokémon is derived by the application at read time.';

